window.PACK={"book":{"id":"diwan-hassan","title":"ديوان حسان بن ثابت","type":"diwan","author":"حسان بن ثابت (ت ٥٤هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"mukhadram","packVersion":"1e8cb3ddca1e"},"items":[{"id":"diwan-hassan:1","bookId":"diwan-hassan","type":"poem","seq":1,"chapter":"مقدمة","title":"عنوان القصيدة : عفت ذات الأصابع فالجواء","page":"","text":"عفت ذات الأصابع فالجواء،\nإلى عذراء منزلها خلاء\nديار من بني الحسحاس قفر،\nتعفيها الروامس والسماء\nوكانت لا يزال بها أنيس،\nخلال مروجها نعم وشاء\nفدع هذا، ولكن من لطيف،\nيؤرقني إذا ذهب العشاء\nلشعثاء التي قد تيمته،\nفليس لقلبه منها شفاء\nكأن سبيئة من بيت رأس،\nيكون مزاجها عسل وماء\nعلى أنيابها، أو طعم غض\nمن التفاح هصره الجناء\nإذا ما الأسربات ذكرن يوما،\nفهن لطيب الراح الفداء\nنوليها الملامة ، إن ألمنا،\nإذا ما كان مغث أو لحاء\nونشربها فتتركنا ملوكا،\nوأسدا ما ينهنهنا اللقاء\nعدمنا خيلنا، إن لم تروها\nتثير النقع، موعدها كداء\nيبارين الأعنة مصعدات،\nعلى أكتافها الأسل الظماء\nتظل جيادنا متمطرات،\nتلطمهن بالخمر النساء\nفإما تعرضوا عنا اعتمرنا،\nوكان الفتح، وانكشف الغطاء\nوإلا، فاصبروا لجلاد يوم،\nيعز الله فيه من يشاء\nوجبريل أمين الله فينا،\nوروح القدس ليس له كفاء\nوقال الله: قد أرسلت عبدا\nيقول الحق إن نفع البلاء\nشهدت به، فقوموا صدقوه!\nفقلتم: لا نقوم ولا نشاء\nوقال الله: قد يسرت جندا،\nهم الأنصار، عرضتها اللقاء\nلنا في كل يوم من معد\nسباب، أو قتال، أو هجاء\nفنحكم بالقوافي من هجانا،\nونضرب حين تختلط الدماء\nألا أبلغ أبا سفيان عني،\nفأنت مجوف نخب هواء\nوأن سيوفنا تركتك عبدا\nوعبد الدار سادتها الإماء\nكأن سبيئة من بيت رأس،\nتعفيها الروامس والسماء\nهجوت محمدا، فأجبت عنه،\nوعند الله في ذاك الجزاء\nأتهجوه، ولست له بكفء،\nفشركما لخيركما الفداء\nهجوت مباركا، برا، حنيفا،\nأمين الله، شيمته الوفاء\nفمن يهجو رسول الله منكم،\nويمدحه، وينصره سواء\nفإن أبي ووالده وعرضي\nلعرض محمد منكم وقاء\nفإما تثقفن بنو لؤي\nجذيمة ، إن قتلهم شفاء\nأولئك معشر نصروا علينا،\nففي أظفارنا منهم دماء\nوحلف الحارث بن أبي ضرار،\nوحلف قريظة منا براء\nلساني صارم لا عيب فيه،\nوبحري لا تكدره الدلاء"},{"id":"diwan-hassan:2","bookId":"diwan-hassan","type":"poem","seq":2,"chapter":"مقدمة","title":"عنوان القصيدة : وأحسن منك لم تر قط عيني","page":"ج1 ص1","text":"وأحسن منك لم تر قط عيني\nوأجمل منك لم تلد النساء\nخلقت مبرأ من كل عيب\nكأنك قد خلقت كما تشاء"},{"id":"diwan-hassan:3","bookId":"diwan-hassan","type":"poem","seq":3,"chapter":"قافية الباء","title":"عنوان القصيدة : هل رسم دارسة المقام، يباب","page":"ج1 ص2","text":"هل رسم دارسة المقام، يباب\nمتكلك لمسائل بجواب\nولقد رأيت بها الحلول يزينهم\nبيض الوجوه ثواقب الأحساب\nفدع الديار وذكر كل خريدة\nبيضاء، آنسة الحديث، كعاب\nواشك الهموم إلى الإله وما ترى\nمن معشر متألبين غضاب\nأموا بغزوهم الرسول، وألبوا\nأهل القرى ، وبوادي الأعراب\nجيش، عيينة وابن حرب فيهم،\nمتخمطين بحلبة الأحزاب\nحتى إذا وردوا المدينة وارتجوا\nقتل النبي ومغنم الأسلاب\nوغدوا علينا قادرين بأيدهم،\nردوا بغيظهم على الأعقاب\nبهبوب معصفة تفرق جمعهم،\nوجنود ربك سيد الأرباب\nوكفى الإله المؤمنين قتالهم\nوأثابهم في الأجر خير ثواب\nمن بعد ما قنطوا، ففرج عنهم\nتنزيل نص مليكنا الوهاب\nوأقر عين محمد وصحابه،\nوأذل كل مكذب مرتاب\nمستشعر للكفر دون ثيابه،\nوالكفر ليس بطاهر الأثواب\nعلق الشقاء بقلبه، فأرانه\nفي الكفر آخر هذه الأحقاب"},{"id":"diwan-hassan:4","bookId":"diwan-hassan","type":"poem","seq":4,"chapter":"قافية الباء","title":"عنوان القصيدة : عرفت ديار زينب بالكثيب","page":"ج1 ص3","text":"عرفت ديار زينب بالكثيب\nكخط الوحي في الرق القشيب\nتعاورها الرياح وكل جون\nمن الوسمي منهمر سكوب\nفأمسى رسمها خلقا، وأمست\nيبابا بعد ساكنها الحبيب\nفدع عنك التذكر كل يوم،\nورد حرارة الصدر الكئيب\nوخبر بالذي لا عيب فيه،\nبصدق، غير إخبار الكذوب\nبما صنع المليك غداة بدر\nلنا في المشركين من النصيب\nغداة كأن جمعهم حراء\nبدت أركانه جنح الغروب\nفوافيناهم منا بجمع\nكأسد الغاب: مردان وشيب\nأمام محمد قد آزروه\nعلى الأعداء في لفح الحروب\nبأيديهم صوارم مرهفات\nوكل مجرب خاظي الكعوب\nبنو الأوس الغطارف آزرتها\nبنو النجار في الدين الصليب\nفغادرنا أبا جهل صريعا\nوعتبة قد تركنا بالجبوب\nوشيبة قد تركنا في رجال\nذوي حسب، إذا نسبوا، نسيب\nيناديهم رسول الله، لما\nقذفناهم كباكب في القليب\nألم تجدو حديثي كان حقا،\nوأمر الله يأخذ بالقلوب\nفما نطقوا، ولو نطقوا لقالوا:\nصدقت وكنت ذا رأي مصيب"},{"id":"diwan-hassan:5","bookId":"diwan-hassan","type":"poem","seq":5,"chapter":"قافية الباء","title":"عنوان القصيدة : تطاول بالجمان ليلي فلم تكن","page":"ج1 ص4","text":"تطاول بالجمان ليلي فلم تكن\nتهم هوادي نجمه أن تصوبا\nأبيت أراعيها كأنيموكل\nبها لا أريد النوم حتى تغيبا\nإذا غار منها كوكب بعد كوكب\nتراقب عيني آخر الليل كوكبا\nغوائر تترى من نجوم تخالها\nمع الصبح تتلوها زواحف لغبا\nأخاف مفاجاة الفراق ببغتة ،\nوصرف النوى من أن تشت وتشعبا\nوأيقنت لما قوض الحي خيمهم\nبروعات بين تترك الرأس أشيبا\nوأسمعك الداعي الفصيح بفرقة ،\nوقد جنحت شمس النهار لتغربا\nوبين في صوت الغراب اغترابهم،\nعشية أوفى غصن بان، فطربا\nوفي الطير بالعلياء إذ عرضت لنا،\nوما الطير إلا أن تمر وتنعبا\nوكدت غداة البعين يغلبني الهوى ،\nأعالج نفسي أن أقوم فأركبا\nوكيف ولا ينسى التصابي بعدما\nتجاوز رأس الأربعين وجربا\nوقد بان ما يأتي من الأمر، واكتست\nمفارقه لونا من الشيب مغربا\nأتجمع شوقا إن تراخت بها النوى\nوصدا، إذا ما أسقبت، وتجنبا\nإذا أنبت أسباب الهوى ، وتصدعت\nعصا البين لم تسطع لشعثاء مطلبا\nوكيف تصدي المرء ذي اللب للصبا،\nوليس بمعذور، إذا ما تطربا\nأطيل اجتنابا عنهم، غير بغضة\nولكن بقيا رهبة وتصحبا\nألا لا أرى جارا يعلل نفسه\nمطاعا، ولا جارا لشعثاء معتبا"},{"id":"diwan-hassan:6","bookId":"diwan-hassan","type":"poem","seq":6,"chapter":"قافية الباء","title":"عنوان القصيدة : إن تمس دار ابن أروى منه خالية","page":"ج1 ص5","text":"إن تمس دار ابن أروى منه خالية\nباب صريع وباب مخرق، خرب\nفقد يصادف باغي الخير حاجته\nفيها ويأوي إليها الذكر والحسب\nيا أيها الناس أبدوا ذات أنفسكم،\nلا يستوي الصدق عند الله والكذب\nإلا تنيبوا لأمر الله تعترفوا\nبغارة عصب من خلفها عصب\nفيهم حبيب شهاب الحرب يقدمهم\nمستلئما قد بدا في وجهه الغضب"},{"id":"diwan-hassan:7","bookId":"diwan-hassan","type":"poem","seq":7,"chapter":"قافية الباء","title":"عنوان القصيدة : ما نقمتم من ثياب خلفة","page":"ج1 ص6","text":"ما نقمتم من ثياب خلفة\nوعبيد، وإماء، وذهب\nقلتم بدل، فقد بدلكم\nسنة حرى ، وحربا كاللهب\nففريق هالك من عجف،\nوفريق كان أودى ، فذهب\nإذ قتلتم ماجدا ذا مرة\nواضح السنة معروف النسب"},{"id":"diwan-hassan:8","bookId":"diwan-hassan","type":"poem","seq":8,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا عضل سيقت إلينا كأنهم","page":"ج1 ص7","text":"إذا عضل سيقت إلينا كأنهم\nجداية شرك، معلمات الحواجب\nأقمنا لكم طعنا مبيرا، منكلا،\nوحزناكم بالضرب من كل جانب\nولولا لواء الحارثية أصبحوا\nيباعون في الأسواق بيع الجلائب\nيمصون أرصاف السهام، كأنهم\nإذا هبطوا سهلا وبار شوازب\nنفجيء عنا الناس حتى كأنما\nيلفحهم جمر من النار ثاقب"},{"id":"diwan-hassan:9","bookId":"diwan-hassan","type":"poem","seq":9,"chapter":"قافية الباء","title":"عنوان القصيدة : صلى الإله على الذين تتابعوا","page":"ج1 ص8","text":"صلى الإله على الذين تتابعوا\nيوم الرجيع، فأكرموا وأثيبوا\nرأس الكتيبة مرثد وأميرهم\nزابن البكير أمامهم وخبيب\nوابن لطارق، وابن دثنة فيهم\nوافاه ثم حمامه المكتوب\nمنع المقادة أن ينالوا ظهره\nحتى يجالد، إنه لنجيب\nوالعاصم المقتول عند رجيعهم\nكسب المعالي، إنه لكسوب"},{"id":"diwan-hassan:10","bookId":"diwan-hassan","type":"poem","seq":10,"chapter":"قافية الباء","title":"عنوان القصيدة : إني حلفت يمينا غير كاذبة","page":"ج1 ص9","text":"إني حلفت يمينا غير كاذبة ،\nلو كان للحارث الجفني أصحاب\nمن جذم غسان مسترخ حمائلهم،\nلا يغبقون من المعزى ، إذا آبوا\nولا يذادون محمرا عيونهم،\nإذا تحضر عند الماجد الباب\nكانوا إذا حضروا شيب العقار لهم،\nوطيف فيهم بأكواس وأكواب\nإذا لآبوا جميعا، أو لكان لهم\nأسرى من القوم أو قتلى وأسلاب\nلجالدوا حيث كان الموت أدركهم\nحتى يثوبوا لهم أسرى وأسلاب\nلكنه إنما لاقى بمأشبة\nليس لهم عند يوم البأس أحساب"},{"id":"diwan-hassan:11","bookId":"diwan-hassan","type":"poem","seq":11,"chapter":"قافية الباء","title":"عنوان القصيدة : قالت له يوما تخاطبه","page":"ج1 ص10","text":"قالت له يوما تخاطبه\nنفج الحقيبة ، غادة الصلب\nأما الوسامة والمروءة ، أو\nرأي الرجال فقد بداء، حسبي\nفوددت أنك لو تخبرنا\nمن والداك، ومنصب الشعب\nفضحكت ثم رفعت متصلا\nصوتي أوان المنطق الشغب\nجدي أبو ليلى ، ووالده\nعمرو، وأخوالي بنو كعب\nوأنا من القوم الذين، إذا\nأزم الشتاء محالف الجدب\nأعطى ذوو الأموال معسرهم،\nوالضاربين بموطن الرعب"},{"id":"diwan-hassan:12","bookId":"diwan-hassan","type":"poem","seq":12,"chapter":"قافية الباء","title":"عنوان القصيدة : قد تعفى بعدنا عاذب","page":"ج1 ص11","text":"قد تعفى بعدنا عاذب\nما به باد ولا قارب\nغيرته الريح تسفي به،\nوهزيم رعده واصب\nولقد كانت تكون به\nطفلة ،ممكورة ، كاعب\nوكلت قلبي بذكرتها،\nفالهوى لي فادح، غالب\nليس لي منها مؤاس، ولا\nبد مما يجلب الجالب\nوكأني، حين أذكرها،\nمن حميا قهوة شارب\nأكعهدي هضب ذي نفر،\nفلوى الأعراف، فالضارب\nفلوى الخربة ، إذ أهلنا،\nكل ممسى ، سامر، لاعب\nفابك ما شئت على ما انقضى ،\nكل وصل منقض ذاهب\nلو يرد الدمع شيئا لقد\nرد شيئا دمعك الساكب\nلم تكن سعدى لتنصفني\nقلما ينصفني الصاحب\nكأخ لي لا أعاتبه\nوبما يستكثر العاتب\nحدث الشاهد من قوله\nبالذي يخفي لنا الغائب\nوبدت منه مزملة ،\nحلمه في غيها ذاهب"},{"id":"diwan-hassan:13","bookId":"diwan-hassan","type":"poem","seq":13,"chapter":"قافية الباء","title":"عنوان القصيدة : إذن والله نرميهم بحرب","page":"ج1 ص12","text":"إذن والله نرميهم بحرب\nتشيب الطفل من قبل المشيب"},{"id":"diwan-hassan:14","bookId":"diwan-hassan","type":"poem","seq":14,"chapter":"قافية الباء","title":"عنوان القصيدة : وفجعنا فيروز لا در دره","page":"ج1 ص13","text":"وفجعنا فيروز لا در دره\nبأبيض يتلو المحكمات منيب\nرؤوف على الأدنى ، غليظ على العدا\nأخي ثقة في النائبات، نجيب\nمتى ما يقل لا يكذب القول فعله\nسريع إلى الخيرات غير قطوب"},{"id":"diwan-hassan:15","bookId":"diwan-hassan","type":"poem","seq":15,"chapter":"قافية الباء","title":"عنوان القصيدة : وغبنا فلم تشهد ببطحاء مكة","page":"ج1 ص14","text":"وغبنا فلم تشهد ببطحاء مكة\nرجال بني كعب تحز رقابها\nبأيدي رجال لم يسلوا سيوفهم\nبحق، وقتلى لم تجن ثيابها\nفيا ليت شعري! هل تنالن نصرتي\nسهيل بن عمرو، وخزها وعقابها\nوصفوان عودا حز من شفر استه\nفهذا أوان الحرب شد عصابها\nفلا تأمننا، يا ابن أم مجالد\nإذا لقحت حرب وأعصل نابها\nولو شهد البطحاء منا عصابة\nلهان علينا، يوم ذاك، ضرابها"},{"id":"diwan-hassan:16","bookId":"diwan-hassan","type":"poem","seq":16,"chapter":"قافية الباء","title":"عنوان القصيدة : يا حار، قد عولت، غير معول","page":"ج1 ص15","text":"يا حار، قد عولت، غير معول،\nعند الهياج وساعة الأحساب\nإذ تمتطي سرج اليدين نجيبة\nمرطى الجراء، خفيفة الأقراب\nوالقوم خلفك قد تركت قتالهم،\nترجو النجاء، فليس حين ذهاب\nهلا عطفت على ابن أمك إذ ثوى\nقعص الأسنة ، ضائع الأسلاب\nجهما لعمرك لو دهيت بمثلها\nلأتاك أخثم شابك الأنياب\nعجل المليك له، فأهلك جمعه\nبشنار مخزية ، وسوء عذاب\nلو كنت ضنء كريمة أبليتها\nحسنى ، ولكن ضنء بنت عقاب"},{"id":"diwan-hassan:17","bookId":"diwan-hassan","type":"poem","seq":17,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا نسبت يوما قريش نفتكم","page":"ج1 ص16","text":"إذا نسبت يوما قريش نفتكم،\nوإن تنتسب شجع فأنت نسيبها\nوإن التي ألقتك من تحت رجلها،\nوليدا، لمهجان الغذاء خبوبها\nوأمك من قسر، حباشة أمها،\nلسمراء فهم، آسن البول طيبها"},{"id":"diwan-hassan:18","bookId":"diwan-hassan","type":"poem","seq":18,"chapter":"قافية الباء","title":"عنوان القصيدة : يا حار قد كنت لولا ما رميت به","page":"ج1 ص17","text":"يا حار قد كنت لولا ما رميت به،\nلله درك، في عز وفي حسب\nجللت قومك مخزاة ومنقصة ،\nما لم يجلله حي من العرب\nيا سالب البيت ذي الأركان حليته\nأد الغزال، فلن يخفى لمستلب\nسائل بني الحارث المزري بمعشره:\nأين الغزال عليه الدر من ذهب؟\nبئس البنون وبئس الشيخ شيخهم\nتبا لذلك من شيخ ومن عقب"},{"id":"diwan-hassan:19","bookId":"diwan-hassan","type":"poem","seq":19,"chapter":"قافية الباء","title":"عنوان القصيدة : يا عين جودي بدمع منك منسكب","page":"ج1 ص18","text":"يا عين جودي بدمع منك منسكب،\nوابكي خبيبا مع الغادين لم يؤب\nصقرا توسط في الأنصار منصبه،\nحلو السجية ، محضا غير مؤتشب\nقد هاج عيني على علات عبرتها،\nإذ قيل نص على جذع من الخشب\nيا أيها الراكب الغادي لطيته،\nأبلغ لديك وعيدا ليس بالكذب\nبني فكيهة ، إن الحرب قد لقحت\nمحلوبها الصاب، إذ تمرى لمحتلب\nفيها أسود بني النجار يقدمهم\nشهب الأسنة في معصوصب لجب"},{"id":"diwan-hassan:20","bookId":"diwan-hassan","type":"poem","seq":20,"chapter":"قافية الباء","title":"عنوان القصيدة : بنى اللؤم بيتا على مذحج","page":"ج1 ص19","text":"بنى اللؤم بيتا على مذحج،\nفكان على مذحج ترتبا\nولو جمعت ما حوت مذحج\nمن المجد ما أثقل الأرنبا"},{"id":"diwan-hassan:21","bookId":"diwan-hassan","type":"poem","seq":21,"chapter":"قافية الباء","title":"عنوان القصيدة : من مبلغ صفوان أن عجوزه","page":"ج1 ص20","text":"من مبلغ صفوان أن عجوزه\nأمة لجارة معمر بن حبيب\nأمة يقال من البراجم أصلها،\nنسب من الأنساب غير قريب\nلولا السفار وبعد خرق مهمه،\nلتركتها تحبو على العرقوب"},{"id":"diwan-hassan:22","bookId":"diwan-hassan","type":"poem","seq":22,"chapter":"قافية الباء","title":"عنوان القصيدة : فلا والله ما تدري هذيل","page":"ج1 ص21","text":"فلا والله ما تدري هذيل\nأمحض ماء زمزم أم مشوب\nوما لهم إذا اعتمروا وحجوا\nمن الحجرين والمسعى نصيب\nولكن الرجيع لهم محل،\nبه اللؤم المبين والعيوب\nهم غروا بذمتهم خبيبا،\nقبئس لعهد عهدهم الكذوب\nتحوزهم وتدفعهم علي،\nفقد عاشوا وليس لهم قلوب"},{"id":"diwan-hassan:23","bookId":"diwan-hassan","type":"poem","seq":23,"chapter":"قافية الباء","title":"عنوان القصيدة : مزينة لا يرى فيها خطيب","page":"ج1 ص22","text":"مزينة لا يرى فيها خطيب،\nولا فلج يطاف به خصيب\nولا من يملأ الشيزى ، ويحمي،\nإذا ما الكلب أحجره الضريب\nرجال تهلكث الحسنات فيهم\nيرون التيس كالفرس النجيب"},{"id":"diwan-hassan:24","bookId":"diwan-hassan","type":"poem","seq":24,"chapter":"قافية الباء","title":"عنوان القصيدة : متى تنسب قريش، أو تحصل","page":"ج1 ص23","text":"متى تنسب قريش، أو تحصل،\nفما لك في أرومتها نصاب\nنفتك بنو هصيص عن أبيها،\nلشجع حيث تسترق العياب\nوأنت، ابن المغيرة ، عبد شول\nقد اندب حبل عاتقك الوطاب\nإذا عد الأطايب من قريش،\nتلاقت دون نسبتكم كلاب\nوعمران بن مخزوم فدعها،\nهناك السر والحسب اللباب"},{"id":"diwan-hassan:25","bookId":"diwan-hassan","type":"poem","seq":25,"chapter":"قافية الباء","title":"عنوان القصيدة : سالت هذيل رسول الله فاحشة","page":"ج1 ص24","text":"سالت هذيل رسول الله فاحشة ،\nضلت هذيل بما جاءت ولم تصب"},{"id":"diwan-hassan:26","bookId":"diwan-hassan","type":"poem","seq":26,"chapter":"قافية الباء","title":"عنوان القصيدة : يا حار إن كنت أمرأ متوسعا","page":"ج1 ص25","text":"يا حار إن كنت أمرأ متوسعا\nفافد الألى ينصفن آل جناب\nأخوات أمك قد علمت مكانها،\nوالحق يفهمه ذوو الألباب\nأن الفرافصة بن الأحوص عنده\nشجن لأمك من بنات عقاب\nأجمعت أنك أنت ألأم من مشى\nفي فحش مومسة وزهو غراب\nوكذاك ورثك الأوائل أنهم\nذهبوا وصرت بخزية وعذاب\nفورثت والدك الخيانة والخنا،\nواللؤم عند تقايس الأحساب\nوأبان لؤمك أن أمك لم تكن\nإلا لشر مقارف الأعراب"},{"id":"diwan-hassan:27","bookId":"diwan-hassan","type":"poem","seq":27,"chapter":"قافية الباء","title":"عنوان القصيدة : أبوك أبوك، وأنت ابنه","page":"ج1 ص26","text":"أبوك أبوك، وأنت ابنه\nفبئس البني وبئس الأب\nوأمك سوداء مودونة\nكأن أناملها الحنظب\nيبيت أبوك بها معرسا،\nكما ساور الهوة الثعلب\nفما منك أعجب يا ابن استها،\nولكنني من أولى أعجب\nإذا سمعوا الغي آدوا له،\nتيوس تنب إذا تضر\nترى التيس عندهم كالجواد،\nبل التيس وسطهم أنجب\nفلا تدعهم لقراع الكماة ،\nوناد إلى سوءة يركبوا"},{"id":"diwan-hassan:28","bookId":"diwan-hassan","type":"poem","seq":28,"chapter":"قافية الباء","title":"عنوان القصيدة : فخرتم باللواء، وشر فخر","page":"ج1 ص27","text":"فخرتم باللواء، وشر فخر\nلواء حين رد إلى صواب\nجعلتم فخركم فيه لعبد،\nمن الأم من يطا عفر التراب\nحسبتم، والسفيه أخو ظنون،\nوذلك ليس من أمر الصواب\nبأن لقاءنا إذ حان يوم\nبمكة بيعكم حمر العياب"},{"id":"diwan-hassan:29","bookId":"diwan-hassan","type":"poem","seq":29,"chapter":"قافية الباء","title":"عنوان القصيدة : سائل قريشا وأحلافها","page":"ج1 ص28","text":"سائل قريشا وأحلافها\nمتى كان عوف لها ينسب\nأفيما مضى نسب ثابت\nفيعلم أم دعوة تكذب\nفإن قريشا ستنفيكم\nإلى نسب، غيره أثقب\nإلى جذم قين لئيم العرو\nق عرقوب والده أصهب\nإلى تغلب إنهم شر جيل،\nفليس لكم غيرهم مذهب\nوقد كان عهدي بها لم تنل\nسنيا ولا شرفا تغلب"},{"id":"diwan-hassan:30","bookId":"diwan-hassan","type":"poem","seq":30,"chapter":"قافية الباء","title":"عنوان القصيدة : ذكرت القروم الصيد من آل هاشم","page":"ج1 ص29","text":"ذكرت القروم الصيد من آل هاشم،\nولست لزور قلته بمصيب\nأتعجب أن أقصدت حمزة منهم،\nنجيبا، وقد سميته بنجيب\nألم يقتلوا عمرا وعتبة وابنه\nوشيبة والحجاج وابن حبيب\nغداة دعا العاصي عليا، فراعه\nبضربة عضب بله بخضيب"},{"id":"diwan-hassan:31","bookId":"diwan-hassan","type":"poem","seq":31,"chapter":"قافية الباء","title":"عنوان القصيدة : لعمرك ما أوصى أمية بكره","page":"ج1 ص30","text":"لعمرك ما أوصى أمية بكره\nبوصية أوصى بها يعقوب\nأوصاهم، لما تولى مدبرا،\nبخطيئة عند الإله وحوب\nأبني! إن حاولتم أن تسرقوا،\nفخذوا معاول، كلها مثقوب\nوأتوا بيوت الناس من أدبارها،\nحتى تصير وكلهن مجوب"},{"id":"diwan-hassan:32","bookId":"diwan-hassan","type":"poem","seq":32,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا أبلغا عني أسيدا رسالة","page":"ج1 ص31","text":"ألا أبلغا عني أسيدا رسالة ،\nفخالك عبد بالشراب مجرب\nلعمروك ما أوفى أسيد لجاره\nولا خالد، وابن المفاضة زينب\nوعتاب عبد غير موف بذمة ،\nكذوب شؤون الرأس قرد مؤدب"},{"id":"diwan-hassan:33","bookId":"diwan-hassan","type":"poem","seq":33,"chapter":"قافية الباء","title":"عنوان القصيدة : رقاق النعال طيب حجزاتهم","page":"ج1 ص32","text":"رقاق النعال طيب حجزاتهم،\n-\nتحييهم بيض الولائد بينهم،\nوأكسية الاضريج فوق المشاجب\nيصونون أجسادا، قديما نعيمها،\nبخالصة الأردان، خضر المناكب\nولا يحسبون الخير لا شر بعده،\nولا يحسبون الشر ضربة لازب\nحبوت بها غسان إذ كنت لاحقا\nبقومي، وإذ أعيت علي مذاهبي"},{"id":"diwan-hassan:34","bookId":"diwan-hassan","type":"poem","seq":34,"chapter":"قافية الباء","title":"عنوان القصيدة : لما رأتني أم عمرو صدفت","page":"ج1 ص33","text":"لما رأتني أم عمرو صدفت،\nقد بلعت بي ذرأة ، فألحفت"},{"id":"diwan-hassan:35","bookId":"diwan-hassan","type":"poem","seq":35,"chapter":"قافية الباء","title":"عنوان القصيدة : من للقوافي بعد حسان وابنه","page":"ج1 ص34","text":"من للقوافي بعد حسان وابنه،\nومن للمثاني بعد زيد بن ثابت"},{"id":"diwan-hassan:36","bookId":"diwan-hassan","type":"poem","seq":36,"chapter":"قافية الباء","title":"عنوان القصيدة : نجى حكيما يوم بدر ركضه","page":"ج1 ص35","text":"نجى حكيما يوم بدر ركضه\nكنجاء مهر من بنات الأعوج\nألقى السلاح وفر عنها مهملا\nكالهبرزي يزل فوق المنسج\nلما رأى بدرا تسيل جلاهها\nبكتائب ملأوس أو ملخزرج\nصبر يساقون الكماة حتوفها،\nيمشون مهيعة الطريق المنهج\nكم فيهم من ماجد ذي سورة ،\nبطل بمكرهة المكان المحرج\nومسود يعطي الجزيل بكفه،\nحمال أثقال الديات، متوج\nأو كل أروع ماجد ذي مرة ،\nأو كل مسترخي النجاد مدجج\nونجا ابن حمراء العجان حويرث،\nيغلي الدماغ به كغلي الزبرج"},{"id":"diwan-hassan:37","bookId":"diwan-hassan","type":"poem","seq":37,"chapter":"قافية الباء","title":"عنوان القصيدة : طويل النجاد، رفيع العماد","page":"ج1 ص36","text":"طويل النجاد، رفيع العماد،\nمصاص النجار من الخزرج"},{"id":"diwan-hassan:38","bookId":"diwan-hassan","type":"poem","seq":38,"chapter":"قافية الباء","title":"عنوان القصيدة : أبلغ ربيعة وابن أمه نوفلا","page":"ج1 ص37","text":"أبلغ ربيعة وابن أمه نوفلا\nأني مصيب العظم، إن لم أصفح\nوكأنني رئبال غاب ضيغم،\nيقرو الأماعز بالفجاج الأفيح\nغرثت حليلته، وأرمل ليلة ،\nفكأنه غضبان ما لم يجرح\nفتخاله حسان، إذ حربته،\nفدع الفضاء إلى مضيقك وافسح\nإن الخيانة ، والمغالة ، والخنا،\nواللؤم أصبح ثاويا بالأبطح\nقوم، إذا نطق الخنا ناديهم،\nتبع الخنا، وأضيع أمر المصلح\nواشتق عند الحجر كل مزلج،\nإلا يصح عند المقالة ينبح"},{"id":"diwan-hassan:39","bookId":"diwan-hassan","type":"poem","seq":39,"chapter":"قافية الباء","title":"عنوان القصيدة : يا دوس، إن أبا أزيهر أصبحت","page":"ج1 ص38","text":"يا دوس، إن أبا أزيهر أصبحت\nأصداؤه رهن المضيح، فاقدحي\nحربا يشيب لها الوليد، وإنما\nيأتي الدنية كل عبد نحنج\nفابكي أخاك بكل أسمر ذابل،\nوبكل أبيض كالعقيقة ، مصفح\nوبكل صافية الأديم، كأنها\nفتخاء كاسرة تدف وتطمح\nوطمرة مرطى الجراء، كأنها\nسيد، بمقفرة ، وسهب أفيح\nإن تقتلوا مائة به، فدنية\nبأبي أزيهر من رجال الأبطح"},{"id":"diwan-hassan:40","bookId":"diwan-hassan","type":"poem","seq":40,"chapter":"قافية الباء","title":"عنوان القصيدة : خابت بنو أسد وآب عزيزهم","page":"ج1 ص39","text":"خابت بنو أسد وآب عزيزهم،\nيوم القليب، بسوءة وفضوح\nمنهم أبو العاصي تجدل، مقعصا،\nعن ظهر صادقة النجاء سبوح\nوالمرء رمعة قد تركن ونحره\nيدمى بعاند معبط مسفوح\nونجا ابن قيس في بقية قومه،\nقد عر مارن أنفه بقيوح"},{"id":"diwan-hassan:41","bookId":"diwan-hassan","type":"poem","seq":41,"chapter":"قافية الباء","title":"عنوان القصيدة : ما سبني العوام إلا لأنه","page":"ج1 ص40","text":"ما سبني العوام إلا لأنه\nأخو سمك في البحر جار التماسح\nلئيم دني فاحش وابن فاحش،\nلئيم العروق أصله متنازح\nله خمرة في بيته وجريرة\nيبيع فيها فهو نشوان سالح"},{"id":"diwan-hassan:42","bookId":"diwan-hassan","type":"poem","seq":42,"chapter":"قافية الباء","title":"عنوان القصيدة : أغر، عليه للنبوة خاتم","page":"ج1 ص41","text":"أغر، عليه للنبوة خاتم\nمن الله مشهود يلوح ويشهد\nوضم الإله اسم النبي إلى اسمه،\nإذا قال في الخمس المؤذن أشهد\nوشق له من اسمه ليجله،\nفذو العرش محمود، وهذا محمد\nنبي أتانا بعد يأس وفترة\nمن الرسل، والأوثان في الأرض تعبد\nفأمسى سراجا مستنيرا وهاديا،\nيلوح كما لاح الصقيل المهند\nوأنذرنا نارا، وبشر جنة ،\nوعلمنا الإسلام، فالله نحمد\nوأنت إله الخلق ربي وخالقي،\nبذلك ما عمرت فيا لناس أشهد\nتعاليت رب الناس عن قول من دعا\nسواك إلها، أنت أعلى وأمجد\nلك الخلق والنعماء، والأمر كله،\nفإياك نستهدي، وإياك نعبد"},{"id":"diwan-hassan:43","bookId":"diwan-hassan","type":"poem","seq":43,"chapter":"قافية الباء","title":"عنوان القصيدة : مستشعري حلق الماذي يقدمهم","page":"ج1 ص42","text":"مستشعري حلق الماذي يقدمهم\nجلد النحيزة ، ماض، غير رعديد\nأعني الرسول، فإن الله فضله\nعلى البرية بالتقوى ، وبالجود\nوقد زعمتم بأن تحموا ذماركم،\nوماء بدر زعمتم غير مورود\nوقد وردنا ولم نسمع لقولكم\nحتى شربنا رواء، غير تصريد\nمستعصمين بحبل غير منجذم،\nمستحم من حبال الله ممدود\nفينا الرسول وفينا الحق نتبعه\nحتى الممات، ونصر غير محدود\nماض على الهول، ركاب لما قطعوا،\nإذا الكماة تحاموا في الصناديد\nواف، وماض، شهاب يستضاء به،\nبدر أنار على كل الأماجيد\nمبارك، كضياء البدر صورته،\nما قال كان قضاء غير مردود"},{"id":"diwan-hassan:44","bookId":"diwan-hassan","type":"poem","seq":44,"chapter":"قافية الباء","title":"عنوان القصيدة : والله ربي لا نفارق ماجدا","page":"ج1 ص43","text":"والله ربي لا نفارق ماجدا،\nعف الخليقة ، ماجد الأجداد\nمتكرما يدعو إلى رب العلى ،\nبذل النصيحة رافع الأعماد\nمثل الهلال مباركا، ذا رحمة ،\nسمح الخليقة ، طيب الأعواد\nإن تتركوه، فإن ربي قادر،\nأمسى يعود بفضله العواد\nوالله ربي لا نفارق أمره،\nما كان عيش يرتجى لمعاد\nلا نبتغي ربا سواه ناصرا،\nحتى نوافي ضحوة الميعاد"},{"id":"diwan-hassan:45","bookId":"diwan-hassan","type":"poem","seq":45,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد خاب قوم غاب عنهم نبيهم","page":"ج1 ص44","text":"لقد خاب قوم غاب عنهم نبيهم،\nوقدس من يسري إليهم ويغتدي\nترحل عن قوم فضلت عقولهم،\nوحل على قوم بنور مجدد\nهداهم به بعد الضلالة ربهم،\nوأرشدهم، من يتبع الحق يرشد\nوهل يستوي ضلال قوم تسفهوا\nعمى ، وهداة يهتدون بمهتد؟\nلقد نزلت منه على اهل يثرب\nركاب هدى ، حلت عليهم بأسعد\nنبي يرى ما لا يرى الناس حوله،\nويتلو كتاب اله في كل مسجد\nوإن قال في يوم مقالة غائب،\nفتصديقها في اليوم أو في ضحى الغد\nليهن أبا بكر سعادة جده\nبصحبته، من يسعد الله يسعد"},{"id":"diwan-hassan:46","bookId":"diwan-hassan","type":"poem","seq":46,"chapter":"قافية الباء","title":"عنوان القصيدة : ألم تر أن الغدر واللؤم والخنا","page":"ج1 ص45","text":"ألم تر أن الغدر واللؤم والخنا\nبنى مسكنا بين المعين إلى عرد\nفغزة ، فالمروت، فالخبت، فالمنى ،\nإلى بيت زماراء، تلدا على تلد\nفقلت ولم أملك: أعمرو بن عامر\nلفرخ بني العنقاء يقتل بالعبد\nلقد شاب رأسي، أو دنا لمشيبه،\nوما عتقت سعد بن زر ولا هند"},{"id":"diwan-hassan:47","bookId":"diwan-hassan","type":"poem","seq":47,"chapter":"قافية الباء","title":"عنوان القصيدة : بطيبة رسم للرسول ومعهد","page":"ج1 ص46","text":"بطيبة رسم للرسول ومعهد\nمنير، وقد تعفو الرسوم وتهمد\nولا تنمحي الآيات من دار حرمة\nبها منبر الهادي الذي كان يصعد\nوواضح آيات، وباقي معالم،\nوربع له فيه مصلى ومسجد\nبها حجرات كان ينزل وسطها\nمن الله نور يستضاء، ويوقد\nمعالم لم تطمس على العهد آيها\nأتاها البلى ، فالآي منها تجدد\nعرفت بها رسم الرسول وعهده،\nوقبرا به واراه في الترب ملحد\nظللت بها أبكي الرسول، فأسعدت\nعيون، ومثلاها من الجفن تسعد\nتذكر آلاء الرسول، وما أرى\nلها محصيا نفسي، فنفسي تبلد\nمفجعة قد شفها فقد أحمد،\nفظلت لآلاء الرسول تعدد\nوما بلغت من كل أمر عشيره،\nولكن نفسي بعض ما فيه تحمد\nأطالت وقوفا تذرف العين جهدها\nعلى طلل القبر الذي فيه أحمد\nفبوركت، يا قبر الرسول، وبوركت\nبلاد ثوى فيها الرشيد المسدد\nوبورك لحد منك ضمن طيبا،\nعليه بناء من صفيح، منضد\nتهيل عليه الترب أيد وأعين\nعليه، وقد غارت بذلك أسعد\nلقد غيبوا حلما وعلما ورحمة ،\nعشية علوه الثرى ، لا يوسد\nوراحوا بحزن ليس فيهم نبيهم،\nوقد وهنت منهم ظهور، وأعضد\nيبكون من تبكي السموات يومه،\nومن قد بكته الأرض فالناس أكمد\nوهل عدلت يوما رزية هالك\nرزية يوم مات فيه محمد\nتقطع فيه منزل الوحي عنهم،\nوقد كان ذا نور، يغور وينجد\nيدل على الرحمن من يقتدي به،\nوينقذ من هول الخزايا ويرشد\nإمام لهم يهديهم الحق جاهدا،\nمعلم صدق، إن يطيعوه يسعدوا\nعفو عن الزلات، يقبل عذرهم،\nوإن يحسنوا، فالله بالخير أجود\nوإن ناب أمر لم يقوموا بحمده،\nفمن عنده تيسير ما يتشدد\nفبينا هم في نعمة الله بينهم\nدليل به نهج الطريقة يقصد\nعزيز عليه أن يحيدوا عن الهدى ،\nحريص على أن يستقيموا ويهتدوا\nعطوف عليهم، لا يثني جناحه\nإلى كنف يحنو عليهم ويمهد\nفبينا هم في ذلك النور، إذ غدا\nإلى نورهم سهم من الموت مقصد\nفأصبح محمودا إلى الله راجعا،\nيبكيه جفن المرسلات ويحمد\nوأمست بلاد الحرم وحشا بقاعها،\nلغيبة ما كانت من الوحي تعهد\nقفارا سوى معمورة اللحد ضافها\nفقيد، يبكيه بلاط وغرقد\nومسجده، فالموحشات لفقده،\nخلاء له فيه مقام ومقعد\nوبالجمرة الكبرى له ثم أوحشت\nديار، وعرصات، وربع، ومولد\nفبكي رسول الله يا عين عبرة\nولا أعرفنك الدهر دمعك يجمد\nومالك لا تبكين ذا النعمة التي\nعلى الناس منها سابغ يتغمد\nفجودي عليه بالدموع وأعولي\nلفقد الذي لا مثله الدهريوجد\nوما فقد الماضون مثل محمد،\nولا مثله، حتى القيامة ، يفقد\nأعف وأوفى ذمة بعد ذمة ،\nوأقرب منه نائلا، لا ينكد\nوأبذل منه للطريف وتالد،\nإذا ضن معطاء بما كان يتلد\nوأكرم حيا في البيوت، إذا انتمى ،\nوأكرم جدا أبطحيا يسود\nوأمنع ذروات، وأثبت في العلى\nدعائم عز شاهقات تشيد\nوأثبت فرعا في الفروع ومنبتا،\nوعودا غداة المزن، فالعود أغيد\nرباه وليدا، فاستتم تمامه\nعلى أكرم الخيرات، رب ممجد\nتناهت وصاة المسلمين بكفه،\nفلا العلم محبوس، ولا الرأي يفند\nأقول، ولا يلفى لقولي عائب\nمن الناس، إلا عازب العقل مبعد\nوليس هوائي نازعا عن ثنائه،\nلعلي به في جنة الخلد أخلد\nمع المصطفى أرجو بذاك جواره،\nوفي نيل ذاك اليوم أسعى وأجهد"},{"id":"diwan-hassan:48","bookId":"diwan-hassan","type":"poem","seq":48,"chapter":"قافية الباء","title":"عنوان القصيدة : ما بال عينك لا تنام كأنما","page":"ج1 ص47","text":"ما بال عينك لا تنام كأنما\nكحلت مآقيها بكحل الأرمد\nجزعا على المهدي، أصبح ثاويا،\nيا خير من وطىء الحصى لا تبعد\nجنبي يقيك الترب لهفي ليتني\nغيبت قبلك في بقيع الغرقد\nبأبي وأمي من شهدت وفاته\nفي يوم الاثنين النبي المهتدي\nفظللت بعد وفاته متبلدا،\nيالهف نفسي ليتني لم أولد\nأأقيم بعدك بالمدينة بينهم؟\nيا ليتني صبحت سم الأسود\nأو حل أمر الله فينا عاجلا\nفي روحة من يومنا أو في غد\nفتقوم ساعتنا، فنلقى طيبا\nمحضا ضرائبه كريم المحتد\nيا بكر آمنة المبارك ذكره،\nولدتك محصنة بسعد الأسعد\nنورا أضاء على البرية كلها،\nمن يهد للنور المبارك يهتد\nيا رب! فاجمعنا فما ونبينا،\nفي جنة تثني عيون الحسد\nفي جنة الفردوس واكتبها لنا\nيا ذا الجلال وذا العلا والسؤدد\nوالله أسمع ما بقيت بهالك\nإلا بكيت على النبي محمد\nيا ويح أنصار النبي ورهطه،\nبعد المغيب في سواء الملحد\nضاقت بالأنصار البلاد فأصبحت\nسودا وجوههم كلون الإثمد\nولقد ولدناه، وفينا قبره،\nوفضول نعمته بنا لم يجحد\nوالله أكرمنا به وهدى به\nأنصاره في كل ساعة مشهد\nصلى الإله ومن يحف بعرشه\nوالطيبون على المبارك أحمد\nفرحت نصارى يثرب ويهودها\nلما توارى في الضريح الملحد"},{"id":"diwan-hassan:49","bookId":"diwan-hassan","type":"poem","seq":49,"chapter":"قافية الباء","title":"عنوان القصيدة : آليت ما في جميع الناس مجتهدا","page":"ج1 ص48","text":"آليت ما في جميع الناس مجتهدا،\nمني ألية بر، غير إفناد\nتالله ما حملت أنثى ، ولا وضعت\nمثل النبي، رسول الرحمة الهادي\nولا برا الله خلقا من بريته\nأوفى بذمة جار، أو بميعاد\nمن الذي كان نورا يستضاء به،\nمبارك الأمر ذا عدل وإرشاد\nمصدقا للنبيين الألى سلفوا،\nوأبذل الناس للمعروف للجادي\nيا أفضل الناس، إني كنت في نهر\nأصبحت منه كمثل المفرد الصادي\nأمسى نساؤك عطلن البيوت، فما\nيضربن فوق قفا ستر بأوتاد\nمثل الرواهب يلبسن المسوح، وقد\nأيقن بالبؤس بعد النعمة البادي"},{"id":"diwan-hassan:50","bookId":"diwan-hassan","type":"poem","seq":50,"chapter":"قافية الباء","title":"عنوان القصيدة : متى يبد في الداجي البهيم جبينه","page":"ج1 ص49","text":"متى يبد في الداجي البهيم جبينه\nيلح مثل مصباح الدجى المتوقد\nفمن كان أو من يكون كأحمد\nنظام لحق، أو نكال لملحد"},{"id":"diwan-hassan:51","bookId":"diwan-hassan","type":"poem","seq":51,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا دفنتم رسول الله في سفط","page":"ج1 ص50","text":"ألا دفنتم رسول الله في سفط\nمن الألوة والكافور منضود"},{"id":"diwan-hassan:52","bookId":"diwan-hassan","type":"poem","seq":52,"chapter":"قافية الباء","title":"عنوان القصيدة : أتركتم غزو الدروب وجئتم","page":"ج1 ص51","text":"أتركتم غزو الدروب وجئتم\nلقتال قوم عند قبر محمد\nفلبئس هدي الصالحين هديتم،\nولبئس فعل الجاهل المتعمد\nإن تقبلوا نجعل قرى سرواتكم\nحول المدينة كل لدن مذود\nأو تدبروا، فلبئس ما سافرتم،\nولمثل أمر إمامكم لم يهتد\nوكأن أصحاب النبي، عشية ،\nبدن تنحر عند باب المسجد\nفابك أبا عمرو لحسن بلائه،\nأمسى مقيما في بقيع الغرقد"},{"id":"diwan-hassan:53","bookId":"diwan-hassan","type":"poem","seq":53,"chapter":"قافية الباء","title":"عنوان القصيدة : ماذا أردتم من أخي الخير باركت","page":"ج1 ص52","text":"ماذا أردتم من أخي الخير باركت\nيد الله في ذاك الأديم المقدد\nقتلتم ولي الله في جوف داره،\nوجئتم بأمر جائر غير مهتدي\nفهلا رعيتم ذمة الله وسطكم،\nوأوفيتم بالعهد، عهد محمد\nألم يك فيكم ذا بلاء ومصدق،\nوأوفاكم عهدا لدى كل مشهد\nفلا ظفرت أيمان قوم تظاهرت\nعلى قتل عثمان الرشيد المسدد"},{"id":"diwan-hassan:54","bookId":"diwan-hassan","type":"poem","seq":54,"chapter":"قافية الباء","title":"عنوان القصيدة : أمسى الخلابيس قد عزوا وقد كثروا","page":"ج1 ص53","text":"أمسى الخلابيس قد عزوا وقد كثروا،\nوابن الفريعة أمسى بيضة البلد\nجاءت مزينة من عمق لتحرجني،\nإخسي مزين، وفي أعناقكم قددي\nيمشون بالقول سرا في مهادنة ،\nيهددوني كأني لست من أحد\nقدثكلت أمه من كنت واجده،\nأو كان منتشبا في برثن الأسد\nما البحر حين تهب الريح شامية ،\nفيغطئل ويرمي العبر بالزبد\nيوما بأغلب مني حين تبصرني،\nأفري من الغيظ فري العارض البرد\nما للقتيل الذي أسمو فآخذه\nمن دية فيه يعطاها ولا قود\nأبلغ عبيدا بأني قد تركت له\nمن خير ما يترك الآباء للولد\nالدار واسعة ، والنخل شارعة ،\nوالبيض يرفلن في القسي كالبرد"},{"id":"diwan-hassan:55","bookId":"diwan-hassan","type":"poem","seq":55,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا من مبلغ عني ربيعا","page":"ج1 ص54","text":"ألا من مبلغ عني ربيعا،\nفما أحدثت في الحدثان بعدي\nأبوك أبو الفعال، أبو براء،\nوخالك ماجد حكم بن سعد\nبني أم البنين! ألم يرعكم،\nوأنتم من ذوائب أهل نجد\nتهكم عامر بأبي براء،\nليخفره، وما خطأ كعمد"},{"id":"diwan-hassan:56","bookId":"diwan-hassan","type":"poem","seq":56,"chapter":"قافية الباء","title":"عنوان القصيدة : هل سر أولاد اللقيطة أننا","page":"ج1 ص55","text":"هل سر أولاد اللقيطة أننا\nسلم غداة فوارس المقداد\nكنا ثمانية ، وكانوا جحفلا\nلجبا، فشلوا بالرماح بداد\nلولا الذي لاقت ومس نسورها\nبجنوب ساية أمس بالتقواد\nأفنى دوابرها ولاح متونها،\nيوم تقاد به ويوم طراد\nللقينكم يحملن كل مدجج\nحامي الحقيقة ماجد الأجداد\nكنا من الرسل الذين يلونكم،\nإذ تقذفون عنان كل جواد\nكلا ورب الراقصات إلى منى\nوالجائبين مخارم الأطواد\nحتى نبيل الخيل في عرصاتكم،\nونؤوب بالملكات والأولاد\nزهوا بكل مقلص وطمرة ،\nفي كل معترك عطفن وواد\nكانوا بدار ناعمين فبدلوا،\nأيام ذي قرد، وجوه عباد"},{"id":"diwan-hassan:57","bookId":"diwan-hassan","type":"poem","seq":57,"chapter":"قافية الباء","title":"عنوان القصيدة : انظر خليلي ببطن جلق هل","page":"ج1 ص56","text":"انظر خليلي ببطن جلق هل\nتؤنس، دون البلقاء، من أحد\nجمال شعثاء قد هبطن من ال\nمحبس بين الكثبان، فالسند\nيحملن حوا، حور المدامع في الر\nيط، وبيض الوجوه كالبرد\nمن دون بصرى ، وخلفها جبل الثلج\nج عليه السحاب كالقدد\nإني ورب المخيسات، وما\nيقطعن من كل سربخ جدد\nوالبدن، إذ قربت لمنحرها،\nحلفة بر اليمين مجتهد\nما حلت عن خير ما عهدت، ولا\nأحببت حبي إياك من أحد\nتقول شعثاء: لو تفيق من الكأ\nس لألفيت مثري العدد\nأهوى حديث الندمان في فلق الصب\nح وصوت المسامر الغرد\nيأبى لي السيف واللسان وقو\nم لم يضاموا كلبدة الأسد\nلا أخدش الخدش بالنديم، ولا\nيخشى جليسي إذا انتشيت يدي\nولا نديمي العض البخيل، ولا\nيخاف جاري ما عشت من وبد"},{"id":"diwan-hassan:58","bookId":"diwan-hassan","type":"poem","seq":58,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا أبلغ المستسمعين بوقعة","page":"ج1 ص57","text":"ألا أبلغ المستسمعين بوقعة ،\nتخف لها شمط النساء القواعد\nوظنهم بي أنني لعشيرتي\nعلى أي حال كان حام وذائد\nفإن لم أحقق ظنهم بتيقن،\nفلا سقت الأوصال مني الرواعد\nويعلم أكفائي من الناس أنني\nأنا الفارس الحامي الذمار المناجد\nوما وجد الأعداء في غميزة ،\nولا طاف لي منهم بوحشي صائد\nوأن لم يزل لي منذ أدركت كاشح،\nعدو أقاسيه، وآخر حاسد\nفما منهما إلا وأني أكيله\nبمثل له مثلين، أو أنا زائد\nفإن تسألي الأقوام عني، فإنني\nإلى محتد تنمي إليه المحاتد\nأنا الزائر الصقر ابن سلمى ، وعنده\nأبي، ونعمان، وعمرو، ووافد\nفأورثني مجدا، ومن يجن مثلها\nبحيث اجتناها ينقلب وهو حامد\nوجدي خطيب الناس يوم سميحة ،\nوعمي ابن هند مطعم الطير خالد\nومنا قتيل الشعب أوس بن ثابت،\nشهيدا، وأسنى الذكر منه المشاهد\nومن جده الأدنى أبي، وابن أمه\nلأم أبي ذاك الشهيد المجاهد\nوفي كل دار ربة خزرجية ،\nوأوسية لي في ذراهن والد\nفما أحد منا بمهد لجاره\nأذاة ، ولا مزر به، وهو عائد\nلأنا نرى حق الجوار أمانة ،\nويحفظه منا الكريم المعاهد\nفمهما أقل مما أعدد لم يزل\nعلى صدقه من كل قومي شاهد\nلكل أناس ميسم يعرفونه،\nوميسمنا فينا القوافي الأوابد\nمتى ما نسم لا ينكر الناس وسمنا،\nونعرف به المجهول ممن نكايد\nتلوح به تعشو إليه وسومنا،\nكما لاح في سمر المتان الموارد\nفيشفين من لا يستطاع شفاؤه،\nويبقين ما تبقى الجبال الخوالد\nويشقين من يغتالنا بعداوة ،\nويسعدن في الدنيا بنا من نساعد\nإذا ما كسرنا رمح راية شاعر،\nيجيش بنا ما عندنا فتعاود\nيكون إذ بث الهجاء لقومه\nولاح شهاب من سنا الحرب واقد\nكأشقى ثمود إذ تعطى لحينه،\nعضيلة أم السقب، والسقب وارد\nفولى ، فأوفى عاقلا رأس صخرة\nنمى فرعها، واشتد منها القواعد\nفقال: ألا فاستمتعوا في دياركم\nفقد جاءكم ذكر لكم ومواعد\nثلاثة أيام من الدهر لم يكن\nلهن بتصديق الذي قال رائد"},{"id":"diwan-hassan:59","bookId":"diwan-hassan","type":"poem","seq":59,"chapter":"قافية الباء","title":"عنوان القصيدة : تروح من الحسناء أم أنت مغتدي","page":"ج1 ص58","text":"تروح من الحسناء أم أنت مغتدي،\nوكيف انطلاق عاشق لم يزود\nتراءت لنا يوم الرحيل بمقلتي\nغرير بملتف من السدر مفرد\nوجيد كجيد الرثم صاف، يزينه\nتوقد ياقوت، وفصل زبرجد\nكأن الثريا فوق ثغرة نحرها\nتوقد، في الظلماء، أي توقد\nلها حائطان الموت أسفل منهما\nوجمع متى يصرخ بيثرب يصعد\nترى اللابة السوداء يحمر لونها،\n-\nلعمري لقد حالفت ذبيان كلها\nوعبسا على ما في الأديم الممدد\nوأقبلت من أرض الحجاز بحلبة\nتغم الفضاء كالقطا المتبدد\nتحملت ما كانت مزينة تشتكي\nمن الظلم في الأحلاف حمل التغمد\nأرى كثرة المعروف يورث أهله\nوسود عصر السوء غير المسود\nإذا المرء لم يفضل، ولم يلق نجدة\nمع القوم فليقعد بصغر ويبعد\nوإني لأغنى الناس عن متكلف\nيرى الناس ضلالا وليس بمهتدي\nكثير المنى بالزاد، لا خير عنده\nإذا جاع يوما يشتكيه ضحى الغد\nنشا غمرا، بورا، شقيا، ملعنا،\nألد كأن رأسه رأس أصيد"},{"id":"diwan-hassan:60","bookId":"diwan-hassan","type":"poem","seq":60,"chapter":"قافية الباء","title":"عنوان القصيدة : لعمر أبيك الخير، يا شعث، ما نبا","page":"ج1 ص59","text":"لعمر أبيك الخير، يا شعث، ما نبا\nعلي لساني، في الخطوب، ولا يدي\nلساني وسيفي صارمان كلاهما،\nويبلغ ما لا يبلغ السيف مذودي\nوإن أك ذا مال قليلأجد به،\nوإن يهتصر عودي على الجهد يحمد\nفلا المال ينسيني حيائي وعفتي،\nولا واقعات الدهر يفللن مبردي\nأكثر أهلي من عيال سواهم،\nوأطوي على الماء القراح المبرد\nوإني لمعط ما وجدت، وقائل،\nلموقد ناري ليلة الريح: أوقد\nوإني لقوال لذي البث مرحبا،\nوأهلا، إذا ما جاء من غير مرصد\nوإني ليدعوني الندى ، فأجيبه،\nوأضرب بيض العارض المتوقد\nوإني لحلو تعتريني مرارة ،\nوإني لتراك لما لم أعود\nوإني لمزجاء المطي على الوجى ،\nوإني لتراك الفراش الممهد\nوأعمل ذات اللوث، حتى أردها،\nإذا حل عنها رحلها لم تقيد\nأكلفها أن تدلج الليل كله\nتروح إلى باب ابن سلمى ، وتغتدي\nوألفيته بحرا كثيرا فضوله،\nجوادا متى يذكر له الخير يزدد\nفلا تعجلن يا قيس واربع، فإنما\nقصاراك أن تلقى بكل مهند\nحسام، وأرماح بأيدي أعزة ،\nمتى ترهم يا بن الخطيم تبلد\nليوث لها الأشبال تحمي عرينها،\nمداعيس بالخطي في كل مشهد\nفقد ذاقت الأوس القتال وطردت،\nوأنت لدى الكنات في كل مطرد\nفناغ لدى الأبواب حورا نواعما،\nوكحل مآقيك الحسان بإثمد\nنفتكم عن العلياء أم لئيمة ،\nوزند متى تقدح به النار يصلد"},{"id":"diwan-hassan:61","bookId":"diwan-hassan","type":"poem","seq":61,"chapter":"قافية الباء","title":"عنوان القصيدة : ومن عاش منا عاش في عنجهية","page":"ج1 ص60","text":"ومن عاش منا عاش في عنجهية\nعلى شظف من عيشه المتنكد"},{"id":"diwan-hassan:62","bookId":"diwan-hassan","type":"poem","seq":62,"chapter":"قافية الباء","title":"عنوان القصيدة : لو كنت من هاشم، أو من بني أسد","page":"ج1 ص61","text":"لو كنت من هاشم، أو من بني أسد،\nأو عبد شمس، أو أصحاب اللوا الصيد\nأو من بني نوفل، أو رهط مطلب\nلله درك لم تهمم بنهديدي\nأو في الذؤابة من قوم ذوي حسب،\nلم تصبح اليوم نكسا ثاني الجيد\nأو من بني زهرة الأخيار قد علموا،\nأو من بني جمح البيض المناجيد\nأو في لذؤابة من تيم، رضيت بهم،\nأو من بني خلف الخضر الجلاعيد\nيا آل تيم ألا ينهى سفيهكم،\nقبل القذاف بقول كالجلاميد\nلولا الرسول، فإني لست عاصيه،\nحتى يغيبني في الرمس ملحودي\nوصاحب الغار، إني سوف أحفظه،\nوطلحة بن عبيد الله ذو الجود\nلقد رميت بها شنعاء فاضحة ،\nيظل منها صحيح القوم كالمودي\nلكن سأصرفها جهدي، وأعدلها\nعنكم بقول رصين، غير تهديد\nإلى الزبعرى ، فإن اللؤم حالفه،\nأو الأخابث من أولاد عبود"},{"id":"diwan-hassan:63","bookId":"diwan-hassan","type":"poem","seq":63,"chapter":"قافية الباء","title":"عنوان القصيدة : ألم تذر العين تسهادها","page":"ج1 ص62","text":"ألم تذر العين تسهادها،\nوجري الدموع، وإنفادها\nتذكر شعثاء، بعد الكرى ،\nوملقى عراص، وأوتادها\nإذا لجب من سحاب الربي\nع مر بساحتها جادها\nوقامت ترائيك مغدودنا،\nإذا ما تنوء به آدها\nووجها كوجه الغزال الربي\nب يقرو تلاعا وأسنادها\nفأوبه الليل شطر العضاه،\nيخاف جهاما وصرادها\nفإما هلكت فلا تنكحي\nخذول العشيرة ، حسادها\nيرى مدحة شتم أعراضها،\nسفاها، ويبغض من سادها\nوإن عاتبوه على مرة ،\nونابت مبيتة زادها\nومثلي أطاق، ولكنني\nأكلف نفسي الذي آدها\nسأوتي العشيرة ما حاولت\nإلي، وأكذب إيعادها\nوأحمل إن مغرم نابها،\nوأضرب بالسيف من كادها\nويثرب تعلم أنا بها\nأسود تنفض ألبادها\nنهز القنا في صدور الكما\nة ، حتى نكسر أعوادها\nإذا ما انتشوا وتصابى الحلو\nم، واجتلب الناس أحشادها\nوقال الحواصن للصالحي\nن: عاد له الشر من عادها\nجعلنا النعيم وقاء البؤوس،\nوكنا لدى الجهد أعمادها"},{"id":"diwan-hassan:64","bookId":"diwan-hassan","type":"poem","seq":64,"chapter":"قافية الباء","title":"عنوان القصيدة : فإن تصلح، فإنك عابدي","page":"ج1 ص63","text":"فإن تصلح، فإنك عابدي،\nوصلح العابدي إلى فساد\nوإن تفسد، فما ألفيت إلا\nبعيدا ما علمت من السداد\nوتلقاه على ما كان فيه\nمن الهفوات، أو نوك الفؤاد\nمبين الغي لا يعيا عليه،\nويعيا بعد عن سبل الرشاد\nعلى ما قام يشتمني لئيم،\nكخنزير تمرغ في رماد\nفأشهد أن أمك ملبغايا،\nوأن أباك من شر العباد\nفلن أنفك أهجو عابديا،\nطوال الدهر، ما نادى المنادي\nوقد سارت قواف باقيات\nتناشدها الرواة بكل وادي\nفقبح عابد، وبنو أبيه،\nفإن معادهم شر المعاد"},{"id":"diwan-hassan:65","bookId":"diwan-hassan","type":"poem","seq":65,"chapter":"قافية الباء","title":"عنوان القصيدة : مهاجنة ، إذا نسبوا عبيد","page":"ج1 ص64","text":"مهاجنة ، إذا نسبوا عبيد،\nعضاريط، مغالثة الزناد"},{"id":"diwan-hassan:66","bookId":"diwan-hassan","type":"poem","seq":66,"chapter":"قافية الباء","title":"عنوان القصيدة : ولسنا بشرب فوقهم ظل بردة","page":"ج1 ص65","text":"ولسنا بشرب فوقهم ظل بردة ،\nيعدون للحانوت تيسا ومفصدا\nولكننا شرب كرام، إذا انتشوا\nأهانوا الصريح والسديف المسرهدا\nوتحسبهم ماتوا زمين حليمة ،\nوإن تأتهم تحمد ندامتهم غدا\nوإن جئتهم ألفيت حول بيوتهم\nمن المسك والجادي فتيتا مبددا\nترى فوق أثناء الزرابي ساطا\nنعالا وقسوبا، وريطا معضدا\nوذا نطف يسعى ، ملصق خده\nبديباجة ، تكفافها قد تقددا"},{"id":"diwan-hassan:67","bookId":"diwan-hassan","type":"poem","seq":67,"chapter":"قافية الباء","title":"عنوان القصيدة : والله ما أدري، وإني لسائل","page":"ج1 ص66","text":"والله ما أدري، وإني لسائل:\nمهانة ، ذات الخيف، ألأم، أم سعد\nأعبد هجين أحمر اللون، فاقع،\nموتر علباء القفا، قطط جعد\nوكان أبو سرح عقيما فلم يكن\nله ولد حتى دعيت له بعد"},{"id":"diwan-hassan:68","bookId":"diwan-hassan","type":"poem","seq":68,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد لعن الرحمن جمعا يقودهم","page":"ج1 ص67","text":"لقد لعن الرحمن جمعا يقودهم\nدعي بني شجع لحرب محمد\nمشوم، لعين، كان قدما مبغضا،\nيبين فيه اللؤم من كان يهتدي\nفدلاهم في الغي، حتى تهافتوا،\nوكان مضلا أمره، غير مرشد\nفأنزل ربي للنبي جنوده،\nوأيده بالنصر في كل مشهد\nوإن ثواب الله كل موحد،\nجنان من الفردوس فيها يخلد"},{"id":"diwan-hassan:69","bookId":"diwan-hassan","type":"poem","seq":69,"chapter":"قافية الباء","title":"عنوان القصيدة : زعم ابن نابغة اللئيم بأننا","page":"ج1 ص68","text":"زعم ابن نابغة اللئيم بأننا\nلا نجعل الأحساب دون محمد\nأموالنا ونفوسنا من دونه،\nمن يصطنع خيرا يثب ويحمد\nفتيان صدق، كالليوث، مساعر،\nمن يلقهم يوم الهياج يعرد\nقوم ابن نابغة اللئام أذلة ،\nلا يقبلون على صفير المرعد\nوبنى لهم بيتا أبوك مقصرا\nكفرا ولؤما، بئس بيت المحتد"},{"id":"diwan-hassan:70","bookId":"diwan-hassan","type":"poem","seq":70,"chapter":"قافية الباء","title":"عنوان القصيدة : سألت قريشا كلها، فشرارها","page":"ج1 ص69","text":"سألت قريشا كلها، فشرارها\nبنو عابد، شاه الوجوه لعابد\nإذا قعدوا وسط الندي تجاوبوا،\nتجاوب عدان الربيع السوافد\nوما كان صيفي ليوفي ذمة ،\nقفا ثعلب أعيا ببعض الموارد"},{"id":"diwan-hassan:71","bookId":"diwan-hassan","type":"poem","seq":71,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا أردت السيد الأشدا","page":"ج1 ص70","text":"إذا أردت السيد الأشدا\nمن الرجال فعليك سعدا\nسعد بن زيد، فاتخذه جندا،\nليس بخوار يهد هدا\nليس يرى من ضرب كبش بدا\n-"},{"id":"diwan-hassan:72","bookId":"diwan-hassan","type":"poem","seq":72,"chapter":"قافية الباء","title":"عنوان القصيدة : أنا ابن خلدة ، والأغ","page":"ج1 ص71","text":"أنا ابن خلدة ، والأغ\nر، ومالكين وساعده\nوسراة قومك، إن بعث\nت لأهل يثرب ناشده\nفسعيت في دور الظوا\nهر والبواطن، جاهده\nفلتصبحن، وأنت ما\nليقين علمك حامده\nالمطعمون، إذا سنو\nن المحل تصبح راكده\nقمع التوامك في جفا\nن الحور، تصبح جامده"},{"id":"diwan-hassan:73","bookId":"diwan-hassan","type":"poem","seq":73,"chapter":"قافية الباء","title":"عنوان القصيدة : فمن يك منهم ذا خلاق، فإنه","page":"ج1 ص72","text":"فمن يك منهم ذا خلاق، فإنه\nسيمنعه من ظلمه ما توكدا"},{"id":"diwan-hassan:74","bookId":"diwan-hassan","type":"poem","seq":74,"chapter":"قافية الباء","title":"عنوان القصيدة : لعمرك ما تنفك عن طلب الخنا","page":"ج1 ص73","text":"لعمرك ما تنفك عن طلب الخنا\nبنو زهرة الأنذال ما عاش واحد\nلئام مساعيها قصار جدودها\nعن الخير للجار الغريب محاشد\nوما منهم عند المكارم والعلى\nإذا حضرت يوما من الدهر ماجد"},{"id":"diwan-hassan:75","bookId":"diwan-hassan","type":"poem","seq":75,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد كان قيس في اللئام مرددا","page":"ج1 ص74","text":"لقد كان قيس في اللئام مرددا،\nعصارة فرخ، معدن اللؤم، ماكد\nولادة سوء من سمية ، إنها\nأمية سوء مجدها شر تالد\nسفاحا، جهارا من أحيمق منهم،\nفقد سبقتهم في جميع المشاهد\nفجاءت بقيس ألأم الناس محتدا\nإذا ذكرت يوما لئام المحاتد"},{"id":"diwan-hassan:76","bookId":"diwan-hassan","type":"poem","seq":76,"chapter":"قافية الباء","title":"عنوان القصيدة : وما طلعت شمس النهار ولا بدت","page":"ج1 ص75","text":"وما طلعت شمس النهار ولا بدت\nعليك، بمجد، يا ابن مقطوعة اليد\nأبوك لقيط، الأم الناس موضعا،\nتبنى عليك اللؤم في كل مشهد\nإذا الدهر عف في تقادم عهده،\nعلى عار قوم، كان لؤمك في غد"},{"id":"diwan-hassan:77","bookId":"diwan-hassan","type":"poem","seq":77,"chapter":"قافية الباء","title":"عنوان القصيدة : لمن الصبي بجانب البطحا","page":"ج1 ص76","text":"لمن الصبي بجانب البطحا،\nفي الترب ملقى ، غير ذي مهد\nنجلت به بيضاء آنسة ،\nمن عبد شمس، صلتة الخد\nتسعى إلى الصياح معولة ،\nيا هند إنك صلبة الحرد\nفإذا تشاء دعت بمقطرة\nتذكى لها بألوة الهند\nغلبت على شبه الغلام، وقد\nبان السواد لحالك جعد\nأشرت لكاع، وكان عادتها\nدق المشاش بناجذ جلد"},{"id":"diwan-hassan:78","bookId":"diwan-hassan","type":"poem","seq":78,"chapter":"قافية الباء","title":"عنوان القصيدة : لمن سواقط صبيان منبذة","page":"ج1 ص77","text":"لمن سواقط صبيان منبذة ،\nباتت تفحص في بطحاء أجياد\nباتت تمخض، ما كانت قوابلها\nإلا الوحوش، وإلا جنة الوادي\nفيهم صبي له أم لها نسب،\nفي ذروة من ذرى الأحساب، أياد\nتقول وهنا، وقد جد المخاض بها:\nيا ليتني كنت أرعى الشول للغادي\nقد غادروه لحر الوجه منعفرا،\nوخالها وأبوها سيد النادي"},{"id":"diwan-hassan:79","bookId":"diwan-hassan","type":"poem","seq":79,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد علم الأقوام أن ابن هاشم","page":"ج1 ص78","text":"لقد علم الأقوام أن ابن هاشم\nهو الغصن ذو الأفنان لا الواحد الوغد\nوما لك فيهم محتد يعرفونه،\nفدونك فالصق مثل ما لصق القرد\nوإن سنام المجد من آل هاشم\nبنو بنت مخزوم، ووالدك العبد\nوما ولدت أفناء زهرة منكم\nكريما، ولم يقرب عجائزك المجد\nولست كعباس، ولا كابن أمه،\nولكن هجين ليس يورى له زند\nوأنت زنيم نيط في آل هاشم،\nكما نيط خلف الراكب القدح الفرد\nوإن أمرأ كانت سمية أمه\nوسمراء مغلوب إذا بلغ الجهد"},{"id":"diwan-hassan:80","bookId":"diwan-hassan","type":"poem","seq":80,"chapter":"قافية الباء","title":"عنوان القصيدة : رحم الله نافع بن بديل","page":"ج1 ص79","text":"رحم الله نافع بن بديل،\nرحمة المشتهي ثواب الجهاد\nصابرا، صادق الحديث، إذا ما\nأكثر القوم قال قول السداد\nكنت قبل اللقاء منه بجهل،\nفقد أمسيت قد أصاب فؤادي"},{"id":"diwan-hassan:81","bookId":"diwan-hassan","type":"poem","seq":81,"chapter":"قافية الباء","title":"عنوان القصيدة : غدا أهل حضني ذي المجاز بسحرة","page":"ج1 ص80","text":"غدا أهل حضني ذي المجاز بسحرة\nوجار ابن حرب بالمحصب ما يغدو\nكساك هشام بن الوليد ثيابه\nفأبل، وأخلف مثلها جددا بعد\nقضى وطرا منه، فأصبح غاديا،\nوأصبحت رخوا ما تخب وما تعدو\nفلو أن أشياخا ببدر شهوده\nلبل متون الخيل معتبط ورد\nفما منع العير الضروط ذماره،\nوما منعت مخزاة والدها هند"},{"id":"diwan-hassan:82","bookId":"diwan-hassan","type":"poem","seq":82,"chapter":"قافية الباء","title":"عنوان القصيدة : شق له من اسمه كي يجله","page":"ج1 ص81","text":"شق له من اسمه كي يجله،\nفذو العرش محمود، وهذا محمد\nنبي أتانا بعد يأس وفترة\nمن الرسل والأوثان في الأرض تعبد\nفأمسى سراجا مستنيرا، وهاديا،\nيلوح كما لاح الصقيل المهند\nوأنذرنا نارا وبشر جنة ،\nوعلمنا الإسلام، فالله نحمد\nوأنت إله الحق ربي وخالقي،\nبذلك ما عمرت في الناس أشهد\nتعاليت رب الناس عن قول من دعا\nسواك إلها، أنت أعلى وأمجد\nلك الخلق والنعماء والأمر كله،\nفإياك نستهدي، وإياك نعبد\nلأن ثواب الله كل موحد\nجنان من الفردوس، فيها يخلد"},{"id":"diwan-hassan:83","bookId":"diwan-hassan","type":"poem","seq":83,"chapter":"قافية الباء","title":"عنوان القصيدة : نب المساكين أن الخير فارقهم","page":"ج1 ص82","text":"نب المساكين أن الخير فارقهم\nمع النبي تولى عنهم سحرا\nمن ذا الذي عنده رحلي، وراحلتي،\nورزق أهلي، إذا لم يؤنسوا المطرا\nأم من نعاتب لا نخشى جنادعه،\nإذا اللسان عتا في القول، أو عثرا\nكان الضياء، وكان النور نتبعه،\nبعد الإله، وكان السمع والبصر\nفليتنا يوم واروه بملحده،\nوغيبوه، وألقوا فوقه المدرا\nلم يترك الله منا بعده أحدا،\nولم يعش بعده أنثى ، ولا ذكرا\nذلت رقاب بني النجار كلهم،\nوكان أمرا من امر الله قد قدرا"},{"id":"diwan-hassan:84","bookId":"diwan-hassan","type":"poem","seq":84,"chapter":"قافية الباء","title":"عنوان القصيدة : كنت السواد لناظري","page":"ج1 ص83","text":"كنت السواد لناظري،\nفعمي عليك الناظر\nمن شاء بعدك فليمت،\nفعليك كنت أحاذر"},{"id":"diwan-hassan:85","bookId":"diwan-hassan","type":"poem","seq":85,"chapter":"قافية الباء","title":"عنوان القصيدة : إياك إني قد كبرت وغالني","page":"ج1 ص84","text":"إياك إني قد كبرت وغالني\nعنك الغوائل عند شيب المكبر\nفجعلتني غرض اللئام، فكلهم\nيرمي بلؤمه بالغا كمقصر\nحتى تضب لثاتهم، فغدت بهم\nسوداء، أصل فروعها كالعنقر\nأجزرتهم عرضي، تهكم سادر؟\nثكلتك أمك، غير عرضي أجزر\nهدف تعاوره الرماة ، كأنما\nيرمون جندلة بعرض المشعر"},{"id":"diwan-hassan:86","bookId":"diwan-hassan","type":"poem","seq":86,"chapter":"قافية الباء","title":"عنوان القصيدة : إن النضيرة ربة الخدر","page":"ج1 ص85","text":"إن النضيرة ربة الخدر\nأسرت إليك، ولم تكن تسري\nفوقفت بالبيداء أسألها:\nأنى اهتديت لمنزل السفر\nوالعيس قد رفضت أزمتها،\nمما يرون بها من الفتر\nوعلت مساوئها محاسنها،\nمما أضر بها من الضمر\nكنا إذا ركد النهار لنا،\nنغتاله بنجائب صعر\nعوج، نواج، يعتلين بنا،\nيعفين دون النص، والزجر\nمستقبلات كل هاجرة ،\nينفحن في حلق من الصفر\nومناخها في كل منزلة ،\nكمبيت جوني القطا الكدر\nوسما على عود، فعارضنا\nحرباؤها، أو هم بالخطر\nوتكلفي اليوم الطويل وقد\nصرت جنادبه من الظهر\nوالليلة الظلماء أدلجها\nبالقوم في الديمومة القفر\nينعى الصدى فيها أخاه كما\nينعى المفجع صاحب القبر\nوتحول دون لكف ظلمتها،\nحتى تشق على الذي يسري\nولقد أريت الركب أهلهم،\nوهديتهم بمهامه غبر\nوبذلت ذا رحلي، وكنت به\nسمحا لهم في العسر واليسر\nفإذا الحوادث ما تضعضعني،\nولا يضيق بحاجتي صدري\nيعيي سقاطي من يوازنني،\nإني لعمرك لست بالهذر\nإني أكارم من يكارمني،\nوعلى المكاشح ينتحي ظفري\nلا أسرق الشعراء ما نطقوا،\nبل لا يوافق شعرهم شعري\nإني أبى لي ذلكم حسبي،\nومقالة كمقاطع الصخر\nوأخي من الجن البصير، إذا\nحاك الكلام بأحسن الحبر\nأنضير ما بيني وبينكم\nصرم، وما أحدثت من هجر\nجودي فإن الجود مكرمة ،\nواجزي الحسام ببعض ما يفري\nوحلفت لا أنساكم أبدا،\nما رد طرف العين ذو شفر\nوحلفت لا أنسى حديثك ما\nذكر الغوي لذاذة الخمر\nولأنت أحسن، إذ برزت لنا،\nيوم الخروج بساحة القصر\nمن درة أغلى الملوك بها،\nمما تربب حائر البحر\nممكورة الساقين، شبههما\nبرديتا متحير غمر\nتنمي كما تنمي أرومتها،\nبمحل أهل المجد والفخر\nيعتادني شوق، فأذكرها،\nمن غير ما نسب ولا صهر\nكتذكر الصادي، وليس له\nماء بقنة شاهق وعر\nولقد تجالسني، فيمنعني\nضيق الذراع، وعلة الخفر\nلو كنت لا تهوين لم تردي،\nأو كنت، ما تلوين في وكر\nلأتيته، لا بد، طالبه،\nفاقني حياءك، واقبلي عذري\nقل للنضيرة إن عرضت لها:\nليس الجواد بصاحب النزر\nقومي بنو النجار رفدهم\nحسن، وهم لي حاضرو النصر\nالموت دوني لست مهتضما،\nوذوو المكارم من بني عمرو\nجرثومة ، عز معاقلها،\nكانت لنا في سالف الدهر"},{"id":"diwan-hassan:87","bookId":"diwan-hassan","type":"poem","seq":87,"chapter":"قافية الباء","title":"عنوان القصيدة : تأوبني ليل بيثرب أعسر","page":"ج1 ص86","text":"تأوبني ليل بيثرب أعسر،\nوهم، إذا ما نوم الناس، مسهر\nلذكرى حبيب هيجت ثم عبرة\nسفوحا، وأسباب البكاء التذكر\nبلاء، فقدان الحبيب بلية ،\nوكم من كريم يبتلى ، ثم يصبر\nرأيت خيار المؤمنين تواردوا\nشعوب وقد خلفت فيمن يؤخر\nفلا يبعدن الله قتلى تتابعوا\nبؤتة ، منهم ذو الجناحين جعفر\nوزيد، وعبد الله، حين تتابعوا\nجميعا، وأسباب المنية تخطر\nغداة غدوا بالمؤمنين يقودهم\nإلى الموت ميمون النقيبة أزهر\nأغر كلون البدر من آل هاشم،\nأبي إذا سيم الظلامة مجسر\nفطاعن حتى مات غير موسد،\nبمعترك، فيه القنا يتكسر\nفصار مع المستشهدين ثوابه\nجنان، وملتف الحدائق، أخضر\nوكنا نرى في جعفر من محمد\nوفاء، وأمرا حازما حين يأمر\nفما زال في الإسلام من آل هاشم\nدعائم عز لا ترام ومفخر\nهم جبل الإسلام، والناس حوله\nرضام إلى طود يروق ويقهر\nبهم تكشف اللأواء في كل مأزق\nعماس، إذا ما ضاق بالقوم مصدر\nهم أولياء الله أنزل حكمه\nعليهم، وفيهم ذا الكتاب المطهر\nبهاليل منهم جعفر وابن أمه\nعلي، ومنهم أحمد المتخير\nوحمزة ، والعباس منهم، ومنهم\nعقيل، وماء العود من حيث يعصر"},{"id":"diwan-hassan:88","bookId":"diwan-hassan","type":"poem","seq":88,"chapter":"قافية الباء","title":"عنوان القصيدة : نبئت أن أبا منذر","page":"ج1 ص87","text":"نبئت أن أبا منذر\nيساميك للحارث الأصغر\nقفاك أحسن من وجهه،\nوأمك خير من المنذر\nويسرى يديك على عسرها\nكيمنى يديه على المعسر\nوشتان بينكما في الندى ،\nوفي البأس، والخير، والمنظر"},{"id":"diwan-hassan:89","bookId":"diwan-hassan","type":"poem","seq":89,"chapter":"قافية الباء","title":"عنوان القصيدة : عين جودي بدمعك المنزور","page":"ج1 ص88","text":"عين جودي بدمعك المنزور،\nواذكري في الرخاء أهل القبور\nواذكري مؤتة ، وما كان فيها،\nيوم ولوا في وقعة التغوير\nحين ولوا وغادروا ثم زيدا،\nنعم مأوى الضريك والمأسور\nحب خير الأنام طرا جميعا،\nسيد الناس، حبه في الصدور\nذاكم أحمد الذي لا سواه،\nذاك حزني معا له وسروري\nثم جودي للخزرجي بدمع،\nسيدا كان ثم غير نزور\nقد أتانا من قتلهم ما كفانا،\nفبحزن نبيت غير سرور"},{"id":"diwan-hassan:90","bookId":"diwan-hassan","type":"poem","seq":90,"chapter":"قافية الباء","title":"عنوان القصيدة : أوفت بنو عمرو بن عوف نذرها","page":"ج1 ص89","text":"أوفت بنو عمرو بن عوف نذرها،\nوتلوثت غدرا بنو النجار\nوتخاذلت يوم الحفيظة إنهم\nليسوا هنالكم من الأخيار\nونسو وصاة محمد في صهره،\nوتبدلوا بالعز دار بوار\nأتركتموه مفردا بمضيعة ،\nتنتابه الغوغاء في الأمصار\nلهفان يدعو غائبا أنصاره،\nيا ويحكم يا معشر الأنصار\nهلا وفيتم عندها بعهودكم،\nوفديتم بالسمع والأبصار\nجيرانه الأنون حول بيوته\nغدروا، ورب البيت ذي الأستار\nإن لم تروا مددا له وكتيبة\nتهدي أوائل جحفل جرار\nفعدمت ما ولد ابن عمرو منذر\nحتى ينيخ جموعهم بصرار\nوالله لا يوفون بعد إمامهم\nأبدا ولو أمنوا بحلس حمار\nأبلغ بني بكر، إذا ما جئتهم،\nذما، فبئس مواضع الأصهار\nغدروا بأبيض كالهلال مبرإ،\nخلصت مضاربه بزند وار\nمن خير خندف كلها، بعد الذي\nنصر الإله به على الكفار\nطاوعتم فيه العدو، وكنتم،\nلو شئتم، في معزل وقرار\nلا يحسبن المرجفون بأنهم\nلن يطلبوا بدماء أهل الدار\nحاشا بني عمرو بن عوف إنهم\nكتبت مضاجعهم مع الأبرار"},{"id":"diwan-hassan:91","bookId":"diwan-hassan","type":"poem","seq":91,"chapter":"قافية الباء","title":"عنوان القصيدة : وأفلت يوم الروع أوس بن خالد","page":"ج1 ص90","text":"وأفلت يوم الروع أوس بن خالد،\nيمج دما كالرعف مختضب النحر"},{"id":"diwan-hassan:92","bookId":"diwan-hassan","type":"poem","seq":92,"chapter":"قافية الباء","title":"عنوان القصيدة : تسائل عن قرم هجان سميذع","page":"ج1 ص91","text":"تسائل عن قرم هجان سميذع،\nلدى البأس، مغوار الصباح ، جسور\nأخي ثقة يهتز للعرف والندى ،\nبعيد المدى ، في النائبات صبور\nفقلت لها إن الشهادة راحة ،\nورضوان رب، يأمام، غفور\nفإن أباك الخير حمزة ، فاعلمي،\nوزير رسول الله خير وزير\nدعاه إله الخلق ذو العرش دعوة\nإلى جنة يرضى بها وسرور\nفذلك ما كنا نرجي ونرتجي،\nلحمزة يوم الحشر، خير مصير\nفوالله لا أنساك ما هبت الصبا،\nولأبكين في محضري ومسيري\nعلى أسد الله الذي كان مدرها،\nيذود عن الإسلام كل كفور\nألا ليت شلوي، يوم ذاك، وأعظمي\nإلأى أضبع ينتبنني ونسور\nأقول، وقد أعلى النعي بهلكه:\nجزى الله خيرا من أخ ونصير"},{"id":"diwan-hassan:93","bookId":"diwan-hassan","type":"poem","seq":93,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا ليت شعري هل اتى أهل مكة","page":"ج1 ص92","text":"ألا ليت شعري هل اتى أهل مكة\nإبارتنا الكفار في ساعة العسر\nقتلنا سراة القوم، عند رحالهم،\nفلم يرجعوا إلا بقاصمة الظهر\nقتلنا أبا جهل وعتبة قبله،\nوشيبة يكبو لليدين وللنحر\nوكم قد قتلنا من كريم مرزإ،\nله حسب في قومه نابه الذكر\nتركناهم للخامعات تنوبهم،\nويصلون نارا بعد حامية القعر\nبكفرهم بالله، والدين قائم،\nوما طلبوا فينا بطائلة الوتر\nلعمرك ما خامت فوارس مالك\nوأشياعهم يوم التقينا على بدر"},{"id":"diwan-hassan:94","bookId":"diwan-hassan","type":"poem","seq":94,"chapter":"قافية الباء","title":"عنوان القصيدة : على قتلى معونة ، فاستهلي","page":"ج1 ص93","text":"على قتلى معونة ، فاستهلي\nبدمع العين سحا غير نزر\nعلى خيل الرسول، غداة لاقوا\nمناياهم، ولاقتهم بقدر\nأصابهم الفناء، بحبل قوم،\nتخون عقد حبلهم بغدر\nفيا لهفي لمنذر إذ تولى ،\nوأعنق في منيته بصبر\nفكائن قد أصيب غداة ذاكم،\nمن أبيض ماجد من سر عمرو"},{"id":"diwan-hassan:95","bookId":"diwan-hassan","type":"poem","seq":95,"chapter":"قافية الباء","title":"عنوان القصيدة : أمسى الفتى بن ود ثاويا","page":"ج1 ص94","text":"أمسى الفتى بن ود ثاويا\nبجنوب سلع، ثاره لم ينظر\nولقد وجدت سيوفنا مشهورة ،\nولقد وجدت جيادنا لم تقصر\nولقد لقيت غداة بدر عصبة\nضربوك ضربا غير ضرب الحسر\nأصبحت لا تدعى ليوم عظيمة ،\nيا عمرو، أو لجسيم أمر منكر"},{"id":"diwan-hassan:96","bookId":"diwan-hassan","type":"poem","seq":96,"chapter":"قافية الباء","title":"عنوان القصيدة : لست إلى عمرو، ولا المرء منذر","page":"ج1 ص95","text":"لست إلى عمرو، ولا المرء منذر،\nإذا ما مطايا القوم أصبحن ضمرا\nفلولا أبو وهب لمرت قصائد،\nعلى شرف البرقاء، يهوين حسرا\nفإنا ومن يهدي القصائد نحونا،\nكمستبضع تمرا إلى أهل خيبرا\nفلا تكن كالوسنان يحلم أنه\nبقرية كسرى ، أو بقرية قيصر\nولا تك كالشاة التي كان حتفها\nبحفر ذراعيها، فلم ترض محفرا\nولا تك كالعاوي، فأقبل نحره،\nولم يخشه، سهما من النبل مضمرا\nأتفخر بالكتان لما لبسته،\nوقد يلبس الأنباط ريطا مقصرا"},{"id":"diwan-hassan:97","bookId":"diwan-hassan","type":"poem","seq":97,"chapter":"قافية الباء","title":"عنوان القصيدة : لعن الله منزلا بطن كوثى","page":"ج1 ص96","text":"لعن الله منزلا بطن كوثى ،\nورماه بالفقر والإمعار\nلست أعني كوثى العراق ولكن\nشرة الدور، دار عبد الدار\nحوت اللؤم والسفاه جميعا،\nفاحتوت ذاك كله في قرار\nوإذا ما سمت قريش لمجد،\nخلفتها في دارها بصغار"},{"id":"diwan-hassan:98","bookId":"diwan-hassan","type":"poem","seq":98,"chapter":"قافية الباء","title":"عنوان القصيدة : سألت قريشا فلم يكذبوا","page":"ج1 ص97","text":"سألت قريشا فلم يكذبوا،\nفسل وحوحا، وأبا عامر\nما أصل حسان في قومه،\nوليس المسائل كالحابر\nفلو يصدقون لأنبوكم\nبأنا ذوو الحسب القاهر\nوأنا مساعير، عند الوغى ،\nنرد شبا الأبلخ الفاجر\nورثت الفعال، وبذل التلا\nد، والمجد عن كابر كابر\nوحمل الديات، وفك العنا\nة ، والعز في الحسب الفاخر\nبكل متين أصم الكعوب،\nوأبيض ذي رونق باتر\nوبيضاء كالنهر فضفاضة ،\nتثنى بطول على الناشر\nبها نختلي مهج الدارعين،\nإذا نور الصبح للناظر\nإذا استبق الناس غاياتهم\nوجدت الزبعرى مع الآخر\nوما يجعل العي وسط الندي\nكالمحرب المصقع الشاعر\nوكيف يناصبني مفحم،\nينص إلى ملصق بائر"},{"id":"diwan-hassan:99","bookId":"diwan-hassan","type":"poem","seq":99,"chapter":"قافية الباء","title":"عنوان القصيدة : زادت هموم، فماء العين ينحدر","page":"ج1 ص98","text":"زادت هموم، فماء العين ينحدر\nسحا إذا أغرقته عبرة درر\nوجدا بشعثاء، إذ شعثاء بهكنة\nهيفاء، لا دنس فيها ولا خور\nدع عنك شعثاء، إذ كانت مودتها\nنزرا، وشر وصال الواصل النزر\nوأت الرسول فقل يا خير مؤتمن\nلمؤمنين، إذا ما عدل البشر\nعلام تدعى سليم، وهي نازحة ،\nأمام قوم هم آووا، وهم نصروا\nسماهم الله أنصارا لنصرهم\nدين الهدى ، وعوان الحرب تستعر\nوجاهدوا في سبيل الله، واعترفوا\nللنائبات فما خاموا ولا ضجروا\nوالناس ألب علينا، ثم ليس لنا،\nإلا السيوف وأطراف القنا، وزر\nولا يهر جناب الحرب مجلسنا،\nونحن حين تلظى نارها سعر\nوكم رددنا ببدر، دون ما طلبوا،\nأهل النفاق، وفينا أنزل الظفر\nونحن جندك يوم النعف من أحد،\nإذ حزبت بطرا أشياعها مضر\nفما ونينا، وما خمنا، وما خبروا\nمنا عثارا، وجل القوم قد عثروا"},{"id":"diwan-hassan:100","bookId":"diwan-hassan","type":"poem","seq":100,"chapter":"قافية الباء","title":"عنوان القصيدة : على حين أن قالتا لأيمن أمه","page":"ج1 ص99","text":"على حين أن قالتا لأيمن أمه:\nجبنت ولم تشهد فوارس خيبر\nوأيمن لم يجبن، ولكن مهره\nأضر به شرب المديد المخمر\nفلولا الذي قد كان من شأن مهره،\nلقاتل فيها فارسا، غير أعسر\nولكنه قد صده فعل مهره،\nوما كان منه عنده غير أيسر"},{"id":"diwan-hassan:101","bookId":"diwan-hassan","type":"poem","seq":101,"chapter":"قافية الباء","title":"عنوان القصيدة : كانت قريش بيضة ، فتفلقت","page":"ج1 ص100","text":"كانت قريش بيضة ، فتفلقت،\nفالمح خالصه لعبد الدار\nومناة ربي خصهم بكرامة ،\nحجاب بيت الله ذي الأستار\nأهل المكارم والعلاء وندوة ال\nنادي وأهل لطيمة الجبار\nولوا قريش في المشاهد كلها،\nوبنجدة عند القنا الخطار"},{"id":"diwan-hassan:102","bookId":"diwan-hassan","type":"poem","seq":102,"chapter":"قافية الباء","title":"عنوان القصيدة : إني لأعجب من قول غررت به","page":"ج1 ص101","text":"إني لأعجب من قول غررت به،\nحلو، يمد إليه السمع والبصر\nلو تسمع العصم، من صم الجبال، به،\nظلت من الراسيات العصم تنحدر\nكالخمر والشهد يجري فوق ظاهره،\nوما لباطنه طعم ولا خبر\nوكالسراب شبيها بالغدير، وإن\nتبغ السراب، فلا عين ولا أثر\nلا ينبت العشب عن برق وراعدة\nغراء، ليس لها سيل ولا مطر"},{"id":"diwan-hassan:103","bookId":"diwan-hassan","type":"poem","seq":103,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد غضبت جهلا سليم سفاهة","page":"ج1 ص102","text":"لقد غضبت جهلا سليم سفاهة ،\nوطاشت بأحلام كثير عثورها\nلئام مساعيها، كذوب حديثها،\nقليل غناها حين ينعى صقورها\nلها عقل نسوان، وشر شريعة ،\nنزور نداها حين تبغى بحورها\nإذا ضفتهم ألفيت حول بيوتهم\nكلابا لها في الدار، عال هريرها"},{"id":"diwan-hassan:104","bookId":"diwan-hassan","type":"poem","seq":104,"chapter":"قافية الباء","title":"عنوان القصيدة : أجمعت عمرة صرما فابتكر","page":"ج1 ص103","text":"أجمعت عمرة صرما فابتكر،\nإنما يدهن للقلب الحصر\nلا يكن حبك حبا ظاهرا،\nليس هذا منك يا عمر بسر\nسألت حسان من أخواله؟\nإنما يسأل بالشيء الغمر\nقلت أخوالي بنو كعب، إذا\nأسلم الأبطال عورات الدبر\nرب خال لي لو أبصرته\nسبط الكفين في اليوم الخصر\nعند هذا الباب، إذ ساكنه\nكل وجه حسن النقبة حر\nيوقد النار، إذا ما أطفئت،\nيعمل القدر بأثباج الجزر\nمن يغر الدهر، أو يأمنه،\nمن قبيل بعد عمرو وحجر\nملكا من جبل الثلج إلى\nجانبي أيلة ، من عبد وحر\nثم كانا خير من نال الندى ،\nسبقا الناس بإقساط وبر\nفارسي خيل، إذا ما أمسكت\nربة الخدر بأطراف الستر\nأتيا فارس في دارهم،\nفتناهوا بعد إعصام بقر\nثم صاحا: يال غسان اصبروا،\nإنه يوم مصاليت صبر\nاجعلوا معقلها أيمانكم،\nبالصفيح المصطفى ، غير الفطر\nبضراب تأذن الجن له،\nوطعان مثل أفواه الفقر\nولقد يعلم من حاربنا\nأننا ننفع قدما ونضر\nصبر للموت، إن حل بنا، م\nصادقو البأس، غطاريف فخر\nوأقام العز فينا والغنى ،\nفلنا منه على الناس الكبر\nمنهم أصلي، فمن يفخر به\nيعرف الناس بفخر المفتخر\nنحن أهل العز والمجد معا،\nغير أنكاس، ولا ميل عسر\nفسلوا عنا، وعن أفعالنا،\nكل قوم عندهم علم الخبر"},{"id":"diwan-hassan:105","bookId":"diwan-hassan","type":"poem","seq":105,"chapter":"قافية الباء","title":"عنوان القصيدة : قد أصبح القلب عنها كاد يصرفه","page":"ج1 ص104","text":"قد أصبح القلب عنها كاد يصرفه\nعنها تترع قول غير الشعرا\nيا زيد، يا سيد النجار، إن لما\nأحدث قومك في عثمان لي خبرا\nوإن لي حاجة ، يا زيد، أذكرها،\nلم أقض منها إلى ما قومنا وطرا\nإني أرى لهم زيا سيهلكهم،\nوفتية لم يصيبوا فيهم البصرا\nيا زيد! هل لك فيهم قبل موبقة\nتسعر النار في أفنائهم سعرا\nيا زيد! أهد لهم رأيا يعاش به؛\nيا زيد زيد بني النجار، مقتصرا\nيا زيد! أخرج بني النجار إذ عميت،\nوارفض طوائف غسان لها الأخرا"},{"id":"diwan-hassan:106","bookId":"diwan-hassan","type":"poem","seq":106,"chapter":"قافية الباء","title":"عنوان القصيدة : رميت بها أهل المضيق، فلم تكد","page":"ج1 ص105","text":"رميت بها أهل المضيق، فلم تكد\nتخلص من حمارة وأباعر\nومرت على الأنصار وسط رحالهم،\nفقلت لهم من صادر مع صادر\nوطوفت بالبيت العتيق، وسامحت\nطريق كداء في لحوب سوائر\nذكرت بها التعريس لما بدا لنا\nخيام بها من بين باد وحاضر\nوأعرض ذو دوران، تحسب أنه\nمن الجدب أعناق النساء الحواسر\nفعجت وألقت للجبان رجيلة\nلأنظر ما زاد الكريم المسافر\nإذا فضلة من بطن زق ونطفة\nوقعب صغير فوق عوجاء ضامر\nفقمت بكأس قهوة ، فشننتها\nيدي رونق من ماء زمزم فاتر\nفلما هبطنا بطن مر تخزعت\nخزاعة عنا في حلول كراكر"},{"id":"diwan-hassan:107","bookId":"diwan-hassan","type":"poem","seq":107,"chapter":"قافية الباء","title":"عنوان القصيدة : أروني سعودا كالسعود التي سمت","page":"ج1 ص106","text":"أروني سعودا كالسعود التي سمت\nبمكة من أولاد عمرو بن عامر\nأقاموا عمود الدين، حتى تمكنت\nقواعده، بالمرهفت البواتر\nوكم عقدوا لله، ثم وفوا به،\nبما ضاق عنه كل باد وحاضر"},{"id":"diwan-hassan:108","bookId":"diwan-hassan","type":"poem","seq":108,"chapter":"قافية الباء","title":"عنوان القصيدة : ما البكر إلا كالفصيل وقد ترى","page":"ج1 ص107","text":"ما البكر إلا كالفصيل وقد ترى\nأن الفصيل عليه ليس بعار\nإنا وما حج الحجيج لبيته،\nركبان مكة معشر الأنصار\nنفري جماجمكم بكل مهند،\nضرب القدار مبادي الأيسار\nحتى تكنوه بفحل هنيدة ،\nيحمي الطروقة ، بازل، هدار"},{"id":"diwan-hassan:109","bookId":"diwan-hassan","type":"poem","seq":109,"chapter":"قافية الباء","title":"عنوان القصيدة : يا حار من يغدر بذمة جاره","page":"ج1 ص108","text":"يا حار من يغدر بذمة جاره\nمنكم، فإن محمدا لم يغدر\nإن تغدروا فالغدر منكم شيمة ،\nوالغدر ينبت في أصول السخبر\nوأمانة المري، حيث لقيته،\nمثل الزجاجة صدعها لم يجبر"},{"id":"diwan-hassan:110","bookId":"diwan-hassan","type":"poem","seq":110,"chapter":"قافية الباء","title":"عنوان القصيدة : ما ولدتكم قروم من بني أسد","page":"ج1 ص109","text":"ما ولدتكم قروم من بني أسد،\nولا هصيص، ولا تيم، ولا عمر\nولا عدي بن كعب، إن صيغتها\nكالهندواني، ولا رث، ولا دثر\nوأنت عبد لقين، لا فؤاد له،\nمن آل شجع، هناك اللؤم والخور\nوقد تبين في شجع ولادتكم،\nكما تبين أنى يطلع القمر"},{"id":"diwan-hassan:111","bookId":"diwan-hassan","type":"poem","seq":111,"chapter":"قافية الباء","title":"عنوان القصيدة : أظن عيينة ، إذ زارها","page":"ج1 ص110","text":"أظن عيينة ، إذ زارها،\nبأن سوف يهدم فيها قصورا\nومنيت جمعك ما لم يكن،\nفقلت سنغنم شيئا كثيرا\nفعفت المدينة إذ جئتها،\nوألفيت للأسد فيها زئيرا\nفولوا سراعا كوخد النعا\nم، لم يكشفوا عن ملط حصيرا\nأمير علينا، رسول الملي\nك، أحبب بذاك إلينا أميرا\nرسول نصدق ما جاءه\nمن الوحي، كان سراجا منيرا"},{"id":"diwan-hassan:112","bookId":"diwan-hassan","type":"poem","seq":112,"chapter":"قافية الباء","title":"عنوان القصيدة : حار بن كعب ألا الأحلام تزجركم","page":"ج1 ص111","text":"حار بن كعب ألا الأحلام تزجركم\nعنا، وأنتم من الجوف الجماخير\nلا بأس بالقوم من طول ومن عظم،\nجسم البغال وأحلام العصافير\nذروا التخاجؤ وامشوا مشية سجحا،\nإن الرجال ذوو عصب وتذكير\nكأنكم خشب جوف أسافله\nمثقب فيه أرواح الأعاصير\nألا طعان، ألا فرسان عادية ،\nإلا تجشوكم حول التنانير\nلا ينفع الطول من نوك الرجال، ولا\nيهدي الإله سبيل المعشر البور\nإني سأقصر عرضي عن شراركم،\nإن النجاشي لشيء غير مذكور\nألفى أباه، وألفى جده حبسا\nبمعزل من معالي المجد والخير"},{"id":"diwan-hassan:113","bookId":"diwan-hassan","type":"poem","seq":113,"chapter":"قافية الباء","title":"عنوان القصيدة : لعمرك بالبطحاء، بين معرف","page":"ج1 ص112","text":"لعمرك بالبطحاء، بين معرف،\nوبين نطاة ، مسكن ومحاضر\nلعمري لحي، بين دار مزاحم،\nوبين الجثى ، لا يجشم السير، حاضر\nوحي حلال لا يكمش سربهم،\nلهم من وراء القاصيات زوافر\nإذا قيل يوما إظعنوا قد أتيتم،\nأقاموا، ولم تجلب إليهم أباعر\nأحق بها من فتية وركائب\nيقطع عنها الليل عوج ضوامر\nتقول وتذري الدمع عن حر وجهها:\nلعلك، نفسي قبل نفسك، باكر\nأباح لها بطريق غسان غائطا\nله من ذرى الجولان بقل وزاهر\nتربع في غسان أكفاف محبل\nإلى حارث الجولان فالني ظاهر\nفقربتها للرحل، وهي كأنها\nظليم نعام بالسماوة نافر\nفأوردتها ماء فما شربت به،\nسوى أنها قد بل منها المشافر\nفأصدرتها عن ماء ثهمل غدوة ،\nمن الغاب ذو طمرين، فالبز آطر\nفباتت، وبات الماء تحت جرانها\nلدى نحرها من جمة الماء عاذر\nفدابت سراها ليلة ثم عرست\nبيثرب، والأعراب باد وحاضر"},{"id":"diwan-hassan:114","bookId":"diwan-hassan","type":"poem","seq":114,"chapter":"قافية الباء","title":"عنوان القصيدة : صابت شعائره بصرى ، وفي رمح","page":"ج1 ص113","text":"صابت شعائره بصرى ، وفي رمح\nمنه دخان حريق كالأعاصير\nأفنى بذي بعل حتى باد ساكنها،\nوكل قصر من الخمان معمور\nفأعجل القوم عن حاجاتهم شغل،\nمن وخز جن بأرض الروم مذكور"},{"id":"diwan-hassan:115","bookId":"diwan-hassan","type":"poem","seq":115,"chapter":"قافية الباء","title":"عنوان القصيدة : سلامة دمية في لوح باب","page":"ج1 ص114","text":"سلامة دمية في لوح باب\nهبلت ألا تعز كما تجير\nولا ينفك ما عاش ابن روح\nجذامي بذمته ختور"},{"id":"diwan-hassan:116","bookId":"diwan-hassan","type":"poem","seq":116,"chapter":"قافية الباء","title":"عنوان القصيدة : يا ابني رفاعة ، ما بالي وبالكما","page":"ج1 ص115","text":"يا ابني رفاعة ، ما بالي وبالكما،\nهل تقصران، ولم تمسسكما ناري\nما كان منتهيا حتى يقاذفني\nكلب وجأت على فيه بأحجار\nيكسو الثلاثة نصف الثوب بينهم،\nبمئزر، ورداء غير أطهار\nقد خاب قوم نيار من سراتهم\nرجلا مجوعة شبت بمسعار\nلولا ابن هيشة ، إن المرء ذو رحم،\nإذا لأنشبت بالبزواء أظفاري"},{"id":"diwan-hassan:117","bookId":"diwan-hassan","type":"poem","seq":117,"chapter":"قافية الباء","title":"عنوان القصيدة : أبلغ معاوية بن حرب مألكا","page":"ج1 ص116","text":"أبلغ معاوية بن حرب مألكا،\nولكل أمر يستراد قرار\nلا تقبلن دنية أعطيتها\nأبدا، ولما تألم الأنصار\nحتى تبار قبيلة بقبيلة\nقودا وتخرب بالديار ديار\nوتجيء من نقب الحجاز كتيبة ،\nوتسيل بالمستلئمين صرار"},{"id":"diwan-hassan:118","bookId":"diwan-hassan","type":"poem","seq":118,"chapter":"قافية الباء","title":"عنوان القصيدة : وقوم من البغضاء زور، كأنما","page":"ج1 ص117","text":"وقوم من البغضاء زور، كأنما\nبأجوافهم، مما تجن لنا، الجمر\nيجيش بما فيه لنا الصدر مثل ما\nتجيش بما فيها من اللهب القدر\nتصد، إذا ما واجهتني، خدودهم\nلدى محفل عني كأنهم صعر\nتصيخ إذا يثنى بخير لديهم،\nرؤوسهم عني، وما بهم وقر\nوإن سمعوا سوءا بدا في وجوههم،\nلما سمعوا، مما يقال لنا البشر\nأجدي لا ينفك غس يسبني،\nفجورا بظهر الغيب أو ملحم قحر\nولو سئلت بدر بحسن بلائنا،\nفأثنت بما فينا، إذا حمدت بدر\nحفاظا على أحسابنا بنفوسنا،\nإذا لم يكن غير السيوف لنا ستر\nوأبدت معاريها النساء، وأبرزت،\nمن الروع، كاب حسن ألوانها، الزهر"},{"id":"diwan-hassan:119","bookId":"diwan-hassan","type":"poem","seq":119,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد لقيت قريظة ما سآها","page":"ج1 ص118","text":"لقد لقيت قريظة ما سآها،\nوما وجدت لذل من نصير\nأصابهم بلاء كان فيهم،\nسوى ما قد أصاب بني النضير\nغداة أتاهم يهوي إليهم\nرسول الله كالقمر المنير\nله خيل مجنبة تعادى\nبفرسان عليها كالصقور\nتركناهم وما ظفروا بشيء\nدماؤهم عليهم كالعبير\nفهم صرعى تحوم الطير فيهم،\nكذاك يدان ذو الفند الفخور\nفأردف مثلها نصحا قريشا،\nمن الرحمن، إن قبلت نذيري"},{"id":"diwan-hassan:120","bookId":"diwan-hassan","type":"poem","seq":120,"chapter":"قافية الباء","title":"عنوان القصيدة : لاطت قريش حياض المجد فافترطت","page":"ج1 ص119","text":"لاطت قريش حياض المجد فافترطت\nسهم، فأصبح منه حوضها صفرا\nوأوردوا، وحياض المجد طامية ،\nفدل حوضهم الوراد فانهدرا\nوالله ما في قريش كلها نفر\nأكثر شيخا جبانا فاحشا غمرا\nأذب أصلع سفسيرا له ذأب\nكالقرد يعجم وسط المجلس الحمرا\nهذر مشائيم محروم ثويهم،\nإذا تروح منهم زود القمرا\nأما ابن نابغة العبد الهجين، فقد\nأنحي عليه لسانا صارما ذكرا\nما بال أمك زاغت عند ذي شرف\nإلى جذيمة ، لما عفت الأثرا\nظلت ثلاثا، وملحان معانقها،\nعند الحجون، فما ملا وما فترا\nيا آل سهم، فإني قد نصحت لكم،\nلا أبعثن على الأحياء من قبرا\nألا ترون بأني قد ظلمت، إذا\nكان الزبعرى لنعلي ثابت خطرا\nكم من كريم يعض الكلب مئزره\nثم يفر إذا ألقمته الحجرا\nقولي لكم، آل شجع، سم مطرقة\nصماء تطحر عن أنيابها القذرا\nلولا النبي، وقول الحق مغضبة ،\nلما تركت لكم أنثى ولا ذكرا"},{"id":"diwan-hassan:121","bookId":"diwan-hassan","type":"poem","seq":121,"chapter":"قافية الباء","title":"عنوان القصيدة : قوم لئام أقلض الله خيرهم","page":"ج1 ص120","text":"قوم لئام أقلض الله خيرهم،\nكما تناثر، خلف الراكب، البعر\nكأن ريحهم في الناس، إذ خرجوا،\nريح الحشاش إذا ما بلها المطر\nقد ابرز الله قولا، فوق قولهم،\nكما النجوم تعالى فوقها القمر"},{"id":"diwan-hassan:122","bookId":"diwan-hassan","type":"poem","seq":122,"chapter":"قافية الباء","title":"عنوان القصيدة : اما الحماس فإني غير شاتمهم","page":"ج1 ص121","text":"اما الحماس فإني غير شاتمهم،\nلا هم كرام ولا عرضي لهم خطر\nقوم لئام أقل الله عدتهم،\nكما تساقط حول الفقحة البعر\nكأن ريحهم، في الناس إذ برزوا،\nريح الكلاب إذا ما بلها المطر\nأولاد حام، فلن تلقى لهم شبها\nإلا التيوس على أكتافها الشعر\nإن سابقوا سبقوا، أو نافروا نفروا،\nأو كاثروا أحدا من غيرهم كثروا\nشبه الإماء، فلا دين ولا حسب،\nلو قامروا الزنج، عن أحسابهم، قمروا\nتلقى الحماسي لا يمنعك حرمته،\nشبه النبيط إذا استعبدتهم صبروا"},{"id":"diwan-hassan:123","bookId":"diwan-hassan","type":"poem","seq":123,"chapter":"قافية الباء","title":"عنوان القصيدة : أشرت لكاع وكان عادتها","page":"ج1 ص122","text":"أشرت لكاع وكان عادتها\nلؤم إذا أشرت مع الكفر\nأخرجت مرقصة إلى أحد،\nفي القوم معنقة على بكر\nبكر ثفال، لا حراك به،\nلا عن معاتبة ، ولا زجر\nوعصاك إستك تتقين به\nدق العجاية عاري الفهر\nقرحت عجيزتها ومشرجها\nمن نصها نصا على القهر\nظلت تداويها زميلتها،\nبالماء تنضحه وبالسدر\nأقبلت زائرة مبادرة\nبأبيك وابنك يوم ذي بدر\nوبعمك المسلوب بزته،\nوأخيك منعفرين في الجفر\nونسيت فاحشة أتيت بها،\nيا هند، ويحك سبة الدهر\nفرجعت صاغرة ، بلا ترة\nمما ظفرت به، ولا وتر\nزعم الولائد أنها ولدت\nولدا صغيرا، كان من عهر"},{"id":"diwan-hassan:124","bookId":"diwan-hassan","type":"poem","seq":124,"chapter":"قافية الباء","title":"عنوان القصيدة : إن أباك الرذل كان لصغرة","page":"ج1 ص123","text":"إن أباك الرذل كان لصغرة ،\nوكان أبوك التيس شاة عزوزا\nوكان ذليلا من طريد ملعن،\nفسموه من بعد الذليل عزيزا\nبنو نوفل أهل السماحة والندى ،\nفآووك من فقر، وكفوا العجوزا"},{"id":"diwan-hassan:125","bookId":"diwan-hassan","type":"poem","seq":125,"chapter":"قافية الباء","title":"عنوان القصيدة : لو كان، في الدار، قوم ذو محافظة","page":"ج1 ص124","text":"لو كان، في الدار، قوم ذو محافظة ،\nحامي الحقيقة ماض، خاله أنس\nإذا حللت، خبيب، منزلا فسحا،\nولم يشد عليك الكبل والحرس\nولم يسقك إلى التنعيم زعنفة\nمن المعاشر، ممن قد نفت عدس\nصبرا، خبيب، فإن القتل مكرمة ،\nإلى جنان نعيم يرجع النفس"},{"id":"diwan-hassan:126","bookId":"diwan-hassan","type":"poem","seq":126,"chapter":"قافية الباء","title":"عنوان القصيدة : يا آل بكر ألا تنهون جاهلكم","page":"ج1 ص125","text":"يا آل بكر ألا تنهون جاهلكم،\nعبد ابن رحضة عنزا بين أتياس\nيا ابن التي سلحت في بيت جارتها،\nفطار منه عصار قاشب الناس\nكأن أظفارها شققن من حجر،\nفليس منهن إلا وارم قاسي\nمثل القرود، إذا ما جئت ناديهم،\nألفيت كل دني، عرده عاسي"},{"id":"diwan-hassan:127","bookId":"diwan-hassan","type":"poem","seq":127,"chapter":"قافية الباء","title":"عنوان القصيدة : لمن الدار أقفرت ببواط","page":"ج1 ص126","text":"لمن الدار أقفرت ببواط،\nغير سفع، رواكد، كالغطاط\nتلك دار الألوف أضحت خلاء،\nبعدما قد تحلها في نشاط\nدارها، إذ تقول: ما لابن عمرو\nلج، من بعد قربه، في شطاط\nبلغاها بأنني خير راع\nللذي حملت بغير افتراط\nرب لهو شهدته، أم عمرو،\nبين بيض نواعم في الرياط\nمع ندامى بيض الوجوه، كرام،\nنبهوا، بعد خفقة الأشراط\nلكميت كأنها دم جوف،\nعتقت من سلافة الأنباط\nفاحتواها فتى يهين لها الما\nل، ونادمت صالح بن علاط\nظل حولي قيانه عازفات،\nمثل أدم، كوانس، وعواط\nطفن بالكأس، بين شرب كرام،\nمهدوا حر صالح الأنماط\nساعة ، ثم قال هن بداد\nبينكم، غير سمعة الإختلاط\nرب خرق أجزت ملعبة الج\nن معي صارم الحديد، إباطي\nفوق مستنزل الرديف، منيف،\nمثل سرحان غابة ، وخاط\nبينما نحن نشتوي من سديف،\nراعنا صوت مصدح، نشاط\nفأتينا بسابح يعبوب،\nلم يذلل بمعلف ورباط\nغير مسح وحشك كوم صفايا،\nومرافيد في الشتاء، بساط\nفتنادوا، فألجموه، وقالوا\nلغلام معاود الإعتباط\nسكنته، واكفف إليك من الغر\nب تجد مائحا، قليل السقاط\nفتولى الغلام يقدع مهرا،\nتئق الغرب، مانعا للسياط\nوتولين حين أبصرن شخصا\nمدمجا متنه كمتن المقاط\nفوقه مطعم الوحوش، رفيق،\nعالم كيف فوزة الآباط\nداجن بالطراد، يرمي بطرف\nفي فضاء، وفي صحار بساط\nثم والى بسمحج ونحوص،\nوبعلج، يكفه بعلاط\nثم رحنا، وما يخاف خليلي\nمن لساني خيانة الإنبساط"},{"id":"diwan-hassan:128","bookId":"diwan-hassan","type":"poem","seq":128,"chapter":"قافية الباء","title":"عنوان القصيدة : بني أسد، ما بال آل خويلد","page":"ج1 ص127","text":"بني أسد، ما بال آل خويلد\nيحنون شوقا كل يوم إلى القبط\nإذا ذكرت قهقاء حنوا لذكرها،\nوللرمث المقرون، والسمك الرقط\nوأعينهم مثل الزجاج، وصيغة\nتخالف كعبا في لحى لهم ثط\nترى ذاك في الشبان والمرد منهم،\nمبينا، وفي الأطفال منهم وفي الشمط\nلعمر أبي العوام، إن خويلدا\nغداة تبناه ليوثق في الشرط\nوإنك إن تجرر علي جريرة ،\nرددتك عبدا في المهانة والعفط"},{"id":"diwan-hassan:129","bookId":"diwan-hassan","type":"poem","seq":129,"chapter":"قافية الباء","title":"قافية الظاء","page":"ج1 ص128","text":"عنوان القصيدة : وكان أمية بن خلف الخزاعي هجا حسان بقوله:"},{"id":"diwan-hassan:130","bookId":"diwan-hassan","type":"poem","seq":130,"chapter":"قافية الباء","title":"ألا من مبلغ حسان عني","page":"ج1 ص128","text":"وكان أمية بن خلف الخزاعي هجا حسان بقوله:\nألا من مبلغ حسان عني\nمغلغلة تدب إلى عكاظ\nأليس أبوك فينا كان قينا،\nلدى القينات، فسلا في الحفاظ\nيمانيا يظل يشد كيرا،\nوينفخ دائبا لهب الشواظ"},{"id":"diwan-hassan:131","bookId":"diwan-hassan","type":"poem","seq":131,"chapter":"قافية الباء","title":"عنوان القصيدة : فأجابه حسان، رضي الله عنه:أتاني عن أمية زرو قول","page":"ج1 ص129","text":"فأجابه حسان، رضي الله عنه:\nأتاني عن أمية زرو قول\nوما هو بالمغيب بذي حفاظ\nسأنشر إن بقيت لكم كلاما،\nينشر في المجامع من عكاظ\nقوافي كالسلام، إذا استمرت\nمن الصم المعجرفة الغلاظ\nتزورك، إن شتوت بكل أرض،\nوترضخ في محلك بالمقاظ\nبنيت عليك أبياتا صلابا\nكأسر الوسق قفص بالشظاظ\nمجللة ، تعممه شنارا،\nمضرمة ، تأجج كالشواظ\nكهمزة ضيغم يحمي عرينا،\nشديد مغارز الأضلاع خاظي\nتغض الطرف أن ألقاك دوني،\nوترمي حين أدبر باللحاظ"},{"id":"diwan-hassan:132","bookId":"diwan-hassan","type":"poem","seq":132,"chapter":"قافية الباء","title":"عنوان القصيدة : إن الذوائب من فهر وإخوتهم","page":"ج1 ص130","text":"إن الذوائب من فهر وإخوتهم\nقد بينوا سنة للناس تتبع\nيرضى بها كل من كانت سريرته\nتقوى الإله وبالأمر الذي شرعوا\nقوم إذا حاربوا ضروا عدوهم،\nأو حاولوا النفع في أشياعهم نفعوا\nسجية تلك منهم غير محدثة ،\nإن الخلائق، فاعلم، شرها البدع\nلا يرقع الناس ما أوهت أكفهم\nعند الدفاع، ولا يوهون ما رقعوا\nإن كان في الناس سباقون بعدهم،\nفكل سبق لأدنى سبقهم تبع\nولا يضنون عن مولى بفضلهم،\nولا يصيبهم في مطمع طبع\nلا يجهلون، وإن حاولت جهلهم،\nفي فضل أحلامهم عن ذاك متسع\nأعفة ذكرت في الوحي عفتهم،\nلا يطمعون، ولا يرديهم الطمع\nكم من صديق لهم نالوا كرامته،\nومن عدو عليهم جاهد جدعوا\nأعطوا نبي الهدى والبر طاعتهم،\nفما ونى نصرهم عنه وما نزعوا\nإن قال سيروا أجدوا السير جهدهم،\nأو قال عوجوا علينا ساعة ، ربعوا\nما زال سيرهم حتى استقاد لهم\nأهل الصليب، ومن كانت له البيع\nخذ منهم ما أتى عفوا، إذا غضبوا،\nولا يكن همك الأمر الذي منعوا\nفإن في حربهم، فاترك عداوتهم،\nشرا يخاض عليه الصاب والسلع\nنسمو إذا الحرب نالتنا مخالبها،\nإذا الزعانف من أظفارها خشعوا\nلا فخر إن هم أصابوا من عدوهم،\nوإن أصيبوا فلا خور ولا جزع\nكأنهم في الوغى ، والموت مكتنع،\nأسد ببيشة في أرساغها فدع\nإذا نصبنا لقوم لا ندب لهم،\nكما يدب إلى الوحشية الذرع\nأكرم بقوم رسول الله شيعتهم،\nإذا تفرقت الأهواء والشيع\nأهدى لهم مدحي قوم يؤازره\nفيما يحب لسان حائك صنع\nفإنهم أفضل الأحياء كلهم،\nإن جد بالناس جد القول أو شمعوا"},{"id":"diwan-hassan:133","bookId":"diwan-hassan","type":"poem","seq":133,"chapter":"قافية الباء","title":"عنوان القصيدة : أرقت لتوماض البروق اللوامع","page":"ج1 ص131","text":"أرقت لتوماض البروق اللوامع،\nونحن نشاوى بين سلع وفارع\nأرقت له، حتى علمت مكانه،\nبأكناف سلع، والتلاع الدوافع\nطوى أبرق العزاف يرعد متنه،\nحنين المتالي، نحو صوت المشايع"},{"id":"diwan-hassan:134","bookId":"diwan-hassan","type":"poem","seq":134,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا يا لقوم هل لما حم دافع؟","page":"ج1 ص132","text":"ألا يا لقوم هل لما حم دافع؟\nوهل ما مضى من صالح العيش راجع\nتذكرت عصرا قد مضى ، فتهافتت\nبنات الحشا، وانهل مني المدامع\nصبابة وجد ذكرتني أحبة ،\nوقتلى مضوا فيهم نفيع ورافع\nوسعد فأضحوا في الجنان وأوحشت\nمنازلهم والأرض منهم بلاقع\nوفوا يوم بدر للرسول، وفوقهم\nظلال المنايا والسيوف اللوامع\nدعا فأجابوه بحق، وكلهم\nمطيع له في كل أمر وسامع\nفما بدلوا حتى توافوا جماعة ،\nولا يقطع الآجال إلا المصارع\nلأنهم يرجون منه شفاعة ،\nإذا لم يكن إلا النبيين شافع\nوذلك، يا خير العباد، بلاؤنا\nومشهدنا في الله، والموت ناقع\nلنا القدم الأولى إليك، وخلفنا،\nلأولنا، في طاعة الله تابع\nونعلم أن الملك لله وحده،\nوإن قضاء الله لا بد واقع"},{"id":"diwan-hassan:135","bookId":"diwan-hassan","type":"poem","seq":135,"chapter":"قافية الباء","title":"عنوان القصيدة : بانت لميس بحبل منك أقطاع","page":"ج1 ص133","text":"بانت لميس بحبل منك أقطاع،\nواحتلت الغمر، نزعا ذات أشراع\nوأصبحت في بني نصر مجاورة ،\nترعى الأباطح في عز وإمراع\nكأن عيني، إذ ولت حمولهم\nفي الفجر، فيض غروب ذات أتراع\nهلا سألت، هداك الله، ما حسبي،\nأم الوليد، وخير القول للواعي\nهل أغفر الذنب ذا الجرح العظيم، ولو\nمرت عجارفه، مني بأوجاع\nالله يعلم ما أسعى لجلهم،\nوما يغيب به صدري وأضلاعي\nأسعى على جل قوم كان سعيهم\nوسط العشيرة سهوا غير دعداع\nولا أصالح من عادوا وأخذلهم،\nولا أغيب لهم يوما بأقذاع\nوقد غدوت على الحانوت يصبحني\nمن عائق مثل عين الديك شعشاع\nتغدوا علي، وندماني لمرفقه،\nنقضي اللذاذات من لهو وأسماع\nإذا نشاء دعوناه، فصب لنا\nمن فرغ منتفج الحيزوم ركاع\nوقد أراني أمام الحي منتطقا\nبصارم مثل لون الملح، قطاع\nتحفز عني، نجاد السيف، سابغة ،\nفضفاضة مثل لون النهي بالقاع\nفي فتية كسيوف الهند أوجههم\nنحو الصريخ، إذا ما ثوب الداعي"},{"id":"diwan-hassan:136","bookId":"diwan-hassan","type":"poem","seq":136,"chapter":"قافية الباء","title":"عنوان القصيدة : أشاقك من أم الوليد ربوع","page":"ج1 ص134","text":"أشاقك من أم الوليد ربوع،\nبلاقع، ما من أهلهن جميع\nعفاهن صيفي الرياح، وواكف\nمن الدلو، رجاف السحاب هموع\nفلم يبق إلا موقد النار حوله\nرواكد، أمثال الحمام، وقوع\nفدع ذكر دار بددت بين أهلها\nنوى فرقت بين الجميع قطوع\nوقل: إن يكن يوم بأحد يعده\nسفيه، فإن الحق سوف يشيع\nوقد ضاربت فيه بنو الأوس كلهم،\nوكان لهم ذكر، هناك، رفيع\nوحامى بنو النجار فيه وضاربوا،\nوما كان منهم، في اللقاء، جزوع\nأمام رسول الله لا يخذلونه،\nلهم ناصر من ربهم، وشفيع\nوفوا إذ كفرتم، يا سخين، بربكم،\nولا يستوي عبد عصى ومطيع\nبأيمانهم بيض إذا حمي الوغى ،\nفلا بد أن يردى بهن صريع\nكما غادرت في النقع عثمان ثاويا،\nوسعدا صريعا، والوشيج شروع\nوقد غادرت تحت العجاجة ، مسندا،\nأبيا، وقد بل القميص نجيع\nبكف رسول الله، حتى تلففت\nعلى القوم مما قد يثرن نقوع\nأولئك قومي سادة من فروعهم،\nومن كل قوم سادة وفروع\nبهن يعز الله حين يعزنا،\nوإن كان أمر، يا سخين، فظيع\nفإن تذكروا قتلى ، وحمزة فيهم\nقتيل، ثوى لله، وهو مطيع\nفإن جنان الخلد منزله بها،\nوأمر الذي يقضي الأمور سريع\nوقتلاكم في النار أفضل رزقهم\nحميم معا، في جوفها، وضريع"},{"id":"diwan-hassan:137","bookId":"diwan-hassan","type":"poem","seq":137,"chapter":"قافية الباء","title":"عنوان القصيدة : أعرض عن العوراء إن أسمعتها","page":"ج1 ص135","text":"أعرض عن العوراء إن أسمعتها،\nواقعد كأنك غافل لا تسمع\nودع السؤال عن الأمور وبحثها،\nفلرب حافر حفرة هو يصرع\nوالزم مجالسة الكرام وفعلهم،\nوإذا اتبعت فأبصرن من تتبع\nلا تتبعن غواية لصبابة ،\nإن الغواية كل شر تجمع\nوالقوم إن نزروا فزد في نزرهم،\nلا تقعدن خلالهم تتسمع\nوالشرب لا تدمن، وخذ معروفه،\nتصبح صحيح الرأس لا تتصدع\nواكدح بنفسك لا تكلف غيرها،\nفبدينها تجزى ، وعنها تدفع\nوالموت أعداد النفوس، ولا أرى\nمنه لذي هرب نجاة تنفع"},{"id":"diwan-hassan:138","bookId":"diwan-hassan","type":"poem","seq":138,"chapter":"قافية الباء","title":"عنوان القصيدة : زبانية حول أبياتهم","page":"ج1 ص136","text":"زبانية حول أبياتهم،\nوخور لدى الحرب في المعمعه"},{"id":"diwan-hassan:139","bookId":"diwan-hassan","type":"poem","seq":139,"chapter":"قافية الباء","title":"عنوان القصيدة : سائل بني الأشعر، إن جئتهم","page":"ج1 ص137","text":"سائل بني الأشعر، إن جئتهم،\nما كان أنباء بني واسع؟\nإذ تركوه، وهو يدعوهم،\nبالنسب الأقصى ، وبالجامع\nوالليث يعلوه بأنيابه،\nمنعفرا وسط دم ناقع\nلا يرفع الرحمن مصروعهم،\nولا يوهن قوة الصارع"},{"id":"diwan-hassan:140","bookId":"diwan-hassan","type":"poem","seq":140,"chapter":"قافية الباء","title":"عنوان القصيدة : نشدت بني النجار أفعال، والدي","page":"ج1 ص138","text":"نشدت بني النجار أفعال، والدي،\nإذا لم يجد عان له من يوارعه\nوارث عليه الوافدون، فما ترى\nعلى النأي منهم ذا حفاظ يطالعه\nوسد عليه كل أمر يريده،\nوزيد وثاقا، فأقفعلت أصابعه\nإذا ذكر الحي المقيم حلولهم،\nوأبصر ما يلقى استهلت مدامعه\nألسنا ننص العيس فيه على الوجى ،\nإذا نام مولاه، ولذت مضاجعه\nولا ننتهي حتى نفك كبوله\nبأموالنا، والخير يحمد صانعه\nوأنشدكم، والبغي مهلك أهله،\nإذا ما شتاء المحل هبت زعازعه\nإذا ما وليد الحي لم يسق شربة ،\nوضن عليه بالصبوح مراضعه\nوراحت جلاد الشول حدبا ظهورها\nإلى مسرح بالجو جدب مراتعه\nألسنا نكب الكوم، وسط رحالنا،\nونستصلح المولى ، إذا قل رافعه\nفإن نابه أمر وقته نفوسنا،\nوما نالنا من صالح، فهو واسعه\nوأنشدكم، والبغي مهلك أهله،\nإذا الكبش لم يوجد له من يقارعه\nألسنا نوازيه بجمع كأنه\nأتي أبدته بليل دوافعه\nفنكثركم فيه، ونصلى بحره،\nونمشي إلى أبطاله، فنماصعه\nوأنشدكم، والبغي مهلك أهله،\nإذا الخصم لم يوجد له من يدافعه\nألسنا نصاديه، ونعدل ميله،\nولا ننتهي أو يخلص الحق ناصعه\nفلا تكفرونا ما فعلنا إليكم،\nوأثنوا به، والكفر بور بضائعه\nكما لو فعلتم مثل ذاك إليهم،\nلأثنوا به، ما يأثر القول سامعه"},{"id":"diwan-hassan:141","bookId":"diwan-hassan","type":"poem","seq":141,"chapter":"قافية الباء","title":"عنوان القصيدة : فلا والله، ما تدري معيص","page":"ج1 ص139","text":"فلا والله، ما تدري معيص،\nأسهل بطن مكة أم يفاع\nوكل محارب، وبني نزار،\nتبين في مشافره الرضاع\nوما جمح ولو ذكرت بشيء،\nولا تيم، فذلكم الرعاع\nلأن اللؤم فيهم مستبين،\nإذا كان الوقائع، والمصاع\nومخزوم هم وعدي كعب،\nلئام الناس، ليس لهم دفاع"},{"id":"diwan-hassan:142","bookId":"diwan-hassan","type":"poem","seq":142,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد أتى عن بني الجرباء قولهم","page":"ج1 ص140","text":"لقد أتى عن بني الجرباء قولهم،\nودونهم قف جمدان، فموضوع\nقد علمت أسلم الأنذال أن لها\nجارا سيقتله في داره الجوع\nوأن سيمنعهم مما نووا حسب،\nلن يبلغ المجد والعلياء مقطوع\nقد رغبوا، زعموا، عني بأختهم،\nوفي الذرى نسبي، والمجد مرفوع"},{"id":"diwan-hassan:143","bookId":"diwan-hassan","type":"poem","seq":143,"chapter":"قافية الباء","title":"عنوان القصيدة : قد حان قول قصيدة مشهورة","page":"ج1 ص141","text":"قد حان قول قصيدة مشهورة ،\nشنعاء أرصدها لقوم رضع\nيغلي بها صدري وأحسن حوكها،\nوإخالها ستقال إن لم تقطع\nذهبت قريش بالعلاء، وأنتم\nتمشون مشي المومسات الخرع\nفدعوا الخاجؤ، وامنعوا أستاهكم،\nوامشوا بمدرجة الطريق المهيع\nأنتم بقية قوم لوط، فاعلموا،\nوإلى خناثكم يشار بإصبع\nوإذا قريش حصلت أنسابها،\nفبآل شجع فافخروا في المجمع\nخرق معازيل إذا جد الوغى ،\nبطن إذا ما جارهم لم يشبع"},{"id":"diwan-hassan:144","bookId":"diwan-hassan","type":"poem","seq":144,"chapter":"قافية الباء","title":"عنوان القصيدة : بني القين هلا إذ فخرتم بربعكم","page":"ج1 ص142","text":"بني القين هلا إذ فخرتم بربعكم\nفخرتم بكير عند باب ابن جندع\nبناه أبوكم، قبل بنيان داره،\nبحرس، فأخفوا ذكر قين مدفع\nوألقوا رماد الكير يعرف وسطكم\nلدى مجلس منكم، لئيم ومفجع"},{"id":"diwan-hassan:145","bookId":"diwan-hassan","type":"poem","seq":145,"chapter":"قافية الباء","title":"عنوان القصيدة : وما سارق الدرعين، إن كنت ذاكرا","page":"ج1 ص143","text":"وما سارق الدرعين، إن كنت ذاكرا،\nبذي كرم من الرجال اوادعه\nفقد أنزلته بنت سعد، فأصبحت\nينازعها جلد استها، وتنازعهء\nفهلا أسيدا جئت جارك راغبا\nإليه، ولم تعمد له، فترافعه\nظننتم بأن يخفى الذي قد صنعتم،\nوفينا نبي عنده الوحي واضعه\nفلولا رجال منكم أن يسوءهم\nهجائي، لقد حلت عليكم طوالعه\nفإن تذكروا كعبا إذا ما نسيتم،\nفهل من أديم ليس فيه أكارعه\nهم الرأس، والأذناب في الناس أنتم،\nفلم تك إلا في الرؤوس مسامعه"},{"id":"diwan-hassan:146","bookId":"diwan-hassan","type":"poem","seq":146,"chapter":"قافية الباء","title":"عنوان القصيدة : لله در عصابة لاقيتهم","page":"ج1 ص144","text":"لله در عصابة لاقيتهم،\nيا ابن الحقيق، وأنت يا ابن الأشرف\nيسرون بالبيض الرقاق إليكم،\nمرحا، كأسد في عرين مغرف\nحتى أتوكم في محل بلادكم،\nفسقوكم حتفا ببيض قرقف\nمستبصرين لنصر دين نبيهم،\nمستصغرين لكل أمر مجحف"},{"id":"diwan-hassan:147","bookId":"diwan-hassan","type":"poem","seq":147,"chapter":"قافية الباء","title":"عنوان القصيدة : لمن الدار، والرسوم العوافي","page":"ج1 ص145","text":"لمن الدار، والرسوم العوافي،\nبين سلع وأبرق العزاف\nدار خود تشفي الضجيع بعذب ال\nطعم مز وبارد كالسلاف\nما تراها على التعطل والبذ\nلة إلا كدرة الأصداف"},{"id":"diwan-hassan:148","bookId":"diwan-hassan","type":"poem","seq":148,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد جدعت آذان كعب وعامر","page":"ج1 ص146","text":"لقد جدعت آذان كعب وعامر\nبقتل ابن كعب ثم حزت أنوفها\nفولت نطيحا كبشها وجموعها\nثبات عزين ما تلام صفوفها\nوحاز ابن عبد، إذ هوى في رماحنا،\nكذاك المنايا حينها وحتوفها\nأصيبت به فهر، فلا انجبرت لها\nمصائب، باد حرها وشفيفها\nوأخرى ببدر خاب فيها رجاؤهم،\nفلم تغن عنها نبلها وسيوفها\nوأخرى وشيكا ليس فيها تحول،\nيصم المنادي جرسها وحفيفها"},{"id":"diwan-hassan:149","bookId":"diwan-hassan","type":"poem","seq":149,"chapter":"قافية الباء","title":"عنوان القصيدة : لو أن اللؤم ينسب كان عبدا","page":"ج1 ص147","text":"لو أن اللؤم ينسب كان عبدا\nقبيح الوجه أعور من ثقيف\nتركت الدين والإيمان جهلا،\nغداة لقيت صاحبة النصيف\nوراجعت الصبا، وذكرت لهوا\nمن الأحشاء، والخصر اللطيف"},{"id":"diwan-hassan:150","bookId":"diwan-hassan","type":"poem","seq":150,"chapter":"قافية الباء","title":"عنوان القصيدة : أظنت بنو بكر كتاب محمد","page":"ج1 ص148","text":"أظنت بنو بكر كتاب محمد\nكإرمائها من أوفض ورصاف\nلأنتم بحمل المخزيات وجمعها\nأحق من ان تستجمعوا لعفاف\nفقالوا على خط النبي، فأصبحوا\nأثامى بنعلي بغضة وقراف"},{"id":"diwan-hassan:151","bookId":"diwan-hassan","type":"poem","seq":151,"chapter":"قافية الباء","title":"عنوان القصيدة : يا مال والسيد المعمم قد","page":"ج1 ص149","text":"يا مال والسيد المعمم قد\nيبطره بعض رأيه السرف\nنحن بما عندنا وأنت بما\nعندك راض، والرأي مختلف\nيا مال والحق إن قنعت به\nفالحق فيه لأمرنا نصف\nخالفت في الرأي كل ذي فجر،\n-\nإن بجيرا مولى لقومكم،\n-"},{"id":"diwan-hassan:152","bookId":"diwan-hassan","type":"poem","seq":152,"chapter":"قافية الباء","title":"عنوان القصيدة : أبلغ بني جحجبى وقومهم","page":"ج1 ص150","text":"أبلغ بني جحجبى وقومهم\nخطمة أنا وراءهم أنف\nوأننا دون ما يسومهم\nأعداء من ضيم خطة نكف\nنفلي بحد الصفيح هامهم،\nوفلينا هامهم بها جنف"},{"id":"diwan-hassan:153","bookId":"diwan-hassan","type":"poem","seq":153,"chapter":"قافية الباء","title":"عنوان القصيدة : ما بال عين دموعها تكف","page":"ج1 ص151","text":"ما بال عين دموعها تكف،\nمن ذكر خود شطت بها قذف\nبانت بها غربة تؤم بها\nأرضا سوانا والشكل مختلف\nما كنت أدري بوشك بينهم،\nحتى رأيت الحدوج قد عزفوا\nفغادروني، والنفس غالبها\nما شفها، والهموم تعتكف\nدع ذا وعد القريض في نفر\nيدعون مجدي، ومدحتي شرف\nإن تدع قومي للمجد تلفهم\nأهل فعال يبدو إذا وصفوا\nبلغ عني النبيت قافية ،\nتذلهم إنهم لنا حلفوا\nبالله جهدا لنقتلنكم،\nقتلا عنيفا، والخيل تنكشف\nأو ندع في الأوس دعوة هربا،\nوقد بدا في الكتيبة النصف\nكنتم عبيدا لنا نخولكم\nمن جاءنا، والعبيد تضطعف\nكيف تعاطون مجدنا سفها،\nوأنتم دعوة لها وكف\nشانكم جدكم، وأكرمنا\nجد لنا في الفعال ينتصف\nنجعل من كان المجد محتده،\nكأعبد الأوس كلما وصفوا\nهلا غضبتم لأعبد قتلوا\nيوم بعاث، أظلهم ظلف\nنقتلهم، والسيوف تأخذهم،\nأخذا عنيفا، وانتم كشف\nوكم قتلنا من رائس لكم،\nفي فيلق يجتدي له التلف\nومن لئيم عبد يحالفكم،\nليست له دعوة ، ولا شرف\nإن سميرا عبد طغى سفها،\nساعده أعبد لهم نطف"},{"id":"diwan-hassan:154","bookId":"diwan-hassan","type":"poem","seq":154,"chapter":"قافية الباء","title":"عنوان القصيدة : ألم ترنا أولاد عمرو بن عامر","page":"ج1 ص152","text":"ألم ترنا أولاد عمرو بن عامر،\nلنا شرف يعلو على كل مرتقي\nرسا في قرار الأرض ثم سمت له\nفروع تسامي كل نجم محلق\nملوك وأبناء الملوك، كأننا\nسواري نجوم طالعات بمشرق\nإذا غاب منها كوكب لاح بعده\nشهاب متى ما يبد للأرض تشرق\nلكل نجيب منجب زخرت به\nمهذبة أعراقها لم ترهق\nكجفنة والقمقام عمرو بن عامر،\nوأولاد ماء المزن وابني محرق\nوحارثة الغطريف، أو كابن منذر،\nومثل أبي قابوس رب الخورنق\nأولئك لا الأوغاد في كل مأقط،\nيردون شأو العارض المتألق\nبطعن كإبزاغ المخاض رشاشه،\nوضرب يزيل الهام من كل مفرق\nأتانا رسول الله، لما تجهمت\nله الأرض، يرميه بها كل موفق\nتطرده أفناء قيس وخندف،\nكتائب إن لا تغد للروع تطرق\nفكنا له من سائر الناس معقلا\nأشم، منيعا ذا شماريخ شهق\nمكللة بالمشرفي وبالقنا،\nبها كل أظمى ذي غرارين، أزرق\nتذود بها عن أرضها خزرجية ،\nكأسد كراء، أو كجنة نمنق\nتؤازرها أوسية مالكية ،\nرقاق السيوف، كالعقائق، ذلق\nنفى الذم عنا كل يوم كريهة ،\nطعان كتضريم الأباء المحرق\nوإكرامنا أضيافنا، ووفاؤنا\nبما كان من إل علينا وموثق\nفنحن ولاة الناس في كل موطن،\nمتى ما نقل في الناس قولا نصدق\nتوفق في أحكامنا حكماؤنا،\nإذا غيرهم، في مثلها، لم يوفق"},{"id":"diwan-hassan:155","bookId":"diwan-hassan","type":"poem","seq":155,"chapter":"قافية الباء","title":"عنوان القصيدة : ما بال عينك لا ترقا مدامعها","page":"ج1 ص153","text":"ما بال عينك لا ترقا مدامعها،\nسحا على الصدر، مثل اللؤلؤ الفلق\nعلى خبيب، وفي الرحمن مصرعه،\nلا فشل حين تلقاه ولا نزق\nفاذهب خبيب، جزاك الله طيبة ،\nوجنة الخلد عند الحور في الرفق\nماذا تقولون، إن قال النبي لكم،\nحين الملائكة الأبرار في الأفق\nفيما قتلتم شهيد الله في رجل\nطاغ قد أوعث في البلدان والطرق\nأبا إهاب فبين لي حديثكم:\nأين الغزال محلى الدر والورق\nلا تذكرن، إذا ما كنت مفتخرا،\nأبا كثيبة ! قد أسرفت في الحمق\nولا عزيزا، فإن الغدر منقصة ،\nإن عزيزا دقيق النفس والخلق"},{"id":"diwan-hassan:156","bookId":"diwan-hassan","type":"poem","seq":156,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا الله حيا معشرا بفعالهم","page":"ج1 ص154","text":"إذا الله حيا معشرا بفعالهم،\nونصرهم الرحمن رب المشارق\nفأخزاك ربي، يا عتيب بن مالك،\nولقاك قبل الموت إحدى الصواعق\nبسطت يمينا للنبي برمية ،\nفأميت فاه، قطعت بالبوارق\nفهلا خشيت الله والمنزل الذي\nتصير إليه بعد إحدى الصفائق\nلقد كان خزيا في الحياة لقومه،\nوفي البعث، بعد الموت، إحدى العوالق"},{"id":"diwan-hassan:157","bookId":"diwan-hassan","type":"poem","seq":157,"chapter":"قافية الباء","title":"عنوان القصيدة : وإنما الشعر لب المرء يعرضه","page":"ج1 ص155","text":"وإنما الشعر لب المرء يعرضه\nعلى المجالس إن كيسا وإن حمقا\nوإن أشعر بيت أنت قائله\nبيت يقال، إذا أنشدته، صدقا"},{"id":"diwan-hassan:158","bookId":"diwan-hassan","type":"poem","seq":158,"chapter":"قافية الباء","title":"عنوان القصيدة : أقمنا على الرس النزيع لياليا","page":"ج1 ص156","text":"أقمنا على الرس النزيع لياليا،\nبأرعن جرار عريض المبارك\nبكل كميت، جوزه نصف خلقه،\nوقب طوال، مشرفات الحوارك\nترى العرفج العامي تذري أصوله\nمناسم أخفاف المطي الرواتك\nإذا ارتحلوا من منزل خلت أنه\nمدمن أهل الموسم المتعارك\nنسير، فلا تنجو اليعافير وسطنا،\nولو وألت منا بشد مواشك\nذروا فلجات الشأم، قد حال دونها\nضراب كأفواه المخاض الاوارك\nبأيدي رجال هاجروا نحو ربهم\nوأنصاره حقا وأيدي الملائك\nإذا سلكت للغور من رمل عالج،\nفقولا لها: ليس الطريق هنالك\nفإن نلق في تطوافنا والتماسنا\nفرات بن حيان يكن وهن هالك\nوإن نلق قيس بن امرىء القيس بعده\nنزد في سواد وجهه لون حالك\nفأبلغ أبا سفيان عني رسالة ،\nفإنك من شر الرجال الصعالك"},{"id":"diwan-hassan:159","bookId":"diwan-hassan","type":"poem","seq":159,"chapter":"قافية الباء","title":"عنوان القصيدة : فإن تك عنا، معشر الأسد، سائلا","page":"ج1 ص157","text":"فإن تك عنا، معشر الأسد، سائلا،\nفنحن بنو الغوث بن زيد بن مالك\nلزيد بن كهلان الذي نال عزه\nقديما دراري النجوم الشوابك\nإذا القوم عدوا مجدهم وفعالهم\nوأيامهم، عند التقاء المناسك\nوجدت لنا فضلا يقر لنا به،\nإذا ما فخرنا، كل باق وهالك"},{"id":"diwan-hassan:160","bookId":"diwan-hassan","type":"poem","seq":160,"chapter":"قافية الباء","title":"عنوان القصيدة : ففدا أمي لعوف كلها","page":"ج1 ص158","text":"ففدا أمي لعوف كلها،\nوبني الأبيض في يوم الدرك\nمنعوا ضيمي بضرب صائب،\nتحت أطراف السرابيل هتك\nوبنان نادر أطرافها،\nوعراقيب تفسا كالفلك"},{"id":"diwan-hassan:161","bookId":"diwan-hassan","type":"poem","seq":161,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا من مبلغ حسان عني","page":"ج1 ص159","text":"ألا من مبلغ حسان عني\nخلفت أبي ولم تخلف أباكا"},{"id":"diwan-hassan:162","bookId":"diwan-hassan","type":"poem","seq":162,"chapter":"قافية الباء","title":"عنوان القصيدة : لأن أبي خلافته شديد","page":"ج1 ص160","text":"لأن أبي خلافته شديد،\nوإن أباك مثلك ما عداك"},{"id":"diwan-hassan:163","bookId":"diwan-hassan","type":"poem","seq":163,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا تذكرت شجوا من أخي ثقة","page":"ج1 ص161","text":"إذا تذكرت شجوا من أخي ثقة ،\nفاذكر أخاك أبا بكر بما فعلا\nالتالي الثاني المحمود مشهده،\nوأول الناس طرا صدق الرسلا\nوالثاني اثنين في الغار المنيف، وقد\nطاف العدو به إذ صعد الجبلا\nوكان حب رسول الله قد علموا،\nمن البرية لم يعدل به رجلا\nخير البرية أبقاها وأرأفها،\nبعد النبي، وأوفاها بما حملا\nعاش حميدا، لأمر الله متبعا،\nبهدي صاحبه الماضي، وما انتقلا"},{"id":"diwan-hassan:164","bookId":"diwan-hassan","type":"poem","seq":164,"chapter":"قافية الباء","title":"عنوان القصيدة : يا غراب البين أسمعت فقل","page":"ج1 ص162","text":"يا غراب البين أسمعت فقل\nإنما تنطق شيئا قد فعل\nإن للخير وللشر مدى ،\nوكلا ذلك وجه وقبل\nوالعطيات خساس بينهم،\nوسواء قبر مثر ومقل\nكل عيش ونعيم زائل،\nوبنات الدهر يلعبن بكل\nأبلغا حسان عني آية ،\nفقريض الشعر يشفي ذا الغلل\nكم ترى بالجر من جمجمة ،\nوأكف قد أترت ورجل\nوسرابيل حسان سريت\nعن كماة أهلكوا في المنتزل\nكم قتلنا من كريم سيد،\nماجد الجدين مقدام بطل\nصادق النجدة ، قرم بارع،\nغير ملتاث لدى وقع الأسل\nليت أشياخي ببدر شهدوا\nجزع الخزرج من وقع الأسل\nفاسأل المهراس من ساكنه،\nبعد أقحاف وهام كالحجل"},{"id":"diwan-hassan:165","bookId":"diwan-hassan","type":"poem","seq":165,"chapter":"قافية الباء","title":"عنوان القصيدة : ذهبت بابن الزبعري وقعة","page":"ج1 ص163","text":"ذهبت بابن الزبعري وقعة ،\nكان منا الفضل فيها لو عدل\nولقد نلتم ونلنا منكم،\nوكذاك الحرب أحيانا دول\nإذ شددنا شدة صادقة ،\nفأجأناكم إلى سفح الجبل\nإذ تولون على أعقابكم\nهربا في الشعب، أشباه الرسل\nنضع الخطي في أكتافكم،\nحيث نهوى عللا بعد نهل\nفسدحنا في مقام واحد،\nمنكم سبعين، غير المنتحل\nوأسرنا منكم أعدادهم،\nفانصرفتم مثل إفلات الحجل\nتخرج الأضياح من أستاهكم\nكسلاح النيب يأكلن العصل\nلم يفوتونا بشيء ساعة ،\nغير أن ولوا بجهل، وفشل\nضاق عنا الشعب، إذ نجزعه،\nوملأنا الفرط منهم والرجل\nبرجال لستم أمثالهم،\nأيدوا جبريل نصرا، فنزل\nوعلونا يوم بدر بالتقى ،\nطاعة الله، وتصديق الرسل\nبخناظيل كجنان الملا،\nمن يلاقوه من الناس يهل\nوتركنا في قريش عورة ،\nيوم بدر، وأحاديث مثل\nوتركنا من قريش جمعهم،\nمثل ما جمع في الخصب الهمل\nفقتلنا كل رأس منهم،\nوقتلنا كل جحجاح رفل\nكم قتلنا من كريم سيد\nماجد الجدين مقدام بطل\nوشريف لشريف ماجد\nلا نباليه لدى وقع الأسل\nنحن لا أنتم، بني أستاهها،\nنحن في البأس إذا البأس نزل"},{"id":"diwan-hassan:166","bookId":"diwan-hassan","type":"poem","seq":166,"chapter":"قافية الباء","title":"عنوان القصيدة : أسألت رسم الدار أم لم تسأل","page":"ج1 ص164","text":"أسألت رسم الدار أم لم تسأل\nبين الجوابي، فالبضيع، فحومل\nفالمرج، مرج الصفرين، فجاسم،\nفديار سلمى ، درسا لم تحلل\nدمن تعاقبها الرياح دوارس،\nوالمدجنات من السماك الأعزل\nدار لقوم قد أراهم مرة\nفوق الأعزة عزهم لم ينقل\nلله در عصابة نادمتهم،\nيوما بجلق في الزمان الأول\nيمشون في الحلل المضاعف نسجها،\nمشي الجمال إلى الجمال البزل\nالضاربون الكبش يبرق بيضه،\nضربا يطيح له بنان المفصل\nوالخالطون فقيرهم بغنيهم،\nوالمنعمون على الضعيف المرمل\nأولاد جفنة حول قبر أبيهم،\nقبر ابن مارية الكريم، المفضل\nيغشون، حتى ما تهر كلابهم،\nلا يسألون عن اليواد المقبل\nيسقون من ورد البريص عليهم\nبردى يصفق بالرحيق السلسل\nيسقون درياق الرحيق، ولم تكن\nتدعى ولائدهم لنقف الحنظل\nبيض الوجوه، كريمة أحسابهم،\nشم الأنوف، من الطراز الأول\nفلبثت أزمانا طوالا فيهم،\nثم ادكرت كأنني لم أفعل\nإما تري رأسي تغير لونه\nشمطا فأصبح كالثغام المحول\nولقد يراني موعدي كأنني\nفي قصر دومة ، أو سواء الهيكل\nولقد شربت الخمر في حانوتها،\nضهباء، صافية ، كطعم الفلفل\nيسعى علي بكأسها متنطف،\nفيعلني منها، ولو لم أنهل\nإن التي ناولتني فرددتها\nقتلت، قتلت، فهاتها لم تقتل\nكلتاهما حلب العصير فعاطني\nبزجاجة أرخاهما للمفصل\nبزجاجة رقصت بما في قعرها،\nرقص القلوص براكب مستعجل\nنسبي أصيل في الكرام، ومذودي\nتكوي مواسمه جنوب المصطلي\nولقد تقلدنا العشيرة أمرها،\nونسود يوم النائبات، ونعتلي\nويسود سيدنا جحاجح سادة ،\nويصيب قائلنا سواء المفصل\nونحاول الأمر المهم خطابه\nفيهم، ونفصل كل أمر معضل\nوتزور أبواب الملوك ركابنا،\nومتى نحكم في البرية نعدل\nوفتى يحب الحمد يجعل ماله\nمن دون والده، وإن لم يسأل\nباكرت لذته، وما ماطلتها،\nبزجاجة من خير كرم أهدل"},{"id":"diwan-hassan:167","bookId":"diwan-hassan","type":"poem","seq":167,"chapter":"قافية الباء","title":"عنوان القصيدة : أهاجك بالبيداء رسم المنازل","page":"ج1 ص165","text":"أهاجك بالبيداء رسم المنازل،\nنعم قد عفاها كل أسحم هاطل\nوجرت عليها الرامسات ذيولها،\nفلم يبق منها غير أشعث ماثل\nديار التي راق الفؤاد دلالها،\nوعز علينا أن تجود بنائل\nلها عين كحلاء المدامع مطفل،\nتراعي نعاما يرتعي بالخمائل\nديار التي كادت، ونحن على منى ،\nتحل بنا لولا نجاء الرواحل\nألا أيها الساعي ليدرك مجدنا،\nنأتك العلى ، فاربع عليك، فسائل\nفهل يستوي ماءان أخضر زاخر،\nوحسي ظنون، ماؤه غير فاضل\nفمن يعدل الأذناب ويحك بالذرى ،\nقد اختلفا بر يحق بباطل\nتناول سهيلا في السماء، فهاته،\nستدركنا إن نلته بالأنامل\nألسنا بحلالين أرض عدونا،\nتأر قليلا، سل بنا في القبائل\nتجدنا سبقنا بالفعال وبالندى ،\nوأمر العوالي في الخطوب الأوائل\nونحن سبقنا الناس مجدا وسوددا\nتليدا، وذكرا ناميا غير خامل\nلنا جبل يعلو الجبال مشرف،\nفنحن بأعلى فرعه المتطاول\nمساميح بالمعروف، وسط رحالنا،\nوشباننا بالفحش أبخل باخل\nومن خير حي تعلمون لسائل\nعفافا، وعان موثق بالسلاسل\nومن خير حي تعلمون لجارهم،\nإذا اختارهم في الأمن أو في الزلازل\nوفينا إذا ما شبت الحرب سادة\nكهول وفتيان طوال الحمائل\nنصرنا، وآوينا النبي، وصدقت\nأوائلنا بالحق، أول قائل\nوكنا متى يغز النبي قبيلة ،\nنصل حافتيه بالقنا والقنابل\nويوم قريش إذ أتونا بجمعهم،\nوطئنا العدو وطأة المتثاقل\nوفي أحد يوم لهم كان مخزيا،\nنطاعنهم بالسمهري الذوابل\nويوم ثقيف، إذ أتينا ديارهم،\nكتائب نمشي حولها بالمناصل\nففروا وشد الله ركن نبيه،\nبكل فتى حامي الحقيقة باسل\nففروا إلى حصن القصور وغلقوا،\nوكائن ترى من مشفق غير وائل\nوأعطوا بأيديهم صغارا وتابعوا،\nفأولى لكم أولى ، حداة الزوامل\nوإني لسهل للصديق، وإنني\nلأعدل رأس الأصعر المتمايل\nوأجعل مالي دون عرضي وقاية ،\nوأحجبه كي لا يطيب لآكل\nوأي جديد ليس يدركه البلى ،\nوأي نعيم ليس يوما بزائل"},{"id":"diwan-hassan:168","bookId":"diwan-hassan","type":"poem","seq":168,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا أبلغ أبا مخزوم عني","page":"ج1 ص166","text":"ألا أبلغ أبا مخزوم عني،\nوبعض القول ليس بذي حويل\nأما، وأبيك، لو لبثت شيئا،\nلألحقك الفوارس بالجليل\nولكن، قد بكيت، وأنت خلو،\nبعيد الدار من عون القتيل"},{"id":"diwan-hassan:169","bookId":"diwan-hassan","type":"poem","seq":169,"chapter":"قافية الباء","title":"عنوان القصيدة : يا حار! في سنة من نوم أولكم","page":"ج1 ص167","text":"يا حار! في سنة من نوم أولكم،\nأم كنت ويحك مغترا بجبريل\nأم كنت، بابن زياد، حين نقتله،\nبغرة في فضاء الأرض مجهول\nوقلتم لن نرى ، والله مبصركم،\nوفيكم محكم الآيات والقيل\nمحمد، والعزيز الله يخبره\nبما تكن سريرات الأقاويل"},{"id":"diwan-hassan:170","bookId":"diwan-hassan","type":"poem","seq":170,"chapter":"قافية الباء","title":"عنوان القصيدة : شهدت، بإذن الله، أن محمدا","page":"ج1 ص168","text":"شهدت، بإذن الله، أن محمدا\nرسول الذي فوق السماوات من عل\nوأن أبا يحيى ويحيى كليهما\nله عمل في دينه متقبل\nوأن التي بالجزع من بطن نخلة ،\nومن دانها فل من الخير معزل\nوأن الذي عادى اليهود ابن مريم،\nرسول أتى من عند ذي العرش مرسل\nوأن أخا الأحقاف، إذ يعذلونه،\nيقوم بدين الله فيهم، فيعدل"},{"id":"diwan-hassan:171","bookId":"diwan-hassan","type":"poem","seq":171,"chapter":"قافية الباء","title":"عنوان القصيدة : منعنا، على رغم القبائل، ضيمنا","page":"ج1 ص169","text":"منعنا، على رغم القبائل، ضيمنا،\nبمرهفة كالملح مخلصة الصقل\nضربناهم، حتى استباحت سيوفنا\nحماهم، وراحوا موجعين من القتل\nورد سراة الأوس، إذ جاء جمعهم،\nبطعن كأفواه المخيسة الهدل\nوذل سمير عنوة جار مالك\nعلى رغمه بعد التخمط والجهل\nوجاء ابن عجلان بعلج مجدع،\nفأدبر منقوص المروءة والعقل\nوصار ابن عجلان نفيا، كأنه\nعسيف على آثار أفصلة همل"},{"id":"diwan-hassan:172","bookId":"diwan-hassan","type":"poem","seq":172,"chapter":"قافية الباء","title":"عنوان القصيدة : حصان رزان ما تزن بريبة","page":"ج1 ص170","text":"حصان رزان ما تزن بريبة ،\nوتصبح غرثى من لحوم الغوافل\nحليلة خير الناس دينا ومنصبا،\nنبي الهدى ، والمكرمات الفواضل\nعقيلة حي من لؤي بن غالب،\nكرام المساعي، مجدها غير زائل\nمهذبة قد طيب الله خيمها،\nوطهرها من كل سوء وباطل\nفإن كنت قد قلت الذي قد زعمتم،\nفلا رفعت سوطي إلي أناملي\nوإن الذي قد قيل ليس بلائط\nبها الدهر بل قول امرىء بي ماحل\nفكيف وودي ما حييت ونصرتي\nلآل نبي الله زين المحافل\nله رتب عال على الناس كلهم،\nتقاصر عنه سورة المتطاول\nرأيتك، وليغفر لك الله، حرة\nمن المحصنات غير ذات غوائل"},{"id":"diwan-hassan:173","bookId":"diwan-hassan","type":"poem","seq":173,"chapter":"قافية الباء","title":"عنوان القصيدة : كم للمنازل من شهر وأحوال","page":"ج1 ص171","text":"كم للمنازل من شهر وأحوال،\nكما تقادم عهد المهرق البالي\nبالمستوي دون نعف القف من قطن\nفالدافعات أولات الطلح والضال\nأمست بسابس تستن الرياح بها،\nقد أشعلت بحصاها أي إشعال\nما يقسم الله أقبل غير مبتئس\nمنه، وأقعد كريما ناعم البال\nماذا يحاول أقوام بفعلهم،\nإذ لا يزال سفيه همه حالي\nلقد علمت بأني غالبي خلقي\nعلى السماحة ، صعلوكا وذا مال\nوالمال يغشى أناسا لا طباخ لهم،\nكالسيل يغشى أصول الدندن البالي\nأصون عرضي بمالي لا أدنسه،\nلا بارك الله بعد العرض في المال\nأحتال للمال، إن أودى فأجمعه،\nولست للعرض إن أودى بمحتال\nوالفقر يزري بأقوام ذوي حسب،\nويقتدى بلئام الأصل أنذال\nكم من أخي ثقة ، محض مضاربه،\nفارقته غير مقلي ولا قالي\nكالبدر كان على ثغر يسد به،\nفأصبح الثغر منه فرجه خالي\nثم تعزيت عنه، غير مختشع\nعلى الحوادث، في عرف وإجمال"},{"id":"diwan-hassan:174","bookId":"diwan-hassan","type":"poem","seq":174,"chapter":"قافية الباء","title":"عنوان القصيدة : وكنا ملوك الناس، قبل محمد","page":"ج1 ص172","text":"وكنا ملوك الناس، قبل محمد،\nفلما أتى الإسلام، كان لنا الفضل\nوأكرمنا الله الذي ليس غيره\nإله، بأيام مضت ما لها شكل\nبنصر الإله للنبي ودينه،\nوأكرمنا باسم مضى ما له مثل\nأولئك قومي خير قوم بأسرهم،\nوليس على معروفهم أبدا قفل\nيربون بالمعروف معروف من مضى\nفما عد من خير، فقومي له أهل\nإذا اختبطوا لم يفحشوا في نديهم،\nوليس على سؤالهم عندهم بخل\nوحاملهم واف بكل حمالة\nتحمل، لا غرم عليه، ولا خذل\nوجارهم فيهك بعلياء بيته،\nله ما ثوى فينا الكرامة والبذل\nوقائلهم بالحق أول قائل،\nفحكمهم عدل، وقولهم فصل\nإذا حاربوا، أو سالموا لم يشبهوا،\nفحربهم خوف، وسلمهم سهل\nومنا أمين المسلمين حياته،\nومن غسلته من جنابته الرسل"},{"id":"diwan-hassan:175","bookId":"diwan-hassan","type":"poem","seq":175,"chapter":"قافية الباء","title":"عنوان القصيدة : أتعرف الدار، عفا رسمها","page":"ج1 ص173","text":"أتعرف الدار، عفا رسمها،\nبعدك، صوب المسبل الهاطل\nبين السراديح، فأدمانة ،\nفمدفع الروحاء في حائل\nساءلتها عن ذاك، فاستعجمت،\nلم تدر ما مرجوعة السائل\nدع عنك دارا قد عفا رسمها،\nوابك على حمزة ذي النائل\nالمالىء الشيزى ، إذا أعصفت\nغبراء في ذي الشبم الماحل\nالتارك القرن لدى لبده،\nيعثر في ذي الخرص الذابل\nواللابس الخيل إذا أحجمت،\nكالليث في غابته الباسل\nأبيض في الذروة من هاشم،\nلم يمر دون الحق بالباطل\nما لشهيد بين أرماحكم،\nشلت يدا وحشي من قاتل\nإن أمرأ غودر في ألة\nمطرورة ، مارنة العامل\nأظلمت الأرض لفقدانه،\nواسود نور القمر الناصل\nصلى عليك الله في جنة\nعالية ، مكرمة الداخل\nكنا نرى حمزة حرزا لنا\nمن كل أمر نابنا نازل\nوكان في الإسلام ذا تدرإ،\nلم يك بالواني، ولا الخاذل\nلا تفرحي يا هند، واستحلبي\nدمعا، وأذري عبرة الثاكل\nوابكي على عتبة ، إذ قطه\nبالسيف تحت الرهج الجائل\nإذ خر في مشيخة منكم،\nمن كل عات قلبه، جاهل\nأرداهم حمزة في أسرة ،\nيمشون تحت الحلق الذائل\nغداة جبريل وزير له،\nنعم وزير الفارس الحامل"},{"id":"diwan-hassan:176","bookId":"diwan-hassan","type":"poem","seq":176,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد لقيت قريظة ما عظاها","page":"ج1 ص174","text":"لقد لقيت قريظة ما عظاها،\nوحل بحصنها ذل ذليل\nوسعد كان أنذرهم نصيحا\nبأن إلههم رب جليل\nفمل برحوا بنقض العهد حتى\nغزاهم في ديارهم الرسول\nأحاط بحصنهم منا صفوف،\nله من حر وقعتها صليل\nفصار المؤمنون بدار خلد،\nأقام لها بها ظل ظليل"},{"id":"diwan-hassan:177","bookId":"diwan-hassan","type":"poem","seq":177,"chapter":"قافية الباء","title":"عنوان القصيدة : نصروا نبيهم، وشدوا أزره","page":"ج1 ص175","text":"نصروا نبيهم، وشدوا أزره،\nبحنين، يوم تواكل الأبطال"},{"id":"diwan-hassan:178","bookId":"diwan-hassan","type":"poem","seq":178,"chapter":"قافية الباء","title":"عنوان القصيدة : يخاف أبي جنان العدو","page":"ج1 ص176","text":"يخاف أبي جنان العدو،\nويعلم أني أنا المعقل\nفلا وأخيك الكريم الذي\nفخرت به لا ترى تعتل\nفلا تقنع العام في دارهم،\nولا أستهد ولا أنكل\nأبا لك، لا مستجاف الفؤا\nد، يوم الهياج، ولا أعزل"},{"id":"diwan-hassan:179","bookId":"diwan-hassan","type":"poem","seq":179,"chapter":"قافية الباء","title":"عنوان القصيدة : رضيت حكومة المرقال قيس","page":"ج1 ص177","text":"رضيت حكومة المرقال قيس،\nوما أحسست إذ حكمت خالي\nله كف تفيض دما، وكف\nيباري جودها سح الشمال\nونحن الحاكمون بكل أمر\nقديما، نبتني شرف المعالي\nولا ينفك فينا ما بقينا\nمنير الوجه، أبيض كالهلال\nألا يا مال لا تزدد سفاها،\nقضية ماجد، ثبت المقال"},{"id":"diwan-hassan:180","bookId":"diwan-hassan","type":"poem","seq":180,"chapter":"قافية الباء","title":"عنوان القصيدة : وقافية عجت بليل، رزينة","page":"ج1 ص178","text":"وقافية عجت بليل، رزينة ،\nتلقيت من جو السماء نزولها\nيراها الذي لا ينطق الشعر عنده،\nويعجز عن أمثالها أن يقولها\nمتاريك أذناب الحقوق، إذا التوت\nأخذنا الفروع، واجتنينا أصولها\nمقاويل بالمعروف، خرس عن الخنا\nكرام، معاط للعشيرة سولها"},{"id":"diwan-hassan:181","bookId":"diwan-hassan","type":"poem","seq":181,"chapter":"قافية الباء","title":"عنوان القصيدة : ولقد بكيت، وعز مهلك جعفر","page":"ج1 ص179","text":"ولقد بكيت، وعز مهلك جعفر،\nحب النبي، على البرية كلها\nولقد جزعت، وقلت حين نعيت لي:\nمنء للجلاد لدى العقاب وظلها\nبالبيض، حين تسل من أغمادها،\nيوما، وإنهال الرماح وعلها\nبعد ابن فاطمة المبارك جعفر،\nخير البرية كلها وأجلها\nرزءا، وأكرمها جميعا محتدا،\nوأعزها متظلما، وأذلها\nللحق حين ينوب غير تنحل\nكذبا، وأغمرها ندى ، وأقلها\nفحشا، وأكثرها، إذا ما تجتدى ،\nفضلا، وأبذلها ندى ، وأدلها\nع الخير بعد محمد، لا شبهه\nبشر يعد من البرية جلها"},{"id":"diwan-hassan:182","bookId":"diwan-hassan","type":"poem","seq":182,"chapter":"قافية الباء","title":"عنوان القصيدة : أقام على عهد النبي وهديه","page":"ج1 ص180","text":"أقام على عهد النبي وهديه،\nحواريه والقول بالفعل يعدل\nأقام على منهاجه وطريقه،\nيوالي ولي الحق، والحق أعدل\nهو الفارس المشهور والبطل الذي\nيصول، إذا ما كان يوم محجل\nإذا كشفت عن ساقها الحرب حشها\nبأبيض سباق إلى الموت يرقل\nوإن امرأ كانت صفية أمه،\nومن أسد في بيتها لمرفل\nله من رسول الله قربى قريبة ،\nومن نصرة الإسلام مجد مؤثل\nفكم كربة ذب الزبير بسيفه\nعن المصطفى ، والله يعطي فيجزل\nفما مثله فيهم، ولا كان قبله،\nوليس يكون الدهر ما دام يذبل\nثناؤك خير من فعال معاشر،\nوفعلك، يا ابن الهاشمية ، أفضل"},{"id":"diwan-hassan:183","bookId":"diwan-hassan","type":"poem","seq":183,"chapter":"قافية الباء","title":"عنوان القصيدة : أخلاء الرخاء هم كثير","page":"ج1 ص181","text":"أخلاء الرخاء هم كثير،\nولكن في البلاء هم قليل\nفلا يغررك خلة من تؤاخي،\nفما لك عند نائبة خليل\nوكل أخ يقول: أنا وفي،\nولكن ليس يفعل ما يقول\nسوى خل له حسب ودين،\nفذاك لما يقول هو الفعول"},{"id":"diwan-hassan:184","bookId":"diwan-hassan","type":"poem","seq":184,"chapter":"قافية الباء","title":"عنوان القصيدة : علمتك، والله الحسيب، عفيفة","page":"ج1 ص182","text":"علمتك، والله الحسيب، عفيفة\nمن المؤمنات غير ذات غوائل\nحصانا رزان الرجل يشبع جارها\nوتصبح غرثى من لحوم الغوافل\nوما قلت في مال تريدين أخذه،\nبنية مهلا، إنني غير فاعل"},{"id":"diwan-hassan:185","bookId":"diwan-hassan","type":"poem","seq":185,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد ورث الضلالة عن أبيه","page":"ج1 ص183","text":"لقد ورث الضلالة عن أبيه،\nأبي، يوم فارقه الرسول\nجئت محمدا عظما رميما،\nلتكذبه، وأنت به جهول\nوقد نالت بنو النجار منكم،\nأمية ، إذ يغوث يا عقيل\nوتب ابنا ربيعة ، إذ أطاعا\nأبا جهل، لأمهما الهبول"},{"id":"diwan-hassan:186","bookId":"diwan-hassan","type":"poem","seq":186,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا الثقفي فاخركم، فقولوا","page":"ج1 ص184","text":"إذا الثقفي فاخركم، فقولوا:\nهلم، فعد شأن أبي رغال\nأبوكم الأم الآباء قدما،\nوأنتم مشبهوه على مثال\nمثال اللؤم، قد علمت معد،\nفليسوا بالصريح ولا الموالي\nثقيف شر من ركب المطايا،\nوأشباه الهجارس في القتال\nولو نطقت رحال الميس قالت:\nثقيف شر من فوق الرحال\nعبيد الفزر أورثهم بنيه،\nوآلى لا يبيعهم بمال\nوما لكرامة حبسوا، ولكن\nأراد هوانهم أخرى الليالي"},{"id":"diwan-hassan:187","bookId":"diwan-hassan","type":"poem","seq":187,"chapter":"قافية الباء","title":"عنوان القصيدة : جاءت مزينة من عمق لتنصرهم","page":"ج1 ص185","text":"جاءت مزينة من عمق لتنصرهم،\nفري، مزينة ، في أستاهك الفتل\nفكل شيء، سوى أن تذكروا شرفا،\nأو تبلغوا حسبا من شأنكم جلل\nقوم مدانيس لا يمشي بعقوتهم\nجار، وليس لهم في موطن بطل"},{"id":"diwan-hassan:188","bookId":"diwan-hassan","type":"poem","seq":188,"chapter":"قافية الباء","title":"عنوان القصيدة : أبلغ عبيدا بأن الفخر منقصة","page":"ج1 ص186","text":"أبلغ عبيدا بأن الفخر منقصة\nفي الصالحين، فلا يذهب بك الجذل\nلما رأيت بني عوف وإخوتهم\nعوفا وجمع بني النجار قد حفلوا\nقوم أباحوا حماكم بالسيوف، ولم\nيفعل بكم أحد في الناس ما فعلوا\nإذ أنتم لا تجيبون المضاف، وإذ\nتلقى خلال الديار الكاعب الفضل"},{"id":"diwan-hassan:189","bookId":"diwan-hassan","type":"poem","seq":189,"chapter":"قافية الباء","title":"عنوان القصيدة : وما كثرت بنو أسد فتخشى","page":"ج1 ص187","text":"وما كثرت بنو أسد فتخشى\nلكثرتها، ولا طاب القليل\nقبيلة تذبذب في معد،\nأنوفهم أذل من السبيل\nتمنى أن تكون إلى قريش\nشبيه البغل شبه بالصهيل"},{"id":"diwan-hassan:190","bookId":"diwan-hassan","type":"poem","seq":190,"chapter":"قافية الباء","title":"عنوان القصيدة : سماه معشره أبا حكم","page":"ج1 ص188","text":"سماه معشره أبا حكم،\nوالله سماه أبا جهل\nفما يجيء، الدهر، معتمرا\nإلا ومرجل جهله يغلي\nوكأنه مما يجيش به\nمبدي الفجور وسورة الجهل\nيغرى به سفع لعامظة ،\nمثل السباع شرعن في الضحل\nأبقت رياسته لمعشره\nغضب الإله وذلة الأصل\nإن ينتصر يدمى الجبين، وإن\nيلبث قليلا يود بالرحل\nقد رامني الشعراء، فانقلبوا\nمني بأفوق ساقط النصل\nويصد عني المفحمون، كما\nصد البكارة عن حرى الفحل\nيخشون من حسان ذا برد،\nهزم العشية ، صادق الوبل"},{"id":"diwan-hassan:191","bookId":"diwan-hassan","type":"poem","seq":191,"chapter":"قافية الباء","title":"عنوان القصيدة : وإن ثقيفا كان، فاعترفوا به","page":"ج1 ص189","text":"وإن ثقيفا كان، فاعترفوا به،\nلئيما، إذا ما نص للمجد معقل\nوأغضوا، فإن المجد عنكم وأهله\nعلى ما بكم من لؤمكم متعزل\nوخلوا معدا وانتسابا إليهم،\nبهم عنكم حقا تناء ومزحل\nوقول السفاه، واقصدوا لأبيكم\nثقيف، فإن القصد في ذاك أجمل\nفإنكم إن ترغبوا لا يكن لكم\nعن أصلكم في جذم قيس معول\nوما لكم في خندف من ولادة ،\nولا في قديم الخير مجد مؤثل"},{"id":"diwan-hassan:192","bookId":"diwan-hassan","type":"poem","seq":192,"chapter":"قافية الباء","title":"عنوان القصيدة : ويوم بدر، لقيناكم، لنا مدد","page":"ج1 ص190","text":"ويوم بدر، لقيناكم، لنا مدد،\nفيرفع النصر ميكال وجبريل"},{"id":"diwan-hassan:193","bookId":"diwan-hassan","type":"poem","seq":193,"chapter":"قافية الباء","title":"عنوان القصيدة : اللؤم خير من ثقيف كلها","page":"ج1 ص191","text":"اللؤم خير من ثقيف كلها\nحسبا، وما يفعل لئيم تفعل\nوبنى المليك من المخازي فوقهم\nبيتا، أقام عليهم لم ينقل\nإن هم أقاموا حل فوق رقابهم،\nأبدا، وإن يتحولوا يتحول\nقوم إذا ما صيح في حجراتهم\nلاقوا بأنذال تنابل عزل"},{"id":"diwan-hassan:194","bookId":"diwan-hassan","type":"poem","seq":194,"chapter":"قافية الباء","title":"عنوان القصيدة : بئس ما قاتلت خيابر عما","page":"ج1 ص192","text":"بئس ما قاتلت خيابر عما\nجمعت من مزارع ونخيل\nكرهوا الموت فاستبيح حماهم،\nوأقاموا فعل اللئيم الذليل\nأمن الموت ترهبون؟ فإن ال\nموت موت الهزال غير جميل"},{"id":"diwan-hassan:195","bookId":"diwan-hassan","type":"poem","seq":195,"chapter":"قافية الباء","title":"عنوان القصيدة : لست من المعشر الأكرمي","page":"ج1 ص193","text":"لست من المعشر الأكرمي\nن لا عبد شمس ولا نوفل\nوليس أبوك بساقي الحجي\nج، فاقعد على الحسب الأرذل\nولكن هجين منوط بهم،\nكما نوطت حلقة المحمل\nتجيش من اللؤم أحسابكم\nكجيش المشاشة في المرجل\nفلو كنت من هاشم في الصمي\nم لم تهجنا، وركي مصطلي"},{"id":"diwan-hassan:196","bookId":"diwan-hassan","type":"poem","seq":196,"chapter":"قافية الباء","title":"عنوان القصيدة : لك الخير غضي اللوم عني فإنني","page":"ج1 ص194","text":"لك الخير غضي اللوم عني فإنني\nأحب من الأخلاق ما كان أجملا\nذريني وعلمي بالأمور وشيمتي،\nفما طائري يوما عليك بأخيلا\nفإن كنت لا مني، ولا من خليقتي،\nفمنك الذي أمسى عن الخير أعزلا\nألم تعلمي أني أرى البخل سبة ،\nوأبغض ذا اللونين والمتنقلا\nإذا انصرفت نفسي عن الشيء مرة ،\nفلست إليه آخر الدهر مقبلا\nوإني، إذا ما الهم ضاف قريته\nزماعا، ومرقال العشيات عيهلا\nململمة ، خطارة ، لو حملتها\nعلى السيف لم تعدل عن السيف معدلا\nإذا انبعثت من مبرك غادرت به\nتوائم أمثال الزبائب ذبلا\nفإن بركت خوت على ثفناتها،\nكأن على حيزومها حرف أعبلا\nمروعة لو خلفها صر جندب،\nرأيت لها من روعة القلب أفكا\nوإنا لقوم ما نسود غادرا،\nولا ناكلا عند الحمالة زملا\nولا مانعا للمال فيما ينوبه،\nولا عاجزا في الحرب جبسا مغفلا\nنسود منا كل أشيب بارع،\nأغر، تراه بالجلال مكللا\nإذا ما انتدى أجنى الندى ، وابتنى العلا،\nوألفي ذا طول على من تطولا\nفلست بلاق ناشئا من شبابنا،\nوإن كان أندى من سوانا، وأحولا\nنطيع فعال الشيخ منا، إذا سما\nلأمر، ولا نعيا، إذا الأمر أعضلا\nله أربة في حزمه وفعاله،\nوإن كان منا حازم الرأي حولا\nوما ذاك إلا أننا جعلت لنا\nأكابرنا، في أول الخير، أولا\nفنحن الذرى من نسل آدم والعرى ،\nتربع فينا المجد حتى تأثلا\nبنى الز بيتا، فاستقرت عماده\nعلينا، فأعيا الناس أن يتحولا\nوإنك لن تلقى من الناس معشرا\nأعز من الأنصار عزا وأفضلا\nوأكثر أن تلقى ، إذا ما أتيتهم،\nلهم سيدا ضخم الدسيعة جحفلا\nوأشيب، ميمون النقيبة ، يبتغى\nبه الخطر الأعلى ، وطفلا مؤملا\nوأمرد مرتاحا، إذا ما ندبته\nتحمل ما حملته، فتربلا\nوعدا خطيبا لا يطاق جوابه،\nوذا أربة في شعره متنخلا\nوأصيد نهاضا إلى السيف، صارما،\nإذا ما دعا داع إلى الموت أرقلا\nوأغيد مختالا، يجر إزاره،\nكثير الندى ، طلق اليدين معذلا\nلنا حرة مأطورة بجبالها،\nبنى المجد فيها بيته، فتأهلا\nبها النخل والآطام تجري خلالها\nجداول، قد تعلو رقاقا وجرولا\nإذا جدول منها تصرم ماؤه،\nوصلنا إليه بالنواضح جدولا\nعلى كل مفهاق، خسيف غروبها،\nتفرغ في حوض من الصخر انجلا\nله غلل في ظل كل حديقة\nيعارض يعبوبا من الماء سلسلا\nإذا جئتها ألفيت، في حجراتها،\nعناجيج قبا والسوام المؤبلا\nجعلنا لها أسيافنا ورماحنا،\nمن الجيش والأعراب، كهفا ومعقلا\nإذ جمعوا جمعا سمونا إليهم\nبهندية تسقى الذعاف المثملا\nنصرنا بها خير البرية كلها،\nإماما، ووقرنا الكتاب المنزلا\nنصرنا، وآوينا، وقوم ضربنا\nله بالسيوف ميل من كان أميلا\nوإنك لن تلقى لنا من معنف،\nولا عائب، إلا لئيما مضللا\nوإلا أمرأ قد ناله من سيوفنا\nذباب، فأمسى مائل الشق أعزلا\nفمن يأتنا أو يلقنا عن جناية\nيجد عندنا مثوى كريما، وموئلا\nنجير، فلا يخشى البوادر جارنا،\nولاقى الغنى في دورنا، فتمولا"},{"id":"diwan-hassan:197","bookId":"diwan-hassan","type":"poem","seq":197,"chapter":"قافية الباء","title":"عنوان القصيدة : أجدك لم تهتج لرسم المنازل","page":"ج1 ص195","text":"أجدك لم تهتج لرسم المنازل،\nودار ملوك، فوق ذات السلاسل\nتجود الثريا فوقها، وتضمنت\nبردا يذري أصول الأسافل\nإذا عذرات الحي كان نتاجها\nكروما تدلى فوق أعرف ماثل\nديار زهاها الله لم يعتلج بها\nرعاء الشوي من وراء السوائل\nفمهما يكن مني، فلست بكاذب،\nولست بخوان الأمين المجامل\nوإني إذا ما قلت قولا فعلته،\nوأعرض عما ليس قلبي بفاعل\nومن مكرهي إن شئت أن لا أقوله،\nوفجع الأمين شيمة غير طائل"},{"id":"diwan-hassan:198","bookId":"diwan-hassan","type":"poem","seq":198,"chapter":"قافية الباء","title":"عنوان القصيدة : أبني الحماس! أليس منكم ماجد","page":"ج1 ص196","text":"أبني الحماس! أليس منكم ماجد،\nإن المروءة في الحماس قليل\nيا ويل أمكم، وويل أبيكم،\nويلا تردد فيكم وعويل\nهاجيتم حسان عند ذكائه،\nغي لمن ولد الحماس طويل\nإن الهجاء إليكم لبعلة ،\nفتحشحشوا إن الذليل ذليل\nلا تجزعوا أن تنسبوا لأبيكم،\nفاللؤم يبقى ، والجبال تزول\nفبنو زياد لم تلدك فحولهم،\nوبنو صلاءة فحلهم مشغول\nوسرى بكم تيس أجم، مجدر،\nما للذمامة عنكم تحويل\nفاللؤم حل على الحماس، فما لهم\nكهل يسود ولا فتى بهلول"},{"id":"diwan-hassan:199","bookId":"diwan-hassan","type":"poem","seq":199,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا قال لم يترك مقالا لقائل","page":"ج1 ص197","text":"إذا قال لم يترك مقالا لقائل،\nبملتقطات لا ترى بينها فصلا\nكفى وشفى ما في النفوس، فلم يدع\nلذي إربة ، في القول، جدا ولا هزلا\nسموت إلى العليا بغير مشقة ،\nفنلت ذراها لا دنيا، ولا وغلا"},{"id":"diwan-hassan:200","bookId":"diwan-hassan","type":"poem","seq":200,"chapter":"قافية الباء","title":"عنوان القصيدة : منعنا رسول الله، إذ حل وسطنا","page":"ج1 ص198","text":"منعنا رسول الله، إذ حل وسطنا،\nعلى انف راض من معد وراغم\nمنعناه لما حل وسط بيوتنا،\nبأسيافنا من كل باغ وظالم"},{"id":"diwan-hassan:201","bookId":"diwan-hassan","type":"poem","seq":201,"chapter":"قافية الباء","title":"عنوان القصيدة : لا تعد من رجلا أحلك بغضه","page":"ج1 ص199","text":"لا تعد من رجلا أحلك بغضه\nنجران، في عيش أحذ لئيم\nبليت قناتك في الحرو فألفيت\nخمانة جوفاء، ذات وصوم\nغضب الإله على الزبعرى وابنه،\nوعذاب سوء في الحياة مقيم"},{"id":"diwan-hassan:202","bookId":"diwan-hassan","type":"poem","seq":202,"chapter":"قافية الباء","title":"عنوان القصيدة : تبلت فؤادك في المنام خريدة","page":"ج1 ص200","text":"تبلت فؤادك في المنام خريدة ،\nتسقي الضجيع ببارد بسام\nكالمسك تخلطه بماء سحابة ،\nأو عاتق كدم الذبيح مدام\nنفج الحقيبة بوصها متنضد،\nبلهاء، غير وشيكة الأقسام\nبنيت على قطن أجم كأنه،\nفضلا إذا قعدت، مداك رخام\nوتكاد تكسل أن تجيء فراشها،\nفي لين خرعبة ، وحسن قوام\nأما النهار، فلا أفتر ذكرها،\nوالليل توزعني بها أحلامي\nأقسمت أنساها، وأترك ذكرها،\nحتى تغيب في الضريح عظامي\nيا من لعاذلة تلوم سفاهة ،\nولقد عصيت، إلى الهوى ، لوامي\nبكرت إلي بسحرة ، بعد الكرى ،\nوتقارب من حادث الأيام\nزعمت بأن المرء يكرب يومه\nعدم لمعتكر من الأصرام\nإن كنت كاذبة الذي حدثتني،\nفنجوت منجى الحارث بن هشام\nترك الأحبة أن يقاتل دونهم،\nونجا برأس طمرة ولجام\nجرواء، تمزع في الغبار كأنها\nسرحان غاب في ظلال غمام\nتذر العناجيج الجياد بقفرة ،\nمر الدموك بمحصد ورجام\nملأت به الفرجين، فارمدت به،\nوثوى أحبته بشر مقام\nوبنو أبيه ورهطه في معرك،\nنصر الإله به ذوي الإسلام\nلولا الإله وجريها لتركنه\nجزر السباع، ودسنه بحوامي\nطحنتهم والله ينفذ أمره،\nحرب يشب سعيرها بضرام\nمن كل مأسور يشد صفاده،\nصقر، إذا لاقى الكتيبة حامي\nومجدل لا يستجيب لدعوة ،\nحتى تزول شوامخ الأعلام\nبالعار والذل المبين، إذ رأوا\nبيض السيوف تسوق كل همام\nبيدي أغر، إذا انتمى لم يخزه\nنسب القصار، سميذع، مقدام\nبيض، إذا لاقت حديدا صممت\nكالبرق تحت ظلال كل غمام\nليسوا كيعمر حين يشتجر القنا،\nوالخيل تضبر تحت كل قتام\nفسلحت، إنك من معاشر خانة ،\nسلح، إذا حضر القتال، لئام\nفدع المكارم، إن قومك أسرة ،\nمن ولد شجع غير جد كرام\nمن صلب خندف ماجد أعراقه،\nنجلت به بيضاء ذات تمام\nومرنح فيه الأسنة شرعا،\nكالجفر غير مقابل الأعمام"},{"id":"diwan-hassan:203","bookId":"diwan-hassan","type":"poem","seq":203,"chapter":"قافية الباء","title":"عنوان القصيدة : لعمرك إن إلك من قريش","page":"ج1 ص201","text":"لعمرك إن إلك من قريش،\nكإل السقب من رأل النعام\nفإنك. إن تمت إلى قريش،\nكذات البو جائلة المرام\nوأنت منوط بهم هجين،\nكما نيط السرائح بالخدام\nفلا تفخر بقوم لست منهم،\nولا تك كاللئام بني هشام"},{"id":"diwan-hassan:204","bookId":"diwan-hassan","type":"poem","seq":204,"chapter":"قافية الباء","title":"عنوان القصيدة : ليت خبيبا لم تخنه أمانة ؛","page":"ج1 ص202","text":"ليت خبيبا لم تخنه أمانة ؛\nوليت خبيبا كان بالقوم عالما\nشراه زهير بن الأغر وجامع،\nوكانا قديما يركبان المحارما\nأجرتم، فلما أن أجرتم غدرتم\nوكنتم بأكناف الرجيع لهاذما"},{"id":"diwan-hassan:205","bookId":"diwan-hassan","type":"poem","seq":205,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا رأيت راعيين في غنم","page":"ج1 ص203","text":"إذا رأيت راعيين في غنم\nأسيدين يحلفان بنهم\nبينهما أشلاء لحم مقتسم\nمن بطن عمق ذي الجليل والسلم"},{"id":"diwan-hassan:206","bookId":"diwan-hassan","type":"poem","seq":206,"chapter":"قافية الباء","title":"عنوان القصيدة : ألم تسأل الربع الجديد التكلما","page":"ج1 ص204","text":"ألم تسأل الربع الجديد التكلما،\nبمدفع أشداخ، فبرقة أظلما\nأبى رسم دار الحي أن يتكلما،\nوهل ينطق المعروف من كان أبكما\nبقاع نقيع الجزع من بطن يلبن،\nتحمل منه أهله، فتتهما\nديار لشعثاء الفؤاد وتربها،\nليالي تحتل المراض، فتغلما\nوإذ هي حوراء المدامع ترتعي\nبمندفع الوادي أراكا منظما\nأقامت به بالصيف، حتى بدا لها\nنشاص، إذا هبت له الريح أرزما\nوقد أل من أعضاده، ودنا له\nمن الأرض دان جوزه، فتحمحما\nتحن مطافيل الرباع خلاله،\nإذا استن، في حافاته البرق، أثجما\nوكاد بأكناف العقيق وثيده\nيحط، من الجماء، ركنا ململما\nفلما علا تربان، وانهل ودقه،\nتداعى ، وألقى بركه وتهزما\nوأصبح منه كل مدفع تلعة\nيكب العضاه سيله، ما تصرما\nتنادوا بليل، فاستقلت حمولهم،\nوعالين أنماط الدرقل المرقما\nعسجن بأعناق الظباء، وأبرزت\nحواشي برود القطر وشيا منمنما\nفأنى تلاقيها، إذا حل أهلها\nبواد يمان، من غفار وأسلما\nتلاق بعيد، واختلاف من النوى ،\nتلاقيكها، حتى توفي موسما\nسأهدي لها في كل عام قصيدة ،\nوأقعد مكفيا بيثرب مكرما\nالست بنعم الجار يولف بيته\nلذي العرف ذا مال كثير ومعدما\nوندمان صدق تمطر الحير كفه،\nإذا راح فياض العشيات خضرما\nوصلت به ركني، ووافق شيمتي،\nولم أك عضا في الندامى ملوما\nوأبقى لنا مر الحروب، ورزؤها،\nسيوفا، وأدراعا، وجمعا عرمرما\nإذا اغبر آفاق السماء، وأمحلت\nكأن عليها ثوب عصب مسهما\nحسبت قدور الصاد، حول بيوتنا،\nقنابل دهما، في المحلة ، صيما\nيظل لديها الواغلون كأنما\nيوافون بحرا، من سميحة ، مفعما\nلنا حاضر فعم، وباد كأنه\nشماريخ رضوى عزة ، وتكرما\nمتى ما تزنا من معد بعصبة ،\nوغسان، نمنع حوضنا أن يهدما\nبكل فتى عاري الأشاجع، لاحه\nقراع الكماة ، يرشح المسك والدما\nإذا استدبرتنا الشمس درت متوننا،\nكأن عروق الجوف ينضحن عندما\nولدنا بني العنقاء وابني محرق،\nفأكرم بنا خلال وأكرم بنا ابنما\nنسود ذا المال القليل، إذا بدت\nمروءته فينا، وإن كان معدما\nوإنا لنقري الضيف، إن جاء طارقا،\nمن الشحم، ما أمسى صحيحا مسلما\nألسنا نرد الكبش عن طية الهوى ،\nونقلب مران الوشيج محطما\nوكائن ترى من سيد ذي مهانة\nأبوه أبونا، وابن أخت ومحرما\nلنا الجفنات الغر يلمعن بالضحى ،\nوأسيافنا يقطرن من نجدة دما\nأبى فعلنا المعروف أن ننطق الخنا،\nوقائلنا بالعرف إلا تكلما\nأبى جاهنا عند الملوك ودفعنا\nوملء جفان الشيز، حتى تهزما\nفكل معد قد جزينا بصنعهش،\nفبؤسى ببؤساها، وبالنعم أنعما"},{"id":"diwan-hassan:207","bookId":"diwan-hassan","type":"poem","seq":207,"chapter":"قافية الباء","title":"عنوان القصيدة : أولئك قومي، فإن تسألي","page":"ج1 ص205","text":"أولئك قومي، فإن تسألي،\nكرام، إذا الضيف يوما ألم\nعظام القدور لأيسارهم،\nيكبون فيها المسن، السنم\nيواسون مولاهم في الغنى ،\nويحمون جارهم إن ظلم\nوكانوا ملوكا بأرضيهم،\nيبادون غضبا، بأمر غشم\nملوكا على الناس لم يملكوا\nمن الدهر يوما، كحل القسم\nفأنبوا بعاد وأشياعها،\nثمود، وبعض بقايا إرم\nبيثرب قد شيدوا في النخيل\nحصونا، ودجن فيها النعم\nنواضح قد علمتها اليهود\nعل إليك، وقولا هلم\nوفيما اشتهوا من عصير القطاف،\nوعيش رخي على غيرهم\nفساروا إليهم بأثقالهم،\nعلى كل فحل هجان قطم\nجياد الخيول بأجنابهم،\nوقد جللوها ثخان الأدم\nفلما أناخوا بجنبي صرار،\nوشدوا السروج بلي الحزم\nفما راعهم غير معج الخيو\nل، والزحف من خلفهم قد دهم\nفطاروا شلالا وقد أفزعوا،\nوطرنا إليهم كأسد الأجم\nعلى كل سلهبة في الصيا\nن، لا تستكين لطول السأم\nوكل كميت، مطار الفؤاد،\nأمين الفصوص، كمثل الزلم\nعليها فوارس قد عاودوا\nقراع الكماة ، وضرب البهم\nليوث إذا غضبوا في الحرو\nب، لا ينكلون، ولكن قدم\nفأبنا بسادتهم والنسا\nء قسرا، وأموالهم تقتسم\nورثنا مساكنهم بعدهم،\nوكنا ملوكا بها لم نرم\nفلما أتانا رسول الملي\nك بالنور والحق بعد الظلم\nركنا إليه، ولم نعصه،\nغداة أتانا من ارض الحرم\nوقلنا: صدقت، رسول المليك،\nهلم إلينا، وفينا أقم\nفنشهد أنك، عند الملي\nك، أرسلت حقا بدين قيم\nفناد بما كنت أخفيته،\nنداء جهارا، ولا تكتتم\nفإنا وأولادنا جنة ،\nنقيك وفي مالنا فاحتكم\nفنحن ولاتك، إذ كذبوك،\nفناد نداء، ولا تحتشم\nفطار الغواة بأشياعهم\nإليه، يظنون أن يخترم\nفقمنا بأسيافنا دونه،\nنجالد عنه بغاة الأمم\nبكل صقيل، له ميعة ،\nرقيق الذباب، غموس خذم\nإذا ما يصادف صم العظا\nم لم ينب عنها، ولم ينثلم\nفذلك ما أورثتنا القرو\nم مجدا تليدا، وعزا أشم\nإذا مر قرن كفى نسله،\nوخلف إذا ما انقصم\nفما إن من الناس إلا لنا\nعليه، وإن خاس، فضل النعم"},{"id":"diwan-hassan:208","bookId":"diwan-hassan","type":"poem","seq":208,"chapter":"قافية الباء","title":"عنوان القصيدة : منع النوم، بالعشاء، الهموم","page":"ج1 ص206","text":"منع النوم، بالعشاء، الهموم،\nوخيال، إذا تغور النجوم\nمن حبيب أصاب قلبك منه\nسقم، فهو داخل مكتوم\nيا لقوم هل يقتل المرء مثلي\nواهن البطش والعظام، سؤوم\nهمها العطر، والفراش، ويعلو\nها لجين ولؤلؤ منظوم\nلو يدب الحولي من ولد الذ\nر عليها، لأندبتها الكلوم\nلم تفقها شمس النهار بشيء،\nغير أن الشباب ليس يدوم\nإن خالي خطيب جابية الجو\nلان عند النعمان حين يقوم\nوأبي، في سميحة ، القائل الفا\nصل، يوم التقت عليه الخصوم\nوأنا الصقر عند باب ابن سلمى ،\nيوم نعمان في الكبول مقيم\nوأبي، ووافد أطلقا لي،\nثم رحنا، وقفلهم محطوم\nورهنت اليدين عنهم جميعا،\nكل كف فيها جز مقسوم\nوسطت نسبتي الذوائب منهم،\nكل دار فيها أب لي عظيم\nرب حلم أضاعه عدم الما\nل، وجهل غطى عليه النعيم\nما أبالي أنب بالحزن تيس،\nأم لحاني بظهر غيب لئيم\nتلك أفعالنا، وفعل الزبعرى\nخامل في صديقه، مذموم\nولي البأس منكم، إذ حضرتم،\nأسرة من بني قصي، صميم\nتسعة تحمل اللواء، وطارت،\nفي رعاع من القنا، مخزوم\nلم يولوا، حتى أبيدوا جميعا،\nفي مقام، وكلهم مذموم\nبدم عاتك، وكان حفاظا\nأن يقيموا، إن الكريم كريم\nوأقاموا حتى أزيروا شعوبا،\nوالقنا، في نحورهم، محطوم\nوقريش تلوذ منا لواذا،\nلم يقيموا، وخف منها الحلوم\nلم تطق حمله العواتق منهم،\nإنما يحمل اللواء النجوم"},{"id":"diwan-hassan:209","bookId":"diwan-hassan","type":"poem","seq":209,"chapter":"قافية الباء","title":"عنوان القصيدة : ما هاج حسان رسوم المقام","page":"ج1 ص207","text":"ما هاج حسان رسوم المقام،\nومظعن الحي، ومبنى الخيام\nوالنؤي، قد هدم أعضاده\nتقادم العهد، بواد تهام\nقد أدرك الواشون ما حاولوا،\nفالحبل من شعثاء رث الرمام\nجنية أرقني طيفها،\nتذهب صبحا وترى في المنام\nهل هي إلا ظبية مطفل،\nمألفها السدر بنعفي برام\nتزجي غزالا، فاترا طرفه،\nمقارب الخطو، ضعيف البغام\nكأن فاها ثغب بارد\nفي رصف، تحت ظلال الغمام\nشجت بصهباء، لها سورة ،\nمن بيت رأس عتقت في الخيام\nعتقها الحانوت دهرا، فقد\nمر عليها فرط عام، فعام\nنشربها صرفا وممزوجة ،\nثم نغني في بيوت الرخام\nتدب في الجسم دبيبا، كما\nدب دبى ، وسط رقاق هيام\nكأسا، إذا ما الشيخ والى بها\nخمسا، تردى برداء الغلام\nمن خمر بيسان تخيرتها،\nترياقة تورث فتر العظام\nيسعى بها أحمر، ذو برنس،\nمختلق الذفرى ، شديد الحزام\nأروع، للدعوة مستعجل،\nلم يثنه الشان، خفيف القيام\nدع ذكرها، وانم إلى جسرة ،\nجلذية ، ذات مراح عقام\nدفقة المشية ، زيافة ،\nتهوي خنوفا في فضول الزمام\nتحسبها مجنونة تغتلي،\nإذ لفع الآل رؤوس الإكام\nقومي بنو النجار، إذ أقبلت\nشهباء ترمي أهلها بالقتام\nلا نخذل الجار ولا نسلمال\nمولى ، ولا نخصم يوم الخصام\nمنا الذي يحمد معروفه،\nويفرج اللزبة يوم الزحام"},{"id":"diwan-hassan:210","bookId":"diwan-hassan","type":"poem","seq":210,"chapter":"قافية الباء","title":"عنوان القصيدة : هل المجد إلا السودد العود والندى","page":"ج1 ص208","text":"هل المجد إلا السودد العود والندى ،\nوجاه الملوك، واحتمال العظائم\nنصرنا وآوينا النبي محمدا،\nعلى أنف راض من معد وراغم\nبحي حريد أصله، وذماره\nبجابية الجولان، وسط الأعاجم\nنصرناه لما حل وسط رحالنا،\nبأسيافنا من كل باغ وظالم\nجعلنا بنينا دونه، وبناتنا،\nوطبنا له نفسا بفيء المغانم\nونحن ضربنا الناس، حتى تتابعوا،\nعلى دينه، بالمرهفات الصوارم\nونحن ولدنا من قريش عظيمها،\nولدنا نبي الخير من آل هاشم\nلنا الملك في الإشراك، والسبق في الهدى\nونصر النبي، وابتناء المكارم\nبني دارم لا تفخروا، إن فخركم\nيعود وبالا عند ذكر المكارم\nهبلتم! علينا تفخرون، وأنتم\nلنا خول من بين ظئر وخادم\nفإن كنتم جئتم لحقن دمائكم،\nوأموالكم أن تقسموا في المقاسم\nفلا تجعلوا لله ندا وأسلموا،\nولا تلبسوا زيا كزي الأعاجم\nوإلا أبحناكم وسقنا نساءكم،\nبضم القنا، والمقربات الصلادم\nوأفضل ما نلتم من المجد والعلى\nرادفتنا، عند احتضار المواسم"},{"id":"diwan-hassan:211","bookId":"diwan-hassan","type":"poem","seq":211,"chapter":"قافية الباء","title":"عنوان القصيدة : إبك، بكت عيناك ثم تبادرت","page":"ج1 ص209","text":"إبك، بكت عيناك ثم تبادرت\nبدم يعل غروبها، سجام\nماذا بكيت على الذين تتابعوا،\nهلا ذكرت مكارم الأقوام\nوذكرت منا ماجدا، ذا همة ،\nسمح الخلائق، ماجد الإقدام\nأعني النبي، أخا التكرم والندى ،\nوأبر من يولي على الأقسام\nفلمثله، ولمثل ما يدعو له،\nكان الممدح، ثم، غير كهام"},{"id":"diwan-hassan:212","bookId":"diwan-hassan","type":"poem","seq":212,"chapter":"قافية الباء","title":"عنوان القصيدة : ما بال عينك، يا حسان، لم تنم","page":"ج1 ص210","text":"ما بال عينك، يا حسان، لم تنم،\nما إن تغمض، إلا مؤثم القسم\nلم أحسب الشمس تبدو بالعشاء، فقد\nلاقيت شمسا تجلي ليلة الظلم\nفرع النساء، وفرع القوم والدها،\nأهل الجلالة ، والإيفاء بالذمم\nلقد حلفت، ولم تحلف على كذب،\nيابن الفريعة ، ما كلفت من أمم"},{"id":"diwan-hassan:213","bookId":"diwan-hassan","type":"poem","seq":213,"chapter":"قافية الباء","title":"عنوان القصيدة : ألين، إذا لان العشير، فإن تكن","page":"ج1 ص211","text":"ألين، إذا لان العشير، فإن تكن\nبه جنة ، فجنتي أنا أقدم\nقريب، بعيد خيره، قبل شره،\nإذا طلبوا مني الغرامة أغرم\nإذا مات منا سيد ساد مثله،\nرحيب الذراع بالسيادة ، خضرم\nيجيب إلى الجلى ، ويحتضر الوغى ،\nأخو ثقة يزداد خيرا ويكرم"},{"id":"diwan-hassan:214","bookId":"diwan-hassan","type":"poem","seq":214,"chapter":"قافية الباء","title":"عنوان القصيدة : تناولني كسرى ببؤسي، ودونه","page":"ج1 ص212","text":"تناولني كسرى ببؤسي، ودونه\nقفاف من الصمان، فالمتثلم\nففجعني، لا وفق الله أمره،\nبأبي، وهاب، قليل التجهم\nلتعف مياه الحارثين، وقد عفت\nمياههما من كل حي عرمرم\nوأقفر من حضاره ورد أهله،\nوكان يروي في قلال، وحنتم\nوقلت لعين بالجوبة يا اسلمي،\nنعم ثم لم تنطق، ولم تتكلم\nديار ملوك قد أراهم بغبطة ،\nزمان عمود الملك لم يتهدم\nلعمري لحرث بين قف ورملة ،\nببرث علت أنهاره كل مخرم\nلدى كل بنيان رفيع، ومجلس\nنشاوى ، وكأس أخلصت لم تصرم\nأحب إلى حسان، لو يستطيعه،\nمن المرقصات، من غفار وأسلم"},{"id":"diwan-hassan:215","bookId":"diwan-hassan","type":"poem","seq":215,"chapter":"قافية الباء","title":"عنوان القصيدة : الله أكرمنا بنصر نبيه","page":"ج1 ص213","text":"الله أكرمنا بنصر نبيه،\nبونا أقام دعائم الإسلام\nوبنا أعز نبيه وكتابه،\nوأعزنا بالضرب والإقدام\nفي كل معترك تطير سيوفنا\nفيه الجماجم عن فراخ الهام\nينتابنا جبريل في أبياتنا،\nبفرائض الإسلام، والأحكام\nيتلو علينا النور فيها محكما،\nقسما لعمرك ليس كالأقسام\nفنكون أول مستحل حلاله،\nومحرم لله كل حرام\nنحن الخيار من البرية كلها،\nونظامها، وزمام كل زمام\nالخائضو غمرات كل منية ،\nوالضامنون حوادث الأيام\nوالمبرمون قوى الأمور بعزمهم،\nوالناقضون مرائر الأقوام\nسائل أبا كرب، وسائل تبعا،\nعنا، وأهل العتر والأزلام\nواسأل ذوي الألباب عن سرواتهم\nيوم العهين، فحاجر، فرؤام\nإنا لنمنع من أردنا منعه،\nونجود بالمعروف للمعتام\nوترد عافية الخميس سيوفنا،\nونقين رأس الأصيد القمقام\nما زال وقع سيوفنا ورماحنا\nفي كل يوم تجالد وترام\nحتى تركنا الأرض حزنها،\nمنظومة من خيلنا بنظام\nونجا أراهط أبعطوا، ولو أنهم\nثبتوا، لما رجعوا إذا بسلام\nفلئن فخرت بهم لمثل قديمهم\nفخر اللبيب به على الأقوام"},{"id":"diwan-hassan:216","bookId":"diwan-hassan","type":"poem","seq":216,"chapter":"قافية الباء","title":"عنوان القصيدة : إن ابن جفنة من بقية معشر","page":"ج1 ص214","text":"إن ابن جفنة من بقية معشر\nلم يغذهم آباؤهم باللوم\nلم ينسني بالشام، إذ هو ربها،\nكلا ولا منتصرا بالروم\nيعطي الجزيل، ولا يراه عنده\nإلا كبعض عطية المذموم\nوأتيته يوما، فقرب مجلسي،\nوسقى فرواني من الخرطوم"},{"id":"diwan-hassan:217","bookId":"diwan-hassan","type":"poem","seq":217,"chapter":"قافية الباء","title":"عنوان القصيدة : لمن منزل عاف كأن رسومه","page":"ج1 ص215","text":"لمن منزل عاف كأن رسومه\nخياعيل ريط سابري مرسم\nخلاء المبادي ما به غير ركد\nثلاث، كأمثال الحمائم جثم\nوغير شجيج ماثل حالف البلى ،\nوغير بقايا كالسحيق المنمنم\nتعل رياح الصيف بالي هشيمه،\nعلى ماثل كالحوض، عاف، مثلم\nكسته سرابيل البلى بعد عهده،\nوجون سرى بالوابل المتهزم\nوقد كان ذا أهل كبير وغبطة ،\nإذا الحبل، حبل الوصل، لم يتصرم\nوإذ نحن جيران كثير بغبطة ،\nوإذ مضى من عيشنا لم يصرم\nوكل حثيث الودق منبعق العرى ،\nمتى تزجه الريح اللواقح يسجم\nضعيف العرى دان من الأرض بركه\nمسف كمثل الطود أكظم أسحم\nفإن تك ليلى قد نأتك ديارها،\nوضنت بحاجات الفؤاد المتيم\nوهمت بصرم الحبل بعد وصاله،\nوأصغت لقول الكاشح المتزعم\nفما حبلها بالرث عندي، ولا الذي\nيغيره نأي، وإن لم تكلم\nوما حبها لو وكلتني بوصله،\nولو صرم الخلان، بالمتصرم\nلعمر أبيك الخير ما ضاع سركم\nلدي، فتجزيني بعادا وتصرمي\nولا ضقت ذرعا بالهوى إذ ضمنته،\nولا كظ صدري بالحديث المكتم\nولا كان مما كان مما تقولوا\nعلي، ونثوا، غير ظن مرجم\nفإن كنت لما تخبرين، فسائلي\nذوي العلم عنا كي تنبي فتعلمي\nمتى تسألي عنا تنبي بأننا\nكرام وأنا أهل عز مقدم\nوأنا عرانين صقور، مصالت،\nنهز قناة ، متنها لم يوصم\nلعمرك ما المعتر يأتي بلادنا\nلنمنعه بالضائع المتهضم\nوما السيد الجبار، حين يريدنا\nبكيد، على أرماحنا بمحرم\nولا ضيفنا عند القرى بمدفع،\nوما جارنا في النائبات بمسلم\nنبيح حمى ذي العز حين نكيده،\nونحمي حمان بالوشيج المقوم\nونحن إذا لم يبرم الناس أمرهم،\nنكون على أمر من الحق مبرم\nولو وزنت رضوى بحلم سراتنا\nلمال برضوى حلمنا ويلملم\nونحن إذا ما الحرب حل صرارها،\nوجادت على الحلاب بالموت والدم\nولم يرج إلا كل أروع ماجد،\nشديد القوى ، ذي عزة وتكرم\nنكون زمام القائدين إلى الوغى ،\nإذا الفشل الرعديد لم يتقدم\nفنحن كذاك، الدهر، ما هبت الصبا\nنعود على جهالهم بالتحلم\nفلو فهموا، أو وفقوا رشد أمرهم،\nلعدنا عليهم بعد بؤسى بأنعم\nإنا إذا ما الأفق أمسى كأنما\nعلى حافتيه ممسيا لون عندم\nلنطعم في المشتى ، ونطعن بالقنا،\nإذا الحرب عادت كالحريق المضرم\nوتلقى لدى أبياتنا، حين نجتدى ،\nمجالس فيها كل كهل معمم\nرفيع عماد البيت، يستر عرضه،\nمن الذم، ميمون النقيبة خضرم\nجواد على العلات، رحب فناؤه،\nمتى يسأل المعروف لا يتجهم\nضروب بأعجاز القداح إذا شتا،\nسريع إلى داعي الهياج، مصمم\nأشم طويل الساعدين سميذع،\nمعيد قراع الدراعين، مكلم"},{"id":"diwan-hassan:218","bookId":"diwan-hassan","type":"poem","seq":218,"chapter":"قافية الباء","title":"عنوان القصيدة : أعين، ألا أبكي سيد الناس، واسفحي","page":"ج1 ص216","text":"أعين، ألا أبكي سيد الناس، واسفحي\nبدمع فإن أنزفته فاسكبي الدما\nوبكي عظيم المشعرين وربها،\nعلى الناس، معروف له ما تكلما\nفلو كان مجد يخلد اليوم واحدا\nمن الناس، أبقى مجده اليوم مطعما\nأجرت رسول الله منهم، فأصبحوا\nعبادك ما لبى ملب، وأحرما\nفلو سئلت عنه معد بأسرها،\nوقحطان، أو باقي بقية جرهما\nلقالوا: هو الموفي بخفرة جاره،\nوذمته يوما، إذا ما تذمما\nفما تطلع الشمس المنيرة فوقهم،\nعلى مثله، منهم أعز وأكرما\nإباء، إذا يأبى ، وأكرم شيمة ،\nوأنوم عن جار، إذا الليل أظلما"},{"id":"diwan-hassan:219","bookId":"diwan-hassan","type":"poem","seq":219,"chapter":"قافية الباء","title":"عنوان القصيدة : إني، لعمر أبيك، شر من أبي","page":"ج1 ص217","text":"إني، لعمر أبيك، شر من أبي،\nولأنت خير من أبيك وأكرم\nوبنوك نوكى ، كلهم ذو علة ،\nولأنت شر من بنيك وألأم"},{"id":"diwan-hassan:220","bookId":"diwan-hassan","type":"poem","seq":220,"chapter":"قافية الباء","title":"عنوان القصيدة : أبلغ بني عمرو بأن اخاهم","page":"ج1 ص218","text":"أبلغ بني عمرو بأن اخاهم\nشراه امرؤ، قد كان للشر لازما\nشراه زهير بن الأغر وجامع،\nوكانا قديما يركبان المحارما\nأجرتم، فلما أن أجرتم غدرتم\nوكنتم بأكناف الرجيع لهاذما\nفليت خبيبا لم تخنه أمانة ،\nوليت خبيبا كان بالقوم عالما"},{"id":"diwan-hassan:221","bookId":"diwan-hassan","type":"poem","seq":221,"chapter":"قافية الباء","title":"عنوان القصيدة : وصقعب والد لأبيك قين","page":"ج1 ص219","text":"وصقعب والد لأبيك قين\nلئيم، حل في شعب الأروم\nوبطن حباشة السوداء عدد،\nوسائل كل ذي حسب كريم\nتسمون المغيرة ، وهو ظلم،\nوينسى ديسم الإسم القديم"},{"id":"diwan-hassan:222","bookId":"diwan-hassan","type":"poem","seq":222,"chapter":"قافية الباء","title":"عنوان القصيدة : باهى ابن صقعب، إذ أثرى ، بكلبته","page":"ج1 ص220","text":"باهى ابن صقعب، إذ أثرى ، بكلبته،\nقل لابن صقعب: أخف الشخص واكتتم\nقل للوليد: متى سميت باسمك ذا،\nأم كان ديسم في الأسماء كالحلم\nوإذ حباشة أم لا تسر بها،\nلا ناكح في الذرى زوجا، ولم تئم\nفالحق بقينك، قين السوء، إن له\nكيرا بباب عجوز السوء، لم يرم\nتلكم مصانعكم في الدهر قد عرفت،\nضرب النصال، وحسن الرقع للبرم"},{"id":"diwan-hassan:223","bookId":"diwan-hassan","type":"poem","seq":223,"chapter":"قافية الباء","title":"عنوان القصيدة : لقد علمت بنو النجار أني","page":"ج1 ص221","text":"لقد علمت بنو النجار أني\nأذود عن العشيرة بالحسام\nوقد أبقيت في سهم علوبا\nإلى يوم التغابن والخصام\nفلا تفخر فقد غلبت قديما\nعليك مشابه من آل حام\nفلست إلى الذوائب من قصي،\nولا في عز زهرة إذ تسامي\nولا في الفرع من ابناء عمرو،\nولا في فرع مخزوم الكرام\nفأقصر عن هجاء بني قصي،\nفقد جربت وقع بني حرام"},{"id":"diwan-hassan:224","bookId":"diwan-hassan","type":"poem","seq":224,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا إن ادعاء بني قصي","page":"ج1 ص222","text":"ألا إن ادعاء بني قصي،\nعلى من لا يناسبهم، حرام\nفإنك وادعاء بني قصي\nلكالمجرى وليس له لجام\nفلا تفخر، فإن بني قصي\nهم الرأس المقدم، والسنام\nوأهل الصيت والسورات قدما،\nمقدمها، إذا نسب الكرام\nهم أعطوا منازلها قريشا،\nبمكة ، وهي ليس لها نظام\nفلا تفخر بقوم لست منهم،\nفإن قبيلك الهجن اللئام\nإذا عد الأطايب من قريش\nتقاعدكم إلى المخزاة حام\nقسامة أمكم، إن تنسبوها\nإلى نسب فتأنفه الكرام"},{"id":"diwan-hassan:225","bookId":"diwan-hassan","type":"poem","seq":225,"chapter":"قافية الباء","title":"عنوان القصيدة : سألت قريشا وقد خبروا","page":"ج1 ص223","text":"سألت قريشا وقد خبروا،\nوكل قريش بكم عالم\nفقالت قريش، ولم يكذبوا،\nوقول قريش لكم لازم\nعبيد قيون، إذا حصلوا،\nأبوكم لدى كيره جاثم\nفسائل هشاما، إذا جئته،\nوخرقة ، عيب لكم دائم\nأطبخ الإهالة أم حقنها،\nفأنفك من ريحها وارم\nوجمرة عار لكم ثابت،\nفقلبك من ذكرها واجم"},{"id":"diwan-hassan:226","bookId":"diwan-hassan","type":"poem","seq":226,"chapter":"قافية الباء","title":"عنوان القصيدة : نالت قريش ذرى العلياء، فانخنثت","page":"ج1 ص224","text":"نالت قريش ذرى العلياء، فانخنثت\nبنو المغيرة عن مجد اللهاميم\nوافتخروا بأمور، أهلها نفر،\nأحسابهم من قصي في الغلاصيم\nبندوة من قصي كان ورثها،\nوباللواء ، وحجاب فخاقيم\nمن جوهر من قريش فالتمس بدلا\nمنهم معانيق في الهيجا، مقاديم\nواترك مآثر قوم في بيوتهم،\nوافخر بمكرمة في بيت مخزوم\nأو من بني شجع إن كنت ذا نسب\nحر من القوم، منسوب، ومعلوم\nهلا منعتم من المخزاة أمكم،\nعند الثنية من عمرو بن يحموم\nبنو المغيرة فحش في نديهم،\nتوارثوا الجهل، بعد الكفر واللوم"},{"id":"diwan-hassan:227","bookId":"diwan-hassan","type":"poem","seq":227,"chapter":"قافية الباء","title":"عنوان القصيدة : لعمر أبي سمية ما أبالي","page":"ج1 ص225","text":"لعمر أبي سمية ما أبالي\nأنب التيس أم نطقت جذام\nإذا ما شاتهم ولدت تادوا:\nأجدي، تحت شاتك، أم غلام؟"},{"id":"diwan-hassan:228","bookId":"diwan-hassan","type":"poem","seq":228,"chapter":"قافية الباء","title":"عنوان القصيدة : ألم تر أن طلحة من قريش","page":"ج1 ص226","text":"ألم تر أن طلحة من قريش\nيعد من القماقمة الكرام\nوكان أبوه، بالبلقاء، دهرا\nيسوق الشول في جنح الظلام\nهو الرجل الذي جلب ابن سعد\nوعثمانا من البلد الشآم\nهو الرجل الذي حدثت عنه،\nغريب بين زمزم والمقام"},{"id":"diwan-hassan:229","bookId":"diwan-hassan","type":"poem","seq":229,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا ذكرت عقيلة بالمخازي","page":"ج1 ص227","text":"إذا ذكرت عقيلة بالمخازي، إذا ذكرت عقيلة بالمخازي،\nتقنع من مخازيها اللئام\nأبو صيفي الذي قد كان منها،\nومخرمة الدعي المستهام\nإذا شتموا بأمهم تولوا\nسراعا ما يبين لهم كلام"},{"id":"diwan-hassan:230","bookId":"diwan-hassan","type":"poem","seq":230,"chapter":"قافية الباء","title":"عنوان القصيدة : أبا لهب! أبلغ بأن محمدا","page":"ج1 ص228","text":"أبا لهب! أبلغ بأن محمدا\nسيعلو بما أدى ، وإ كنت راغما\nوإن كنت قد كذبته وخذلته\nوحيدا، وطاوعت الهجين الضراغما\nولو كنت حرا في أرومة هاشم،\nوفي سرها منهم منعت المظالما\nولكن لحيانا أبوك ورثته،\nومأوى الخنا منهم، فدع عنك هاشما\nسمت هاشم للمكرمات وللعلى ،\nوغودرت في كأب من اللؤم جاثما"},{"id":"diwan-hassan:231","bookId":"diwan-hassan","type":"poem","seq":231,"chapter":"قافية الباء","title":"عنوان القصيدة : من سره الموت صرفا لا مزاج له","page":"ج1 ص229","text":"من سره الموت صرفا لا مزاج له،\nفليأت مأسدة في دار عثمانا\nمستحقبي حلق الماذي، قد سعفت\nفوق المخاطم، بيض زان أبدانا\nبل ليت شعري، وليت الطير تخبرني\nما كان شأن علي وابن عفانا\nضحوا بأشمط عنوان السجود به\nيقطع الليل تسبيحا وقرآنا\nلتسمعن وشيكا في ديارهم،\nالله أكبر، يا ثارات عثمانا\nوقد رضيت بأهل الشأم زافرة ،\nوبالأمير، وبالإخوان إخوانا\nإني لمنهم، وإن غابوا، وإن شهدوا،\nحتى الممات، وما سميت حسانا\nويها فدى لكم أمي وما ولدت،\nقد ينفع الصبر في المكروه أحيانا\nشدوا السيوف بثني، في مناطقكم،\nحتى يحين بها في الموت من حانا\nلعلكم أن تروا يوما بمغبطة ،\nخليفة الله فيكم كالذي كانا"},{"id":"diwan-hassan:232","bookId":"diwan-hassan","type":"poem","seq":232,"chapter":"قافية الباء","title":"عنوان القصيدة : يا للرجال لدمع هاج بالسنن","page":"ج1 ص230","text":"يا للرجال لدمع هاج بالسنن،\nإني عجبت لمن يبكي على الدمن\nإني رأيت أمين الله مضطهدا،\nعثمان رهنا لدى الأجداث والكفن\nيا قاتل الله قوما كان شأنهم\nقتل الإمام الأمن المسلم الفطن\nما قاتلوه على ذنب ألم به،\nإلا الذي نطقوا زورا ولم يكن\nإذا تذكرته فاضت بأربعة\nعيني بدمع، على الخدين، محتتن"},{"id":"diwan-hassan:233","bookId":"diwan-hassan","type":"poem","seq":233,"chapter":"قافية الباء","title":"عنوان القصيدة : ومسترق النخامة مستكين","page":"ج1 ص231","text":"ومسترق النخامة مستكين\nلوقع الكأس، مختلس البيان\nحلفت له بها حجت قريش\nوكل مشعشع م الخمر آن\nلتصطحبن، وإن أعرضت عنها،\nولو أني بحيبته سقاني\nفطافت طوفتين، فقال: زدني،\nودبت في الأخادع والبنان\nفلم أعرف أخي حتى اصطبحنا\nثلاثا، فانبرى خذم العنان\nفلان الصوت، فانبسطت يداه،\nوكان كأنه في الغل عان\nوراح ثيابه الأولى سواها،\nبلا بيع، أميم، ولا مهان"},{"id":"diwan-hassan:234","bookId":"diwan-hassan","type":"poem","seq":234,"chapter":"قافية الباء","title":"عنوان القصيدة : وممسك بصداع الرأس من سكر","page":"ج1 ص232","text":"وممسك بصداع الرأس من سكر،\nناديته وهو مغلوب، ففداني\nلما صحا وتراخى العيش قلت له:\nإن الحياة ، وإن الموت مثلان\nفاشرب من الخمر ما آتاك مشربه،\nواعلم بأن كل عيش صالح فان"},{"id":"diwan-hassan:235","bookId":"diwan-hassan","type":"poem","seq":235,"chapter":"قافية الباء","title":"عنوان القصيدة : إما سألت، فإنا معشر نجب","page":"ج1 ص233","text":"إما سألت، فإنا معشر نجب،\nالأزد نسبتنا، والماء غسان\nشم الأنوف، لهم مجد ومكرمة ،\nكانت لهم كجبال الطود أركان"},{"id":"diwan-hassan:236","bookId":"diwan-hassan","type":"poem","seq":236,"chapter":"قافية الباء","title":"عنوان القصيدة : إن شرخ الشباب والشعر الأس","page":"ج1 ص234","text":"إن شرخ الشباب والشعر الأس\nود ما لم يعاص كان جنونا\nما التصابي على المشيب وقد قل\nبت من ذاك أظهرا وبطونا\nإن يكن غث من رقاش حديث،\nفبما نأكل الحديث سمينا\nوانتصينا نواصي اللهو يوما،\nوبعثنا جناتنا يجتنونا\nفجنونا جنى شهيا، حليا،\nوقضوا جوعهم، وما يأكلونا\nوأمين حدثته سر نفسي،\nفرعاه حفظ الأمين الأمينا\nمخمر سره، إذا ما التقينا،\nثلجت نفسه بإن لا أخونا"},{"id":"diwan-hassan:237","bookId":"diwan-hassan","type":"poem","seq":237,"chapter":"قافية الباء","title":"عنوان القصيدة : وقد كنا نقول، إذا رأينا","page":"ج1 ص235","text":"وقد كنا نقول، إذا رأينا\nلذي جسم يعد وذي بيان\nكأنك، أيها المعطى بيانا\nوجسما، من بني عبد المدان"},{"id":"diwan-hassan:238","bookId":"diwan-hassan","type":"poem","seq":238,"chapter":"قافية الباء","title":"عنوان القصيدة : لمن الدار أوحشت بمعان","page":"ج1 ص236","text":"لمن الدار أوحشت بمعان،\nبين أعلى اليرموك، فالخمان\nفالقريات من بلاس فدار\nيا، فسكاء، فالقصور الدواني\nفقفا جاسم، فأودية الص\nفر، مغنى قبائل وهجان\nتلك دار العزيز، بعد أنيس،\nوحلول عظيمة الأركان\nثكلت أمهم، وقد ثكلتهم،\nيوم حلوا بحارث الجولان\nقد دنا الفصح، فالولائد ينظم\nن سراعا أكلة المرجان\nيجتنين الجادي في نقب الري\nط، عليها مجاسد الكتان\nلم يعللن بالمغافر والصم\nغ وا نقف حنظل الشريان\nذاك مغنى من آل جفنة في الده\nر، وحق تعاقب الأزمان\nقد أراني هناك، حق مكين،\nعند ذي التاج مجلسي ومكاني"},{"id":"diwan-hassan:239","bookId":"diwan-hassan","type":"poem","seq":239,"chapter":"قافية الباء","title":"عنوان القصيدة : ويثرب تعلم أنا بها","page":"ج1 ص237","text":"ويثرب تعلم أنا بها،\nإذا التبس الامر، ميزانها\nويثرب تعلم أنا بها،\nإذا قحط القطر، نوءانها\nويثرب تعلم أنا بها،\nإذا خافت الأوس، جيرانها\nويثرب تعلم أن النبي،\nت عند الهزاهز ذلانها\nمتى ترنا الأوس في بيضنا،\nنهز القنا، تخب نيرانها\nوتعط القياد على رغمها،\nوينزل من الهام عصيانها"},{"id":"diwan-hassan:240","bookId":"diwan-hassan","type":"poem","seq":240,"chapter":"قافية الباء","title":"عنوان القصيدة : إن سرك الغدر صرفا لا مزاج له","page":"ج1 ص238","text":"إن سرك الغدر صرفا لا مزاج له،\nفأت الرجيع، وسل عن دار لحيان\nقوم تواصوا بأكل الجار كلهم،\nفخيرهم، رجلا، والتيس مثلان\nلو ينطق التيس ذو الخصيين وسطهم،\nلكان ذا شرف فيهم وذا شان"},{"id":"diwan-hassan:241","bookId":"diwan-hassan","type":"poem","seq":241,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا أبلغ أبا قيس رسولا","page":"ج1 ص239","text":"ألا أبلغ أبا قيس رسولا،\nإذا ألقى لها سمعا تبين\nنسيت الجسر يوم أبي عقيل،\nوعندك من وقائعنا يقين\nفلست لحاصن إن لم تزركم\nخلال الدور مشعلة طحون\nيدين لها العزيز إذا رآها،\nويهرب من مخافتها القطين\nتشيب الناهد العذراء فيها،\nويسقط من مخافتها الجنين\nبعينيك القواضب حين تعلى\nبها الأبطال والهام السكون\nتجود بأنفس الأبطال سجحا،\nوأنت بنفسك الخب الضنن\nولا وقر بسمعك حين تدعى\nضحى إذ لا تجيب ولا تعين\nألم نترك مآتم معولات،\nلهن على سراتكم رنين\nتشينهم، زعمت، بغير شيء،\nونفسك لو علمت بهم تشين\nقتلتم واحدا من بألف،\nهلا لله ذا الظفر المبين\nوذلك أن ألفكم قليل\nلواحدنا، أجل أيضا ومين\nفلا زلتم، كما كنتم قديما،\nولا زلنا كما كنا نكون\nيطيف بكم من النجار قوم،\nكأسد الغاب، مسكنها العرين\nكأنا، إذ نساميكم رجالا،\nجمال حين يجتلدون جون\nولن ترضى بهذا فاعلموه،\nمعاشر أوس، ما سمع الحنين\nوقد أكرمتكم وسكنت عنكم،\nسراة الأوس، لو نفع السكون\nحياء أن أشاتمكم، وصونا\nلعرضي، إنه حسب سمين\nوأكرمت النساء، وقلت رهطي،\nوهذا حين أنطق، أو أبين"},{"id":"diwan-hassan:242","bookId":"diwan-hassan","type":"poem","seq":242,"chapter":"قافية الباء","title":"عنوان القصيدة : يا راكبا إما عرضت فبلغن","page":"ج1 ص240","text":"يا راكبا إما عرضت فبلغن\nعبد المدان، وجل آل قيان\nقد كنت أحسب أن أصلي أصلكم،\nحتى أمرتم عبدكم، فهجاني\nفتوقعوا سبل العذاب عليكم،\nمما يمر على الروي لساني\nفلأذكرن بني رميمة كلهم\nوبني الحصين بخزية وهوان\nولتعرفن قلائدي برقابكم،\nكالوشم لا تبلى على الحدثان\nأبني الحماس، فما أقول لثلة ،\nترعى البقاع، خبيثة الأوطان\nأين المال، بني الحماس، إذا ذكت\nبهجائكم، متشنعا، نيراني"},{"id":"diwan-hassan:243","bookId":"diwan-hassan","type":"poem","seq":243,"chapter":"قافية الباء","title":"عنوان القصيدة : ألا أبلغ بني الديان عني","page":"ج1 ص241","text":"ألا أبلغ بني الديان عني\nمغلغلة ، ورهط بني قيان\nوأبلغ كل منتخب هواء،\nرحيب الجوف، من عبد المدان\nميامس غزة ، ورماح غاب،\nخفاف، لا تقوم بها اليدان\nتفاقدتم! علام هجوتموني،\nولم أظلم، ولم أخلس بياني"},{"id":"diwan-hassan:244","bookId":"diwan-hassan","type":"poem","seq":244,"chapter":"قافية الباء","title":"عنوان القصيدة : إذا ما ترعرع فينا الغلام","page":"ج1 ص242","text":"إذا ما ترعرع فينا الغلام،\nفما إن يقال له من هوه\nفقالت ثنه: فقال: إذا لم يسد قبل شد الإزار،\nفذلك فينا الذي لا هوه\nولي صاحب من بني الشيصبان،\nفطورا أقول، وطورا هوه"},{"id":"diwan-hassan:245","bookId":"diwan-hassan","type":"poem","seq":245,"chapter":"قافية الباء","title":"عنوان القصيدة : سقتم كنانة جهلا من عداوتكم","page":"ج1 ص243","text":"سقتم كنانة جهلا من عداوتكم،\nإلى الرسول، فجند الله مخزيها\nأوردتموها حياض الموت ضاحية ،\nفالنار موعدها، والقتل لاقيها\nأنتم أحابيش، جمعتم بلا نسب،\nأئمة الكفر، غرتكم طواغيها\nهلا اعتبرتم بخيل الله، إذ لقيت\nأهل القليب، ومن أردينه فيها\nكم من أسير فككناه بلا ثمن،\nوجز ناصية ، كنا مواليها"},{"id":"diwan-hassan:246","bookId":"diwan-hassan","type":"poem","seq":246,"chapter":"قافية الباء","title":"عنوان القصيدة : لو خلق اللؤم إنسانا يكلمهم","page":"ج1 ص244","text":"لو خلق اللؤم إنسانا يكلمهم،\nلكان خير هذيل حين يأتيها\nترى من اللؤم رقما بين أعينهم،\nكما كوى أذرع العانات كاويها\nتبكي القبور، إذا ما مات ميتهم،\nحتى يصيح بمن في الأرض داعيها\nمثل القنافذ تخزى أن تفاجئها،\nشد النهار، ويلقى الليل ساريها"},{"id":"diwan-hassan:247","bookId":"diwan-hassan","type":"poem","seq":247,"chapter":"قافية الباء","title":"عنوان القصيدة : أبلغ هوازن أعلاها وأسفلها","page":"ج1 ص245","text":"أبلغ هوازن أعلاها وأسفلها،\nأن لست هاجيها، إلا بما فيها\nقبيلة ألأم الأحياء أكرمها،\nوأغدر الناس، بالجيران، وافيها\nوشر من يحضر الأمصار حاضرها،\nوشر بادية الأعراب باديها\nتبلى عظامهم إما هم دفنوا\nتحت التراب، ولا تبلى مخازيها\nكأن أسنانهم، من خبث طعمتهم،\nأظفار خاتنة كلت مواسيها"},{"id":"diwan-hassan:248","bookId":"diwan-hassan","type":"poem","seq":248,"chapter":"قافية الباء","title":"عنوان القصيدة : ثوى في قريش، بضع عشرة حجة","page":"ج1 ص246","text":"ثوى في قريش، بضع عشرة حجة ،\nيذكر، لو يلقى خليلا مؤاتيا\nويعرض في أهل المواسم نفسه،\nفلم ير من يؤوي، ولم ير داعيا\nفلما أتانا، واطمأنت به النوى ،\nفأصبح مسرورا، بطيبة ، راضيا\nبذلنا له الأموال من جل مالنا،\nوأنفسنا، عند الوغى ، والتآسيا\nنحارب من عادى من الناس كلهم،\nجميعا، وإن كان الحبيب المصافيا\nونعلم أن الله لا رب غيره،\nوإن كتاب الله أصبح هاديا"},{"id":"diwan-hassan:249","bookId":"diwan-hassan","type":"poem","seq":249,"chapter":"قافية الباء","title":"عنوان القصيدة : أوصى أبونا مالك بوصاية","page":"ج1 ص247","text":"أوصى أبونا مالك بوصاية\nعمرا وعوفا، إذ تجهز غاديا\nبأن اجعلوا أموالكم وسيوفكم\nلأعراضكم ما سلم الله واقيا\nفقلنا له إذ قال ما قال: مرحبا،\nأمرت بمعروف وأوصيت كافيا"}]};